import { UICF } from "../../UIDefined";

export class SequenceCtrl {

    private static _seqList: Sequence[] = [];

    public static update(deltaTime: number): void {
        this._seqList?.forEach(item => {
            item.update(deltaTime);
        });
    }

    public static push(seq: Sequence): void {
        if (this._seqList.indexOf(seq) === -1) {
            this._seqList.push(seq);
        }
    }

    public static remove(seq: Sequence): void {
        const index = this._seqList.indexOf(seq);
        if (index >= 0) {
            this._seqList.splice(index, 1);
        }
    }

    public static pop(): void {
        let seq = this._seqList?.pop();
        seq.clear();
    }

    public static clearAll(): void {
        this._seqList.forEach(seq => seq.clear());
        this._seqList = [];
    }

    public static reset(): void {
        this.clearAll();
    }
}

export class Sequence {

    private _headNode: ActionNode;
    private _tailNode: ActionNode;

    public get isRunning() {
        return this._headNode.isRuning;
    }

    constructor() {
        // SequenceCtrl.push(this);  // 取消注释
    }

    /// <summary>
    /// 添加节点
    /// </summary>
    /// <param name="action">执行当前节点的回调(进入时即执行)</param>
    /// <param name="loop"> loop <= 0 无限循环</param>
    /// <returns></returns>
    private addNode(action: Function, delay: number, loop: number): void {
        if (!this._headNode) {
            // 头节点            
            this._headNode = this._tailNode = new ActionNode(action, delay, loop); //Todo ObjectPool      
        }
        else {
            // 后继节点
            this._tailNode = this._tailNode.nextNode = new ActionNode(action, delay, loop);
        }
    }

    /** 移动到下一个节点 */
    private moveNext(): void {
        if (this._headNode && this._headNode.nextNode) {
            this._headNode = this._headNode.nextNode;
            this._headNode?.start();
        }
    }

    public update(deltaTime: number): void {
        this._headNode?.update(deltaTime, this.moveNext.bind(this));
    }

    /** 先执行 action 再 delay
     * @delay 延时时间 S
     * @loop 0: 无限循环
     */
    public append(action: Function, delay: number = 0, loop: number = 1): Sequence {
        this.addNode(action, delay, loop);
        this._headNode.start();
        return this;
    }

    public stop(): void {
        this._headNode?.stop();
    }

    public pause(): void {
        this._headNode?.pause();
    }

    public resume(): void {
        this._headNode?.resume();
    }

    /** 跳过当前循环中的delay */
    public continue(): void {
        this._headNode?.continue();
    }

    public onUpdate(callback: Function): void {
        this._tailNode?.onUpdate(callback);
    }

    public onComplete(callback: Function): void {
        this._tailNode?.onComplete(callback);
    }

    /** 清空所有节点 */
    public clear(): void {
        let currentNode = this._headNode;
        while (currentNode) {
            currentNode.stop();
            const nextNode = currentNode.nextNode;
            currentNode.nextNode = null;  // 断开链接
            currentNode = nextNode;
        }
        this._headNode = null;
        this._tailNode = null;
        SequenceCtrl.remove(this);  // 取消注释
    }
}

class ActionNode {
    private running: boolean = false;
    private loop: number = 0;      // 循环次数
    private delay: number = 0;      // 停留时长 s
    private tempDelay: number = 0;       // 缓存 runTime 初始值

    private _onStart: Function;       // start
    private _onUpdate: Function;
    private _onComplete: Function;

    public nextNode: ActionNode;

    public get isRuning() {
        return this.running;
    }

    constructor(action: Function, delay: number, loop: number) {
        this.running = false;
        this.delay = delay;
        this.loop = loop;
        this._onStart = action;
    }

    /** 节点计时器, 计时完毕后移动到下一个节点 */
    public update(deltaTime: number, moveNext: Function): void {
        if (this.running) {
            if (this.tempDelay <= 0) {
                this.loop--;
                // 当前节点结束进入下一个节点             
                if (this.loop == 0) {
                    this.running = false;
                    this._onComplete?.call(this);
                    moveNext();         // 移到下个节点并开始
                }
                else {
                    this.running = false;
                    this._onComplete?.call(this);
                    this.start();       // 循环节点
                }
            }
            else {
                this._onUpdate?.call(this);
                this.tempDelay = Math.max(this.tempDelay - deltaTime, 0);
            }
        }
    }

    /** 执行 action 方法 并开启计时器 */
    public start(): void {
        if (!this.running) {
            this.running = true;
            this.tempDelay = this.delay;
            this._onStart?.call(this);
        }
    }

    /** 停止当前节点 */
    public stop(): void {
        if (this.running) {
            this.loop = 1;
            this.tempDelay = 0;
            this.running = false;
        }
    }

    /** 跳过等待, 开始下一个节点 */
    public continue(): void {
        if (this.running) {
            this.tempDelay = 0;
        }
    }

    /** 暂停当前节点 */
    public pause(): void {
        this.running = false;
    }

    /** 继续当前节点 */
    public resume(): void {
        this.running = true;
    }

    public onUpdate(callback: Function): void {
        this._onUpdate = callback;
    }

    /** 节点完成回调 */
    public onComplete(callback: Function): void {
        this._onComplete = callback;
    }
}