import { _decorator, Component, Node, Prefab, instantiate, Vec3, UITransform, tween, sp, UIOpacity, Vec2 } from 'cc';
import { ColorAnimation } from './ColorAnimation';
const { ccclass, property } = _decorator;

@ccclass('StarAniControl')
export class StarAniControl extends Component {
    @property(Prefab)
    bluePrefab: Prefab = null;

    @property(Prefab)
    redPrefab: Prefab = null;

    @property(Prefab)
    yellowPrefab: Prefab = null;

    @property(Node)
    starsContainer: Node = null;

    @property(sp.Skeleton)
    private frameSkeleton: sp.Skeleton | null = null;

    starCount: number = 80;
    newStarInterval: number = 0.5;
    disappearChance: number = 0.3;
    minAnimationDuration: number = 2;
    maxAnimationDuration: number = 5;

    private starPool: Node[] = [];
    private containerRect: { left: number, right: number, top: number, bottom: number } = { left: 0, right: 0, top: 0, bottom: 0 };
    private isAnimationEnding: boolean = false;
    private frameAnimationDuration: number = 0;
    private animationCompletedCount: number = 0;
    private totalAnimations: number = 0;

    start() {
        // console.log("StarAniControl start method called");
        if (this.starsContainer) {
            this.calculateContainerRect();
        } else {
            console.error("Stars container is not set!");
            return;
        }

        if (this.frameSkeleton) {
            this.setupFrameSkeleton();
        }

        // console.log("Stars container found:", this.starsContainer.name);

        this.createInitialStars();
        this.schedule(this.createNewStar, this.newStarInterval);
    }

    setupFrameSkeleton() {
        // console.log("Setting up frameSkeleton");
        // console.log("frameSkeleton parent:", this.frameSkeleton.node.parent?.name);
        // console.log("StarAniControl node:", this.node.name);
        
        if (this.frameSkeleton.node.parent !== this.node) {
            this.node.addChild(this.frameSkeleton.node);
            // console.log("Adjusted frameSkeleton parent to:", this.frameSkeleton.node.parent?.name);
        }
        
        // console.log("frameSkeleton scale:", this.frameSkeleton.node.scale);
        // console.log("frameSkeleton anchor:", this.frameSkeleton.node.getComponent(UITransform)?.anchorPoint);
        
        this.frameSkeleton.node.setScale(1, 1, 1);
        const uiTransform = this.frameSkeleton.node.getComponent(UITransform);
        if (uiTransform) {
            uiTransform.anchorPoint = new Vec2(0.5, 0.5);
        }
        
        this.frameSkeleton.node.setSiblingIndex(0);
        this.frameSkeleton.node.setPosition(0, 221, 0);
        
        this.setupFrameSkeletonAnimation();
    }

    setupFrameSkeletonAnimation() {
        const animationState = this.frameSkeleton.setAnimation(0, 'yuzhongjiang', false);
        this.frameAnimationDuration = animationState.animationEnd - animationState.animationStart;
        
        // 设置动画播放速度为1，确保动画以正常速度播放
        animationState.timeScale = 1;
        
        this.frameSkeleton.setCompleteListener(() => {
            this.isAnimationEnding = true;
            this.unschedule(this.createNewStar);
            this.fadeOutAllStars();
        });
    }

    calculateContainerRect() {
        const uiTransform = this.starsContainer.getComponent(UITransform);
        const containerWorldPos = this.starsContainer.getWorldPosition();
        const anchorPoint = uiTransform.anchorPoint;
        
        const width = uiTransform.width;
        const height = uiTransform.height;

        this.containerRect.left = containerWorldPos.x - anchorPoint.x * width -20;
        this.containerRect.right = this.containerRect.left + width + 20;
        this.containerRect.bottom = containerWorldPos.y - anchorPoint.y * height - 20;
        this.containerRect.top = this.containerRect.bottom + height + 20;
    }

    createInitialStars() {
        for (let i = 0; i < this.starCount; i++) {
            const star = this.getStarFromPool();
            this.resetStar(star);
            this.animateStar(star);
        }
    }

    createNewStar() {
        if (this.starsContainer.children.length < this.starCount && !this.isAnimationEnding) {
            const star = this.getStarFromPool();
            this.resetStar(star);
            this.animateStar(star);
        }
    }

    getStarFromPool(): Node {
        let star: Node = null;
        if (this.starPool.length > 0) {
            star = this.starPool.pop();
        } else {
            star = this.createNewStarInstance();
        }
        return star;
    }

    createNewStarInstance(): Node {
        const prefabs = [this.bluePrefab, this.redPrefab, this.yellowPrefab].filter(p => p != null);
        const randomPrefab = prefabs[Math.floor(Math.random() * prefabs.length)];
        const star = instantiate(randomPrefab);
        this.starsContainer.addChild(star);
        return star;
    }

    getRandomPosition(): Vec3 {
        const padding = 50; // 添加一些内边距
        const x = Math.random() * (this.containerRect.right - this.containerRect.left - 2 * padding) + this.containerRect.left + padding;
        const y = Math.random() * (this.containerRect.top - this.containerRect.bottom - 2 * padding) + this.containerRect.bottom + padding;
        return new Vec3(x, y, 0);
    }

    resetStar(star: Node) {
        const position = this.getRandomPosition();
        star.setWorldPosition(position);
        star.active = true;
        
        // 重置透明度
        const uiOpacity = star.getComponent(UIOpacity) || star.addComponent(UIOpacity);
        uiOpacity.opacity = 255;
    }

    animateStar(star: Node) {
        const colorAnimation = star.getComponent(ColorAnimation);
        if (colorAnimation) {
            colorAnimation.playRandomAnimation();
        }

        const targetPosition = this.getRandomPosition();
        let duration: number;

        if (this.isAnimationEnding) {
            // 如果动画正在结束，使用较短的持续时间
            duration = Math.random() * (this.maxAnimationDuration - this.minAnimationDuration) + this.minAnimationDuration;
        } else {
            // 正常情况下，使用较长的持续时间
            duration = Math.random() * (this.maxAnimationDuration - this.minAnimationDuration) + this.minAnimationDuration;
            // 确保持续时间不超过帧动画的剩余时间
            duration = Math.min(duration, this.frameAnimationDuration);
        }

        tween(star)
            .to(duration, { worldPosition: targetPosition }, { easing: 'sineInOut' })  // 使用 sineInOut 缓动函数使动画更平滑
            .call(() => {
                if (this.isAnimationEnding || Math.random() < this.disappearChance) {
                    this.starPool.push(star);
                    star.active = false;
                } else {
                    this.resetStar(star);
                    this.animateStar(star);
                }
            })
            .start();
    }

    fadeOutAllStars() {
        this.starsContainer.children.forEach((star) => {
            const uiOpacity = star.getComponent(UIOpacity) || star.addComponent(UIOpacity);
            const duration = Math.random() * (this.maxAnimationDuration - this.minAnimationDuration) + this.minAnimationDuration;
            tween(uiOpacity)
                .to(duration, { opacity: 0 }, { easing: 'sineIn' })  // 使用 sineIn 缓动函数使淡出更自然
                .call(() => {
                    this.starPool.push(star);
                    star.active = false;
                })
                .start();
        });
    }

    playAnimation(callback: () => void) {
        // console.log("StarAniControl playAnimation 开始执行");
        
        this.node.active = true;
        // console.log("StarAniControl node active:", this.node.active);
        
        if (this.frameSkeleton && this.frameSkeleton.node) {
            this.frameSkeleton.node.active = true;
            // console.log("frameSkeleton node active:", this.frameSkeleton.node.active);
            this.frameSkeleton.node.setPosition(0, 221, 0);
        } else {
            console.error("frameSkeleton or its node is null");
        }

        this.starsContainer.active = true;
        // console.log("Stars container active:", this.starsContainer.active);
        // console.log("Number of stars in container:", this.starsContainer.children.length);

        this.animationCompletedCount = 0;
        this.totalAnimations = this.starCount;

        // console.log("Starting to create and animate stars");
        for (let i = 0; i < this.starCount; i++) {
            const star = this.getStarFromPool();
            // console.log(`创建第 ${i + 1} 个星星，活动状态: ${star.active}`);
            this.resetStar(star);
            // console.log(`重置第 ${i + 1} 个星星，位置: ${star.getWorldPosition()}`);
            
            this.animateStarWithCallback(star, () => {
                this.animationCompletedCount++;
                
                if (this.animationCompletedCount >= this.totalAnimations) {
                    // console.log("所有星星动画完成，调用回调函数");
                    callback();
                }

                this.starPool.push(star);
                star.active = false;
            });
        }
    }

    private animateStarWithCallback(star: Node, callback: () => void) {
        // console.log("animateStarWithCallback 开始执行");
        const colorAnimation = star.getComponent(ColorAnimation);
        if (colorAnimation) {
            colorAnimation.playRandomAnimation();
        }

        const targetPosition = this.getRandomPosition();
        const duration = Math.max(0.1, Math.random() * (this.maxAnimationDuration - this.minAnimationDuration) + this.minAnimationDuration);

        // console.log(`星星动画开始，持续时间: ${duration}秒，初始位置: ${star.getWorldPosition()}, 目标位置: ${targetPosition}`);
        
        tween(star)
            .to(duration, { worldPosition: targetPosition }, { easing: 'sineInOut' })
            .call(() => {
                // console.log("单个星星动画完成");
                callback();
            })
            .start();
    }

    public reset() {
        // console.log("重置 StarAniControl");
        this.isAnimationEnding = false;
        this.animationCompletedCount = 0;
        this.totalAnimations = 0;

        this.starPool.forEach(star => {
            star.active = false;
        });
        
        this.starsContainer.children.forEach(star => {
            star.active = false;
            this.starPool.push(star);
        });

        if (this.frameSkeleton) {
            this.frameSkeleton.node.active = false;
            this.setupFrameSkeletonAnimation();
        } else {
            console.error("frameSkeleton is not set!");
        }

        this.calculateContainerRect();
    }
}
