/** 游戏数据定义 (包括游戏数据的配置) */
export class GameDataDefine {
    //不同游戏的字段定义不同,随游戏逻辑进行'增删改'
    /** 百搭id列表 */
    public static wildIdList: number[] = [];
    /** 分散id列表 */
    public static scatterIdList: number[] = [];
    /** 图标id列表_免费游戏 (包含wild和scatter) */
    public static iconIds_FreeGame: number[] = [];

    public static ResetFilters = [];

    /** 初始化游戏数据定义 */
    public static initGameDataDefine() {
        let iconMap = RES.getRes(RES.resConfig.IconConfig);
        Config.setIconConfigs(iconMap.json);
        let lineConf = RES.getRes(RES.resConfig.LineConfig);
        Config.setLineConfigs(lineConf.json);
        let config = Config.getIconConfig();
        for (let key in config) {
            let iconCfg = config[key];
            //包含"组合百搭"
            if (iconCfg.isWild) {
                this.wildIdList.push(iconCfg.iconId);
            }
            if (iconCfg.iconType == Enum_IconType.Scatter) {
                this.scatterIdList.push(iconCfg.iconId);
            }
            //免费游戏
            if (iconCfg.iconType == Enum_IconType.Scatter) {
                this.iconIds_FreeGame.push(iconCfg.iconId);
            }
        }
        LogUtil.debug("GameDataDefine", "this.wildIdList", this.wildIdList);
        LogUtil.debug("GameDataDefine", "this.scatterIdList", this.scatterIdList);
    }

    /** 是否属于百搭图标 */
    public static isBelongsToWild(iconId: number): boolean {
        return this.wildIdList.indexOf(iconId) >= 0;
    }

    /** 是否属于分散图标 */
    public static isBelongsToScatter(iconId: number): boolean {
        return this.scatterIdList.indexOf(iconId) >= 0;
    }

    /** 是否属于免费游戏 */
    public static isBelongsToFreeGame(iconId: number): boolean {
        return this.iconIds_FreeGame.indexOf(iconId) >= 0;
    }

    /** jackpot 奖励数据 */
    public static quickhitDefine = [
        {reward:5},
        {reward:10},
        {reward:25},
        {reward:50},
        {reward:100},
        {reward:250},
        {reward:750},
        {reward:2000}
    ];

    public static quickhitLvData = [
        {reward:5,   count:5,   id:1},
        {reward:10,  count:6,   id:2},
        {reward:25,  count:7,   id:3},
        {reward:50,  count:8,   id:4},
        {reward:100, count:9,   id:5},
        {reward:250, count:10,  id:6},
        {reward:750, count:11,  id:7},
        {reward:2000,count:12,  id:8}
    ];
    /** rapidhit累计数量 */
    public static rapidhitCount = 0;
}

