export interface LineConfig {
    lineId: number;
    lineArray: number[];
    rate: number;
    color: string;
    sound: string;
}

export interface GridPosition {
    row: number;
    col: number;
}

export class LineConfigGenerator {
    private readonly colors = [
        "#05A280", "#DDDD00", "#27C422", "#F02625", 
        "#A628B9", "#0066FF", "#FF6600"
    ];

    // 基础模式数据
    private readonly basePatterns = {
        // 51-60的基础模式
        pattern51To60: [
            [1, 5, 9, 13, 17],
            [1, 6, 11, 14, 17],
            [3, 6, 9, 14, 19],
            [2, 5, 9, 13, 18],
            [1, 6, 10, 14, 17],
            [1, 5, 10, 15, 19],
            [3, 7, 10, 13, 17],
            [2, 5, 10, 13, 18],
            [1, 6, 9, 14, 17],
            [1, 6, 10, 14, 19]
        ],
        // 101-110的基础模式
        pattern101To110: [
            [1, 10, 19, 28, 37],
            [1, 11, 21, 29, 37],
            [3, 11, 19, 29, 39],
            [2, 10, 19, 28, 38],
            [1, 11, 20, 29, 37],
            [1, 10, 20, 30, 39],
            [3, 13, 22, 28, 37],
            [2, 10, 20, 28, 38],
            [1, 11, 19, 29, 37],
            [1, 11, 20, 29, 39]
        ]
    };

    // 将数字转换为网格位置
    private numberToPosition(num: number, gridWidth: number): GridPosition {
        return {
            row: Math.ceil(num / gridWidth),
            col: ((num - 1) % gridWidth) + 1
        };
    }

    // 将网格位置转换为数字
    private positionToNumber(pos: GridPosition, gridWidth: number): number {
        return (pos.row - 1) * gridWidth + pos.col;
    }

    // 转换单个连线配置到新的网格大小
    private convertLineArray(lineArray: number[], fromWidth: number, toWidth: number): number[] {
        return lineArray.map(num => {
            const pos = this.numberToPosition(num, fromWidth);
            return this.positionToNumber(pos, toWidth);
        });
    }

    // 生成基础配置（1-50）
    private generateBasicConfigs(gridWidth: number): LineConfig[] {
        const configs: LineConfig[] = [];
        // 这里实现基础配置的生成逻辑
        // ...
        return configs;
    }

    // 生成额外模式配置（51-60, 101-110等）
    private generatePatternConfigs(
        basePattern: number[][], 
        startId: number, 
        fromWidth: number, 
        toWidth: number
    ): LineConfig[] {
        return basePattern.map((pattern, index) => ({
            lineId: startId + index,
            lineArray: this.convertLineArray(pattern, fromWidth, toWidth),
            rate: 1,
            color: this.colors[index % this.colors.length],
            sound: ""
        }));
    }

    // 生成完整配置
    public generateConfig(
        targetGridWidth: number, 
        includePatterns: boolean = true
    ): Record<string, LineConfig> {
        const config: Record<string, LineConfig> = {};
        
        // 生成基础配置（1-50）
        const basicConfigs = this.generateBasicConfigs(targetGridWidth);
        basicConfigs.forEach(cfg => {
            config[cfg.lineId.toString()] = cfg;
        });

        if (includePatterns) {
            // 生成51-60的配置
            const pattern51Configs = this.generatePatternConfigs(
                this.basePatterns.pattern51To60, 
                51, 
                4, // 原始网格宽度
                targetGridWidth
            );
            pattern51Configs.forEach(cfg => {
                config[cfg.lineId.toString()] = cfg;
            });

            // 生成101-110的配置
            const pattern101Configs = this.generatePatternConfigs(
                this.basePatterns.pattern101To110, 
                101, 
                9, // 原始网格宽度
                targetGridWidth
            );
            pattern101Configs.forEach(cfg => {
                config[cfg.lineId.toString()] = cfg;
            });
        }

        return config;
    }

    // 添加新的模式
    public addNewPattern(
        pattern: number[][], 
        startId: number, 
        fromWidth: number, 
        toWidth: number
    ): LineConfig[] {
        return this.generatePatternConfigs(pattern, startId, fromWidth, toWidth);
    }
}
