import { _decorator, Component, Node, Label, Sprite, Animation, Vec3, tween, UIOpacity, sp } from 'cc';
import { Utils } from '../../utils/Utils';

const { ccclass, property } = _decorator;

@ccclass('QuickLevelNode')
export class QuickLevelNode extends Component {
    @property(Label)
    curLevelLab: Label = null;

    @property(Sprite)
    currentSprite: Sprite = null;

    @property(Node)
    blitzIcon: Node = null;

    @property(Label)
    symbolCountLabel: Label = null;

    @property(Node)
    spinRemainIcon: Node = null;

    @property(Label)
    spinCountLabel: Label = null;

    @property(Sprite)
    upgradeSprite: Sprite = null;

    @property(Sprite)
    lastSpinSprite: Sprite = null;

    @property(Sprite)
    titleSprite: Sprite = null;

    @property(Sprite)
    winnerSprite: Sprite = null;


    @property({ type: sp.Skeleton, visible: true })
    private animation: sp.Skeleton = null;

    public level: number = 0;
    private maxSpins: number = 3;
    private usedSpins: number = 0;
    private reward: number = 0;
    private rewordsToNextLevel: number[] = [560.4, 700.5, 1401, 3502.5, 7005, 14010, 35025, 105075, 280200];
    private symbolsToNextLevel: number[] = [0, 5, 10, 15, 20, 30, 40, 55, 70, 85];
    
    private readonly BASE_OFFSET = 200; // 基础偏移量
    private readonly OFFSET_INCREMENT = 10; // 每级增加的偏移量

    private currentSymbolCount: number = 0;


    onLoad() {
    }

    start() {
        this.spinCountLabel.string = "3";
    }

    update(deltaTime: number) {
        
    }

    setLevel(level: number, maxSpins: number = 3) {
        this.level = level;
        this.maxSpins = maxSpins;
        this.usedSpins = 0;
        this.reward = 0;
        this.currentSymbolCount = this.symbolsToNextLevel[this.level + 1];
    
        this.updateUI();
        this.adjustElementPositions();
    }

    private updateUI() {
        // console.log("updateUI============this.rewordsToNextLevel[this.level]:", this.rewordsToNextLevel[this.level]);
        // console.log("updateUI============this.symbolsToNextLevel[this.level]:", this.symbolsToNextLevel[this.level]);
        // this.curLevelLab.string = `Level ${this.level}`;
        this.curLevelLab.string = this.rewordsToNextLevel[this.level]+"";
        this.symbolCountLabel.string = this.symbolsToNextLevel[this.level+1]+"";
        // console.log("updateUI============this.symbolCountLabel.string:", this.symbolCountLabel.string);
        this.spinCountLabel.string = `${this.maxSpins}`;
        // console.log("updateUI============this.spinCountLabel.string:", this.spinCountLabel.string);
        // 更新其他UI元素...
    }

    public adjustElementPositions() {
        const offset = this.BASE_OFFSET + (this.level * this.OFFSET_INCREMENT);
        // console.log(`Adjusting positions for level ${this.level}, offset: ${offset}`);
    
        // 调左侧元素
        if (this.currentSprite && this.blitzIcon && this.upgradeSprite) {
            this.currentSprite.node.setPosition(new Vec3(-offset, this.currentSprite.node.position.y, 0));
            this.blitzIcon.setPosition(new Vec3(-offset, this.blitzIcon.position.y, 0));
            this.upgradeSprite.node.setPosition(new Vec3(-offset, this.upgradeSprite.node.position.y, 0));
            // console.log(`Left elements adjusted to x: -${offset}`);
        }
    
        // 调整右侧元素
        if (this.spinRemainIcon && this.lastSpinSprite) {
            this.spinRemainIcon.setPosition(new Vec3(offset, this.spinRemainIcon.position.y, 0));
            this.lastSpinSprite.node.setPosition(new Vec3(offset, this.lastSpinSprite.node.position.y, 0));
            // console.log(`Right elements adjusted to x: ${offset}`);
        }
    }

    public showAnimation(level: number, status: boolean = true, isPlaySound: boolean = true) {
        if (!this.animation) {
            console.error("Animation component is not initialized in QuickLevelNode");
            return;
        }
        // Ensure the skeleton animation node is visible
        const skeletonNode = this.animation.node;
        if (skeletonNode) {
            skeletonNode.active = true;
        }
    
        const animationName = "kuang" + level;
        // console.log("Attempting to play animation:", animationName);
        
        // Check if the animation exists
        if (this.animation.findAnimation(animationName)) {
            // console.log("Playing animation:", animationName);
            this.animation.setAnimation(0, animationName, status);
            // Play the corresponding collection sound effect based on the level
            // Delay sound playback by 2 seconds
            // this.scheduleOnce(() => {
            //     this.playCollectionSound(level, isPlaySound);
            // }, 3);
        } else {
            console.warn("Animation not found:", animationName);
            // console.log("Available animations:", this.getAvailableAnimations());
        }
    }
    
    private playCollectionSound(level: number, isPlaySound: boolean) {
        // console.log("playCollectionSound============level:", level, "isPlaySound:", isPlaySound);
        if (!isPlaySound) {
            return;
        }   

        const soundMap = {
            1: "qhb_fg_jpu_collect_10",
            2: "qhb_fg_jpu_collect_15",
            3: "qhb_fg_jpu_collect_20",
            4: "qhb_fg_jpu_collect_30",
            5: "qhb_fg_jpu_collect_40",
            6: "qhb_fg_jpu_collect_55",
            7: "qhb_fg_jpu_collect_70",
            8: "qhb_fg_jpu_collect_70"
        };
        const soundEffect = soundMap[level];
        if (soundEffect) {
            Utils.playEffectNew(soundEffect);
        }
    }
    
    private getAvailableAnimations(): string[] {
        if (!this.animation || !this.animation.skeletonData) return [];
        
        const animations: string[] = [];
        const possibleAnimations = [
            "kuang1", "kuang2", "kuang3", "kuang4", "kuang5", 
            "kuang6", "kuang7", "kuang8"
        ];
    
        for (const animName of possibleAnimations) {
            if (this.animation.findAnimation(animName)) {
                animations.push(animName);
            }
        }
    
        return animations;
    }

    public stopAnimation() {
        if (!this.animation) {
            console.error("Animation component is not initialized in QuickLevelNode");
            return;
        }
        
        const skeletonNode = this.animation.getComponent(sp.Skeleton);
        if (skeletonNode) {
            skeletonNode.setAnimation(0, null, false);
            skeletonNode.node.active = false;
        }
    }

    public hideAnimation() {
        // this.animation.node.active = false;
    }

    public hideSpineAnimation(duration: number = 0.5) {
        if (this.animation) {
            const skeletonNode = this.animation.node;
            if (skeletonNode) {
                // 获取或添加 UIOpacity 组件
                let uiOpacity = skeletonNode.getComponent(UIOpacity);
                if (!uiOpacity) {
                    uiOpacity = skeletonNode.addComponent(UIOpacity);
                }

                // 创建渐隐动画
                tween(uiOpacity)
                    .to(duration, { opacity: 0 })
                    .call(() => {
                        skeletonNode.active = false;
                        // 重置透明度，以便下次显示时是完全不透明的
                        uiOpacity.opacity = 255;
                    })
                    .start();
            }
        }
    }

    public incrementUsedSpins() {
        if (this.usedSpins < this.maxSpins) {
            this.usedSpins++;
            this.updateUI();
        }
    }

    public showCurLevelLab() {
        if (this.curLevelLab) {
            this.curLevelLab.node.active = true;
        }
    }

    public hideCurLevelLab() {
        if (this.curLevelLab) {
            this.curLevelLab.node.active = false;
        }
    }

    public showUpgradeSprite() {
        if (this.upgradeSprite) {
            this.upgradeSprite.node.active = true;
        }
    }

    public hideUpgradeSprite() {
        if (this.upgradeSprite) {
            this.upgradeSprite.node.active = false;
        }
    }

    public showCurrentSprite() {
        if (this.currentSprite) {
            this.currentSprite.node.active = true;
        }
    }

    public hideCurrentSprite() {
        if (this.currentSprite) {
            this.currentSprite.node.active = false;
        }
    }

    public showBlitzIcon() {
        if (this.blitzIcon) {
            this.blitzIcon.active = true;
        }
    }

    public hideBlitzIcon() {
        if (this.blitzIcon) {
            this.blitzIcon.active = false;
        }
    }

    public showSpinRemainIcon() {
        if (this.spinRemainIcon) {
            this.spinRemainIcon.active = true;
        }
        if (this.spinCountLabel) {
            this.spinCountLabel.node.active = true;
        }
    }

    public hideSpinRemainIcon() {
        if (this.spinRemainIcon) {
            this.spinRemainIcon.active = false;
        }
    }

    public showLastSpinSprite() {
        if (this.lastSpinSprite) {
            this.lastSpinSprite.node.active = true;
        }
    }

    public hideLastSpinSprite() {
        if (this.lastSpinSprite) {
            this.lastSpinSprite.node.active = false;
        }
    }

    public showTitleSprite() {
        if (this.titleSprite) {
            this.titleSprite.node.active = true;
        }
    }

    public hideTitleSprite() {
        if (this.titleSprite) {
            this.titleSprite.node.active = false;
        }
    }

    public showWinnerSprite() {
        if (this.winnerSprite) {
            this.winnerSprite.node.active = true;
    
            // 确保节点有 UIOpacity 组件
            let uiOpacity = this.winnerSprite.node.getComponent(UIOpacity);
            if (!uiOpacity) {
                uiOpacity = this.winnerSprite.node.addComponent(UIOpacity);
            }
    
            // 停止可能正在进行的其他动画
            tween(this.winnerSprite.node).stop();
    
            // 创建闪烁动作
            const fadeOut = tween(uiOpacity).to(0.15, { opacity: 0 });
            const delay = tween().delay(0.5);
            const fadeIn = tween(uiOpacity).to(0.3, { opacity: 255 });
            const blinkSequence = tween().sequence(fadeOut,delay,fadeIn);
            const blinkRepeat = tween(uiOpacity).repeatForever(blinkSequence);
    
            // 应用闪烁动作
            blinkRepeat.start();
    
            // console.log("Winner sprite blink animation started");
        } else {
            console.warn("Winner sprite is not set");
        }
    }

    public hideWinnerSprite() {
        if (this.winnerSprite) {
            this.winnerSprite.node.active = false;
        }
    }

    public showAllElements() {
        this.showUpgradeSprite();
        this.showCurrentSprite();
        this.showBlitzIcon();
        this.showSpinRemainIcon();
        this.showLastSpinSprite();
        this.showTitleSprite();
        this.showWinnerSprite();
    }

    public hideAllElements() {
        this.hideUpgradeSprite();
        this.hideCurrentSprite();
        this.hideBlitzIcon();
        this.hideSpinRemainIcon();
        this.hideLastSpinSprite();
        this.hideTitleSprite();
        this.hideWinnerSprite();
    }

    public addReward(amount: number) {
        this.reward += amount;
        // 更新奖励显示
    }

    public moveToBottom(duration: number =  0.85, yOffset: number = -355, scale: number = 0.65) {
        const startPosition = this.node.position.clone();
        const middlePosition = new Vec3(startPosition.x, yOffset/2, 0); // 假设中间位置的 Y 坐标为 0
        const bottomPosition = new Vec3(startPosition.x, yOffset, 0);
        const targetScale = new Vec3(scale, scale, 1);
        // console.log("============moveToBottom============", startPosition, middlePosition, bottomPosition, targetScale);
    
        const halfDuration = duration;
        const pauseDuration = 0.5; // 停顿时间，可以根据需要调整

        this.hideAllElements();
        this.showCurrentSprite();


        this.playCollectionSound(this.level, true);

        tween(this.node)
            // 第一阶段：移动到中间位置
            .to(halfDuration, {
                position: middlePosition
            }, {
                easing: 'sineOut' // 使用 sineOut 缓动效果使移动变慢
            })
            .call(() => {
                // 播放当前 Jackpot 下降音效
                Utils.playEffectNew("qhb_fg_jpu_crntjackdrop");
            })
            // 停顿
            .delay(pauseDuration)
            // 第二阶段：移动到底部位置并缩放
            .to(halfDuration, {
                position: bottomPosition,
                scale: targetScale
            }, {
                easing: 'sineIn' // 使用 sineIn 缓动效果使移动加速
            })
            .call(() => {
                // 播放当前 Jackpot 落地音效
                Utils.playEffectNew("qhb_fg_jpu_crntjackland");
            })
            .start();
    }

    public fadeOut(duration: number = 0.85) {
        const uiOpacity = this.node.getComponent(UIOpacity);
        if (!uiOpacity) {
            this.node.addComponent(UIOpacity);
        }

        const startPosition = this.node.position.clone();
        const endPosition = new Vec3(startPosition.x, startPosition.y - 500, startPosition.z);

        tween(this.node)
            .to(duration, {
                position: endPosition
            }, {
                easing: 'cubicOut'
            })
            .start();

        tween(uiOpacity)
            .to(duration, { opacity: 0 })
            .call(() => this.node.active = false)
            .start();
    }

    public isLevelCompleted(): boolean {
        // 实现level完成的判断逻辑
        return false;
    }

    public updateSymbolCount(symbolCount: number) {
        console.log("updateSymbolCount============symbolCount:", symbolCount);
        // 计算距离下一个等级还需要的symbolCount
        const targetSymbolCount = this.symbolsToNextLevel[this.level];
        this.currentSymbolCount = Math.max(0, targetSymbolCount - symbolCount);
        console.log("this.currentSymbolCount:", this.currentSymbolCount);
        this.updateSymbolCountLabel(this.currentSymbolCount);
    }

    

    private updateSymbolCountLabel(count: number) {
        console.log(`[QuickLevelNode] Updating symbol count label - Level: ${this.level}, Remaining Count: ${count}`);
        if (this.symbolCountLabel) {
            this.symbolCountLabel.string = count.toString();
            console.log(`[QuickLevelNode] Symbol count label updated to: ${count}`);
        } else {
            console.warn('[QuickLevelNode] symbolCountLabel is null');
        }
    }

    public updateSpinCountLabel(count: number) {
        console.log(`[QuickLevelNode] Updating spin count label - Level: ${this.level}, Count: ${count}`);
        if (this.spinCountLabel) {
            this.spinCountLabel.string = count.toString();
            console.log(`[QuickLevelNode] Spin count label updated to: ${count}`);
        } else {
            console.warn('[QuickLevelNode] spinCountLabel is null');
        }
    }

    public updateRewordsToNextLevel(newRewards: number[]) {
        // console.log("updateRewordsToNextLevel============newRewards:", newRewards);
        // console.log("this.rewordsToNextLevel :", this.rewordsToNextLevel.length);
        // console.log("this.newRewards:", newRewards.length);
        if (newRewards.length === this.rewordsToNextLevel.length) {
            this.rewordsToNextLevel = newRewards;
        } else {
            console.warn("New rewards array length does not match the existing one.");
        }
        // console.log("this.rewordsToNextLevel:", this.rewordsToNextLevel);
    }

    public degreeCurrentSymbolCount() {
        if (this.currentSymbolCount > 0) {
            this.currentSymbolCount--;
            console.log("degreeCurrentSymbolCount:", this.currentSymbolCount);
            this.updateSymbolCountLabel(this.currentSymbolCount);
            return true;
        }
        return false;
    }
}
