    /**
     * 设置押注索引
     * @param betIndex 索引
     */
    public setBetIndex(betIndex: number) {
        let betCount = GameCommonModel.getInstance().betList.length;
        console.log("setBetIndex GameCommonModel.getInstance().betList",GameCommonModel.getInstance().betList);
        if (betCount <= 0) {
            Log.e("bet list count is zero");
            return;
        }
        if (betIndex < 0) {
            betIndex = betCount - 1;
        }
        if (betIndex >= betCount) {
            betIndex = 0;
        }

        GameCommonModel.getInstance().curBetIndex = betIndex;
        this.updateBet();
    }

    public updateBet() {
        let curBet = GameCommonModel.getInstance().curBet;
        let line = this.model.curBetLine;
        let bet = curBet * line * this.model.betRate;
        let score = GamesData.formatScore(bet, false);
        let buyScore = GamesData.formatScore(bet * Config.buyGaneBet, false);
        this.lab_bet.string = score;
        if(this.lab_buy)
            this.lab_buy.string = buyScore;
        let money = GameCommonModel.getInstance().money;
        LogUtil.log("=====updateBet==curBet= curBetIndex ==", GameCommonModel.getInstance().curBet, ", bet = ", bet, ", curBetIndex = ", GameCommonModel.getInstance().curBetIndex, ", score = ", score, ", betRate = ", this.model.betRate);
        LogUtil.log("updateBet curBet ==", curBet, "bet ==", bet, "line ==", line);
        
        if (this.btn_buyGame) {
            if (money < bet * Config.buyGaneBet) {
                this.btn_buyGame.interactable = false;
            } else {
                this.btn_buyGame.interactable = true;
            }
        }
        // this.setQuickHitLvData(curBet);
    }

