    protected _addEvent() {
        this.btn_start.touchEndedFun = this.onStart.bind(this);
        this.btn_stop.touchEndedFun = this.onStop.bind(this);

        this.btn_autostart.getComponent(UIButton).touchEndedFun = this.onAutoStart.bind(this);
        this.btn_autostop.getComponent(UIButton).touchEndedFun = this.onAutoStop.bind(this);

        if (this.btn_bet_add) {
            this.btn_bet_add.touchEndedFun = this.onBetClick.bind(this);
        }
        if (this.btn_bet_dec) {
            this.btn_bet_dec.touchEndedFun = this.onBetClick.bind(this);
        }
        if (this.btn_buyGame) {
            this.btn_buyGame.touchEndedFun = this.onBuyGame.bind(this);
        }

        if (this.btn_menu) {
            this.btn_menu.touchEndedFun = this.onMenu.bind(this);
            this.btn_menu.touchBeganFun = this.onMenuBegan.bind(this);
            this.btn_menu.touchCancelFun = this.onMenuCancel.bind(this);
        }
        if (this.helpBtn) {
            this.helpBtn.touchEndedFun = this.onHelp.bind(this);
        }
        if (this.soundBtn) {
            this.soundBtn.touchEndedFun = this.onSound.bind(this);
        }
        if (this.backBtn) {
            this.backBtn.touchEndedFun = this.onBack.bind(this);
        }

        this.model.mainViewAddMoneyFun = this.addMoney.bind(this);

        //协议
        Eventer.getInstance().on(GameEventType.OnReceiveBalance, this._updateBalance, this);

    }

    protected removeFromStage() {

        Eventer.getInstance().offName(GameEventType.OnReceiveBalance, this);

        let mLanguage: string = GamesData.getGameLanguageStr();
        let path = `resources/texture/language/${mLanguage}/languageTexture/GAMEWIN/spriteFrame`;
        if (this.gameWinTitle && this.gameWinTitle.spriteFrame) {
            this.gameWinTitle.spriteFrame.decRef();
            this.gameWinTitle.spriteFrame = null;
        }
        CacheManager.getInstance().remove(BUNDLE_NAME.rollCommon, path);

        path = `resources/texture/language/${mLanguage}/languageTexture/yue/spriteFrame`;
        if (this.moneyTitle && this.moneyTitle.spriteFrame) {
            this.moneyTitle.spriteFrame.decRef();
            this.moneyTitle.spriteFrame = null;
        }
        CacheManager.getInstance().remove(BUNDLE_NAME.rollCommon, path);

        this.model.mainViewAddMoneyFun = null;
    }


    public getWinPos():Vec3{
        return this.curWinNode.worldPosition;
    }

    /**
     * 提示文本
     * 是否是feature模式
     * @param isFeature 
     */
    private _setRuleTipRun(isFeature:boolean = false){
        let tipFree = this.tipsNode.getChildByName("freeTip");
        let tipFeature = this.tipsNode.getChildByName("featureTip");
        tipFree.active = !isFeature;
        tipFeature.active = isFeature;
        Tween.stopAllByTarget(tipFree);
        Tween.stopAllByTarget(tipFeature);

        let showNode = tipFree;
        if(isFeature){
            showNode = tipFeature;
        }

        let width = showNode.parent?.getComponent(UITransform)!.width;
        let width1 = showNode.getComponent(UITransform)!.width;
        let mt = 1000;
        let ex = -310;
        if(width){
            ex = -width/2 - width1/2;
            mt = (width + width1) / 0.11;
        }
        tween(showNode).to(mt / 1000, { position: new Vec3(ex) })
        .call(() => {
            showNode.setPosition(new Vec3(-ex));
        })
        .union()
        .repeatForever()
        .call(() => {
        })
        .start();
    }



