    // 添加新方法来获取动画序列的总时长
    public setFeatureAutoRollDuration(): void {
        console.log('getAnimationDuration');
        if(!this._slotGame || this._type != GameType.Feature) return;
    
        if (this._slotGame) {
            this._slotIcons = this._slotGame.getAllIcon();
        }
    
        // 计算基础动画时长
        let totalDuration = 0;
        
        // 设置中奖线数据的时长
        totalDuration += 0.5;
        
        // 显示所有中奖线的时长
        totalDuration += 3;
        
        // 计算 QuickHit 动画时长
        if (this._type === GameType.Feature) {
            const quickHitIcons = this._slotIcons.filter(icon => 
                icon && (icon.id === QuickHit_Syboml || icon.id === QuickHit_Syboml_Feature)
            );
            
            // 计算需要播放的动画数量（不超过目标数量）
            const animationsToPlay = Math.min(
                this._targetQuickHitCount - this._currentQuickHitCount, 
                quickHitIcons.length
            );
            // 如果这是最后一个动画,额外加1秒时间
            if (this._currentQuickHitCount + animationsToPlay === this._targetQuickHitCount) {
                totalDuration += 1.5;
            }
            
            // 只计算到最后一个需要播放的动画的时间
            totalDuration += animationsToPlay * 0.3;
        }
        
        // 添加额外的缓冲时间
        totalDuration += 1.5;
    
        LogUtil.debug(`[LineControl] featureAutoRollTimeDelay Animation sequence started at: [${new Date().toISOString()}], duration: ${totalDuration}`);
        this._slotGame.featureAutoRollTimeDelay = totalDuration;
    }

    // 添加新的方法来设置 QuickHit 计数
    public setQuickHitCount(current: number, target: number): void {
        this._currentQuickHitCount = current;
        this._targetQuickHitCount = target;
        LogUtil.debug(`[LineControl] Set QuickHit counts - Current: ${current}, Target: ${target}`);
    }

    // 添加新的方法来播放最后一个 QuickHit 的特殊动画
    private playLastQuickHitAnimation(): void {
        LogUtil.debug('[LineControl] Playing last QuickHit special animation');
        // 播放特殊音效金色星星
        Utils.playEffectNew("qhb_fg_blitzsymbol_jpuflip");

    }
