import { PhysicMaterial, Vec2, _decorator, } from 'cc';
import { Scatter_Syboml, QuickHit_Syboml, Liang, XiaoHe, HanXin, LiuBang, RowCount, Wild_Special, Wild_Normal } from '../../Config';
import { MapData } from '../../GameDataDefine';
const { ccclass, property } = _decorator;

export class GameUtility {


    /** 是否进入免费游戏
     *  scatterCount >= 3
     */
    public static isEnterFeature(map: number[]): boolean {
        if (!map || map.length == 0) return false;
        return map.filter((item) => item == Scatter_Syboml).length >= 3;
    }
    /**
         * 剩余免费牌面数量
         * @description 中断重连后，游戏在免费游戏，获取剩余的免费游戏剩余牌面数量（不包括后续免费中免费）
         */
    public static freeGameTime(maps: MapData[]) {
        let time = 0;
        for (let key in maps) {
            let map = maps[key].map;
            time += this.freeCount(map);
        }
        return time;
    }
    /**是否有后续凤凰火**/
    public static haveFire(maps: MapData[]) {
        let time = 0;
        for (let key in maps) {
            let map = maps[key].map;
            time += this.isWild(map);
        }
        return time > 0;
    }
    public static isWild(map) {
        if (!map || map.length == 0) return false;
        return map.filter((item) => item == Wild_Normal).length
    }
    public static isEnterSpecial(map: number[]): boolean {
        if (!map || map.length == 0) return false;
        return map.filter((item) => item == Wild_Special).length >= 1;
    }

    public static isPhoenix(id: number): boolean {
        return id >= 6 && id <= 10; // 6, 7, 8. 9. 10
    }

    public static isAllPhoenix(map: number[]): number {
        let count: number = 0;
        let phoenix: { [key: number]: number } = {};
        // let phoenixes = new Set<number>(); // 打包后数据异常
        for (let index = 0; index < map.length; index++) {
            let iconId = map[index];
            if (this.isPhoenix(iconId)) {
                if (iconId != Wild_Normal) {
                    // phoenixes.add(iconId);
                    phoenix[iconId] = 1;
                }
                count++;
            }
        }
        if (count == 25) {
            if (Object.keys(phoenix).length == 1) {
                return Number(Object.keys(phoenix)[0]);
                // return ([...phoenixes])[0];
            }
            else {
                return 13;
            }
        }
        return -1;
    }

    /**
     *由图标计算的免费游戏轮数
     */
    public static freeCount(map: number[]): number {
        let scatterCount = map.filter(item => item == Scatter_Syboml).length;
        switch (scatterCount) {
            case 6: return 10;
            case 8: return 15;
            case 10: return 20;
            default: return 0;
        }
    }

    public static specialCount(map: number[]): number {
        return 1;
    }

    /** 获取表面行列坐标  x: col; y: row 
    * 0 3 6  9 12
    * 1 4 7 10 13
    * 2 5 8 11 14
    */
    public static getIconCoord(index: number): Vec2 {
        let col = Math.floor(index / RowCount);
        let row = index - col * RowCount;
        return new Vec2(col, row);
    }

    /**
     * value 以 amount 为增量累加接近但不超过 target
     */
    public static approch(value: number, target: number, amount: number): number {
        return value > target ? Math.max(value - target, target) : Math.min(value + amount, target);
    }

    public static lerp(a: number, b: number, t: number): number {
        return a + (b - a) * this.clamp(t, 0, 1);
    }

    /**
     * 返回 value 的符号
     * @param value 
     * @returns 
     */
    public static sign(value: number): number {
        return value > 0 ? 1 : value < 0 ? -1 : 0;
    }

    public static abs(value: number): number {
        return value > 0 ? value : -value;
    }

    /**
     * 50%概率返回true
     */
    public static maybe(): boolean {
        return Math.random() < 0.5;
    }

    /**
     * 范围[min, max]
     */
    public static random(min: number, max: number): number {
        let range = max - min;
        let random = Math.random();
        return min + Math.round(random * range);
    }

    /**
     * 范围[min, max] && 不包括exclude
     */
    public static randomEx(min: number, max: number, exclude: number,): number {
        let ans = this.random(min, max);
        if (ans == exclude) ans = this.randomEx(min, max, exclude);
        return ans;
    }

    /**
     * 范围 a <= value <= b
     */
    public static clamp(value: number, a: number, b: number): number {
        return Math.max(a, Math.min(value, b));
    }

    public static contains<T extends object>(dic: T, key): boolean {
        return key in dic;
    }
}

