import { _decorator, Component, Label, Node, NodeEventType } from 'cc';
import { UIButton } from '../../../../scripts/framework/ui/basic_ui/UIButton';
import { Eventer } from '../../../../scripts/framework/Eventer';
import { GameEventType } from '../../../gamesCommon/script/GameEventType';
import { Config } from '../Config';
import { ScreenType, UIView } from '../../../../scripts/framework/ui/UIView';
import { GameCommonModel } from '../../../gamesCommon/script/GameCommonModel';
import { RollCommonModel } from '../../../rollCommon/script/RollCommonModel';
import GamesData from '../../../gamesCommon/script/GamesData';
import { Global } from '../../../../scripts/main/Global';
import { RollComUtils } from '../../../rollCommon/script/utils/RollComUtils';
import { Utils } from '../utils/Utils';
const { ccclass, property } = _decorator;

@ccclass('BuyGameCom')
export class BuyGameCom extends UIView {
    @property(Label)
    private score: Label;
    @property(UIButton)
    private cancal_btn: UIButton;
    @property(UIButton)
    private check_btn: UIButton;
    @property(Node)
    private mask: Node;
    @property(Node)
    private controller: Node;

    start() {
        RollComUtils.closeFuncUI()
        this.initBtns();
    }

    init() {
        // Utils.playSound("buy")
        this.onScreenSwitch()
        let model = RollCommonModel.getInstance();
        let curBet = GameCommonModel.getInstance().curBet;
        let line = model.curBetLine;
        let bet = curBet * line * model.betRate * Config.buyGaneBet;
        let score = GamesData.formatScore(bet, false);
        this.scoreStr = score;


    }
    private onScreenSwitch() {
        if (Global.gameScreenType == ScreenType.Landscape)
            this.controller.angle = 0;
        else
            this.controller.angle = 90;
    }

    public initBtns(): void {
        // this.node.active = false;
        this.onEven();
    }

    protected onEven() {
        this.cancal_btn.touchEndedFun = this.hide.bind(this);
        this.check_btn.touchEndedFun = this.onBuyGame.bind(this);
        this.mask.on(NodeEventType.TOUCH_END, this.hide, this);
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    private offEvent(): void {
        // this.mask && this.mask.off(NodeEventType.TOUCH_END, this.hide, this);
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }

    protected onDestroy(): void {
        this.offEvent();
    }
    protected onBuyGame(): void {
        Config.inBuyGame = true;
        Eventer.getInstance().emit(GameEventType.RollStart);
        this.hide();
    }

    protected hide(): void {
        this.close();
        // this.node.active = false;
    }
    public set scoreStr(str: string) {
        this.score.string = Config.getPrefix() + str;
    }

}

