@ccclass('GameAudioManager')
export default class GameAudioManager extends Component {
    private static _instance: GameAudioManager = null!;
    private _soundEnabled: boolean = true;
    private _audioSoundArr: AudioSource[] = [];
    private _audioSound: AudioSource = null;
    private _soundDictionary: Dictionary<SoundConfig>
    public static Instance() {
        return this._instance;
    }

    start() {
        this._soundDictionary = new Dictionary<SoundConfig>();
        this._audioSound = this.node.addComponent(AudioSource);
        Eventer.getInstance().on(Config.changeSound, this._changeSound, this);
    }

    private _changeSound(data: any): void {
        this._soundEnabled = data;
    }

    public playGameSound(name: string, loop: boolean = false, volume: number = 1): AudioSource {
        if (!this._soundEnabled) return;
        let path = `resources/audio/game/${name}`;

        let aud = new Resource(path, AudioClip);
        let data = RES.getRes(aud, AudioClip);
        // let sound = this.getSound(name);
        // if (sound) {

        // } else {
        //     sound.clip = data;
        // }
        // let sound = data;
        this._audioSound.clip = data;
        // this._audioSound.play();
        this._audioSound.playOneShot(data, volume);
        this._audioSound.loop = loop;
        this._addSoundInDic(name, this._audioSound);
        //Log.e("soundName==", name);
        return this._audioSound;
    }

    public setSoundClip(name: string): AudioSource {
        let path = `resources/audio/game/${name}`;
        let aud = new Resource(path, AudioClip);
        let data = RES.getRes(aud, AudioClip);
        this._audioSound.clip = data;
        return this._audioSound
    }

    public playSoundClip(name: string, loop: boolean = false, volume: number = 1): AudioSource {
        let path = `resources/audio/game/${name}`;
        let aud = new Resource(path, AudioClip);
        let data = RES.getRes(aud, AudioClip);
        this._audioSound.clip = data;
        this._audioSound.loop = loop;
        // this._audioSound.playOneShot(data, volume);
        this._addSoundInDic(name, this._audioSound);
        return this._audioSound;
    }

    public playSound(key: string, url: string, loop: boolean, bundleName: string = Macro.BUNDLE_RESOURCES, volume: number = 1): AudioSource {
        if (!this._soundEnabled) return;
        ResManager.Instance().load(Global.gameId + "", url, AudioClip, () => { }, (evt: any) => {
            // this._audioSound = evt.data;
            //this._audioSound.playOneShot(evt.data, volume);
            if (evt.data) {
                this._audioSound.clip = evt.data;
                this._audioSound.play();
                this._audioSound.loop = loop;
                this._addSoundInDic(key, this._audioSound);
               // Log.e("音效资源", this._audioSound);
                return this._audioSound;
            } else {
              //  Log.e("音效资源为空");
            }
        });

        // assetManager.loadBundle(
        //     bundleName,
        //     (error: Error, bundle: AssetManager.Bundle) => {
        //         if (!error) {
        //             bundle.load(
        //                 url,
        //                 AudioClip,
        //                 null,
        //                 (error: any, clip: AudioClip) => {
        //                     if (!error) {

        //                         this._addSoundInDic(key, this._audioSound);
        //                         //this._audioSound.clip = clip;
        //                         //this._audioSound.play();
        //                         this._audioSound.playOneShot(clip, volume);
        //                         Log.e("playSound");
        //                         return this._audioSound;
        //                         // this._audioSoundArr.push(this._audioSound);
        //                         // this._addSoundInDic(key, this._audioSource);
        //                         //Log.e("_audioSource==", this._audioSound);
        //                     } else {
        //                         Log.w(error);
        //                     }
        //                 }
        //             );
        //         } else {
        //             Log.w(error);
        //         }
        //     }
        // );
    }

    private _addSoundInDic(name: string, audio: AudioSource): void {
        let sound = this._soundDictionary.get(name);
        if (sound) {

        } else {
            let soundConfig: SoundConfig = new SoundConfig();
            soundConfig.audio = audio;
            soundConfig.soundName = name;
            this._soundDictionary.set(name, soundConfig)
        }
    }

    public getSound(type: string | AudioSource): AudioSource {
        if (typeof type === "string") {
            let sound = this._soundDictionary.get(type);
            if (!sound) {
                return;
            }
            return sound.audio;
        } else {
            for (let key in this._soundDictionary.values) {
                let value = this._soundDictionary.values[key];
                if (value && value.audio === type) {
                    return value.audio;
                }
            }
        }
    }

    /**对应音效名或者音效 */
    public stopSound(type: string | AudioSource) {
        if (typeof type === "string") {
            let sound = this._soundDictionary.get(type);
            if (!sound) {
                return;
            }
            sound.audio.stop();
            this._soundDictionary.remove(type);
        } else {
            for (let key in this._soundDictionary.values) {
                let value = this._soundDictionary.values[key];
                // let sound = this._soundDictionary.get(type);
                if (value && value.audio === type) {
                    value.audio.stop();
                    //let name = this._soundDictionary[key].name;
                    this._soundDictionary.remove(value.soundName);
                }
            }
        }
    }

    public stopAllSounds(): void {
        for (let key in this._soundDictionary.values) {
            let value = this._soundDictionary.values[key];
            if (value) {
                value.audio.stop();
                this._soundDictionary.remove(value.soundName);
            }
        }
    }



}

export class SoundConfig {
    public soundName: string = "";
    public audio: AudioSource = null;
}


