import { _decorator, Component, Sprite, SpriteFrame } from 'cc';
import { ResManager } from '../../../../../../scripts/framework/manager/ResManager';
import { RES } from '../../../Config';
import LogUtil from '../../../../../../scripts/common/utils/LogUtil';
const { ccclass, property } = _decorator;

enum State {
    None = 0,
    Playing,
    Paused,
}

@ccclass('FrameAnimation')
export class FrameAnimation extends Component {

    private _loop: number;
    private _rate: number;
    private _speed: number;
    @property({ type: Number, visible: true })
    private _timer: number = 0;

    private _preFrame: number = -1; // 上一帧
    private _curFrame: number = 0;  // 当前帧
    private _stayFinalFrame: boolean = false;    // 最终停留在最后一帧

    private _state: State;
    private _sprite: Sprite;
    private _frameClip: FrameClip;
    private _frameDic: { [key: string]: FrameClip };

    public onCompleted: Function;

    public set stayFinalFrame(value: boolean) {
        this._stayFinalFrame = value;
    }

    public get frameLength(): number {
        return this._frameClip.length;
    }

    protected onLoad(): void {
        this._frameDic = {};
        this._sprite = this.getComponent(Sprite);
    }

    protected update(deltaTime: number): void {
        this.updateFrame(deltaTime);
    }

    public get playing(): boolean {
        return this._state == State.Playing;
    }

    public isPlaying(clip: FrameClip): boolean {
        return this.playing && this._frameClip && this._frameClip == clip;
    }

    public addClip(key: string, clip: FrameClip): void {
        this._frameDic[key] = clip;
    }

    public removeClip(key: string): void {
        if (this.contains(key)) {
            this._frameDic[key].release();
            delete this._frameDic[key];
        }
    }

    public play(key: string, speed: number = 1, loop: number = 1): void {
        let clip = this._frameDic[key];
        if (clip) {
            this._loop = loop;
            this._speed = speed;
            if (!this.isPlaying(clip)) {
                this._rate = clip.fps;
                this._frameClip = clip;
                this._state = State.Playing;
                this.setFrame(0);
            }
        }
    }

    public stop(): void {
        this._state = State.Paused;
        if (this._frameClip) {
            this.setFrame(this._stayFinalFrame ? this.frameLength - 1 : 0);
        }
        if (this.onCompleted) this.onCompleted.call(this);
    }

    public getFrame(index: number) {
        return this._frameClip.frames[index];
    }

    public setFrame(index: number) {
        if (this._preFrame != index) {
            let curSprite = this.getFrame(index);
            this._sprite.spriteFrame = curSprite;
            this._preFrame = index;
        }
    }

    private setFrameByTime(time: number): void {
        this._timer = Math.floor(time % this.frameLength);
        this._curFrame = this._timer;
        this.setFrame(this._curFrame);
        this._preFrame = this._curFrame;
    }

    private updateFrame(deltaTime: number): void {
        if (this._state != State.Playing) {
            return;
        }
        this._timer += this._rate * this._speed * deltaTime;
        this._curFrame = Math.floor(this._timer);
        if (this._curFrame >= this.frameLength) {
            this._loop--;
            if (this._loop == 0) {
                // stoped
                this._timer = 0;
                this._state = State.Paused;
                this._curFrame = this.frameLength - 1;
                this.setFrame(this._stayFinalFrame ? this._curFrame : 0);
                if (this.onCompleted) {
                    this.onCompleted.call(this);
                }
            }
            else {
                // loop
                this._timer = 0;
                this._preFrame = -1;
                this._curFrame = 0;
                this.setFrame(this._curFrame);
            }
        }
        else {
            // playing
            this.setFrame(this._curFrame);
        }
    }

    private contains(key: string): boolean {
        if (!this._frameDic) return false;
        return key in this._frameDic;
    }
}

export class FrameClip {
    public fps: number;
    public length: number;
    public frames: SpriteFrame[] = [];

    public constructor(path: string, name: string, fps: number, length: number = 1) {
        this.fps = fps;
        this.length = length;
        this.loadFrames(path, name, length);
    }

    public loadFrames(path: string, name: string, length: number): void {
        for (let i = 0; i < length; i++) {
            // let url = path + `/${name}${i}`;
            let url = path + `/${name}${i}/spriteFrame`;
            LogUtil.log(`FrameAnimation.ts:106 | url: ${url}`);
            ResManager.Instance().load(RES.bundleName, url, SpriteFrame, () => { }, (evt: any) => {
                LogUtil.log(`FrameAnimation.ts:111 | evt: ${evt}`);
                this.frames[i] = evt.data;
                LogUtil.log(`FrameAnimation.ts:111 | evt: ${ evt.data }`);
            });
        }
    }

    public release(): void {
        this.length = 0;
        this.frames = null;
    }
}
