import { _decorator, Component, Node, Sprite, Label, SpriteAtlas, Vec3, NodeEventType, sp, find, Font, tween } from "cc";
import GamesData from "../../../../gamesCommon/script/GamesData";
import { Config, RES } from "../../Config";
import { Sequence, SequenceCtrl } from "../other/SequenceCtrl";
import { Eventer } from "../../../../../scripts/framework/Eventer";
import { GameEventType } from "../../../../gamesCommon/script/GameEventType";
import { ScreenType } from "../../../../../scripts/framework/ui/UIView";
import { Global } from "../../../../../scripts/main/Global";
import { RollComUtils } from "../../../../rollCommon/script/utils/RollComUtils";
import { Utils } from "../../utils/Utils";


const { ccclass, property } = _decorator;

@ccclass('TipsController')
export class TipsController extends Component {

    private static _instance: TipsController;

    // tips
    @property({ type: Node, visible: true })
    private _btmNode: Node;
    private _btmLabel: Label;
    // touch
    @property({ type: Node, visible: true })
    private _touchNode: Node;
    // pop
    @property({ type: Node, visible: true })
    private _popNode: Node;
    private _popSke: sp.Skeleton;

    private _jieSuanSke: sp.Skeleton;
    public _index: number;
    public canShow: boolean;
    public canTouch: boolean;

    public hideCallback: Function;

    private jieSuanNode: Node;
    private mianBanNode: Node;
    public static get instance() {
        return TipsController._instance;
    }

    protected onLoad(): void {
        TipsController._instance = this;
    }

    public init(): void {
        this._btmLabel = this._btmNode.getChildByName("Label").getComponent(Label);

        this.jieSuanNode = this._popNode.getChildByName("jieSuan");
        this.mianBanNode = this._popNode.getChildByName("mianban");
        this._popSke = this._popNode.getChildByName("youWinSke").getComponent(sp.Skeleton);
        this._jieSuanSke = this._popNode.getChildByName("jieSuanSke").getComponent(sp.Skeleton);
        this._touchNode = this._popNode.getChildByName("TouchNode");
        this._popNode.active = false;
        this.canShow = true;
        this.canTouch = true;
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    private onScreenSwitch(): void {
        let scale = Global.gameScreenType == ScreenType.Landscape ? 1 : 0.85;
        this.node.setScale(new Vec3(scale, scale, scale));
        let pos = Global.gameScreenType == ScreenType.Landscape ? new Vec3(0, -230, 0) : new Vec3(0, -270, 0)
        this._btmNode.setPosition(pos);
    }

    /** 底部游戏提示 */
    public setBottomTips(key: string, params?: any[]): void {
        if (key == "") {
            this._btmLabel.string = "";
        } else {
            this._btmLabel.string = GamesData.replaceString(Config.getText(key), params);
        }
    }

    onDestroy() {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }

    /**
    * 0: remind
    * 1: reward
    */
    public showScrollsPop(index?: number, score?: number): void {
        if (!this.canShow) return;
        RollComUtils.closeFuncUI()
        this.canTouch = false;
        this._popNode.active = true;
        let labelNode = find("/mianban", this._popNode).getChildByName("Label");
        let spriteNode = find("/mianban", this._popNode).getChildByName("Sprite");
        this.jieSuanNode.active = true;
        this.playAppearTween();
        this._jieSuanSke.node.active = true;
        labelNode.active = false;
        spriteNode.active = false;
        this._popSke.node.active = true;
        let tip_0 = this.jieSuanNode.getChildByName("tip_0");
        let tip_1 = this.jieSuanNode.getChildByName("tip_1");
        let tubiao = this.jieSuanNode.getChildByName("tubiao");
        tip_0.active = true;
        tip_1.active = true;
        tubiao.active = true;
        // index = 2;
        // score = 1000;
        // this.jieSuanNode.active = false;
        switch (index) {
            case 0:
                this._popSke.node.active = false;
                tubiao.active = false;
                tip_0.active = false;
                tip_1.active = true;
                tip_1.getComponent(Sprite).spriteFrame = RES.getFrom<SpriteAtlas>("BackgroundAtlas").getSpriteFrame("font_you_win");
                tip_1.position = new Vec3(0, 37, 0);
                this._index = 0;
                labelNode.active = true;
                labelNode.position = new Vec3(-192.71, 11.278, 0);
                labelNode.getComponent(Label).font = RES.getFrom<Font>("RedFont");
                labelNode.getComponent(Label).string = score.toString();
                spriteNode.active = true;
                let free_games = RES.getFrom<SpriteAtlas>("BackgroundAtlas").getSpriteFrame("free_games");
                spriteNode.getComponent(Sprite).spriteFrame = free_games;
                let seq = new Sequence();
                SequenceCtrl.push(seq);
                Utils.playSound("window")
                seq.append(() => {
                    this._jieSuanSke.setAnimation(0, "Appear", false);
                }, 1, 1)
                    .append(() => {
                        this._jieSuanSke.setAnimation(0, "Loop", false);
                        // SequenceCtrl.remove(seq);
                    }, 1, 1)
                    .append(() => {
                        this._jieSuanSke.setAnimation(0, "Disappear", false);
                        tip_1.active = false;
                        labelNode.active = false;
                        spriteNode.active = false;
                        this.hideCallback?.call(this);
                        SequenceCtrl.remove(seq);
                    });

                break;
            case 1:
                tip_0.active = false;
                tubiao.active = false;
                this._popSke.node.active = false;
                this._index = 1;
                spriteNode.active = false;
                labelNode.active = true;
                Utils.playSound("congratulations")
                labelNode.position = new Vec3(0, 4, 0);
                labelNode.getComponent(Label).font = RES.getFrom<Font>("YellowFont");
                labelNode.getComponent(Label).string = Config.getPrefix() + GamesData.formatScore(score);
                this._jieSuanSke.setAnimation(0, "Appear", false);
                this._jieSuanSke.setCompleteListener(track => {
                    this._jieSuanSke.setCompleteListener(null);
                    this._jieSuanSke.setAnimation(0, "Loop", true);
                });
                this._touchNode.on(NodeEventType.TOUCH_END, this.onTouch, this);
                break;
            case 2:
                // 凤凰蛋奖
                tubiao.active = false;
                this._jieSuanSke.node.active = false;
                this.jieSuanNode.active = false;
                this._index = 2;
                Utils.playSound("transition")
                this._popSke.setAnimation(0, "ani", false);
                break;
            default: break;
        }
    }
    /**中断重连调整tips的位置*/
    public setTips1Pos() {
        let tip_1 = this.jieSuanNode.getChildByName("tip_1");
        tip_1.position = new Vec3(0, 37, 0);
    }

    /** 全屏凤凰奖提示 */
    public showScrollsPop2(index: number, score: number): void {
        if (!this.canShow) return;
        this.jieSuanNode.active = true;
        this.playAppearTween();
        this._jieSuanSke.node.active = true;
        this._index = 2;
        this.canTouch = false;
        this._popNode.active = true;
        let labelNode = find("/mianban", this._popNode).getChildByName("Label");
        let spriteNode = find("/mianban", this._popNode).getChildByName("Sprite");
        let tip_0 = this.jieSuanNode.getChildByName("tip_0");
        tip_0.active = true;
        let tip_1 = this.jieSuanNode.getChildByName("tip_1");
        tip_1.active = true;
        tip_1.getComponent(Sprite).spriteFrame = RES.getFrom<SpriteAtlas>("BackgroundAtlas").getSpriteFrame("font_you_win2");
        tip_1.position = new Vec3(155, 37, 0);
        let iconNode = this.jieSuanNode.getChildByName("tubiao");
        spriteNode.active = false;
        iconNode.active = true;
        labelNode.active = true;
        let atlas = RES.getFrom<SpriteAtlas>("IconAtlas");
        let key = `icon${index}_0`;
        iconNode.getComponent(Sprite).spriteFrame = atlas.getSpriteFrame(key);
        labelNode.position = new Vec3(0, 20, 0);
        labelNode.getComponent(Label).font = RES.getFrom<Font>("YellowFont");
        labelNode.getComponent(Label).string = GamesData.formatScore(score);
        this._jieSuanSke.setAnimation(0, "Appear", false);
        this._jieSuanSke.setCompleteListener(track => {
            this._jieSuanSke.setCompleteListener(null);
            this._jieSuanSke.setAnimation(0, "Loop", true);
        });
        this._touchNode.on(NodeEventType.TOUCH_END, this.onTouch, this);
    }

    public hideScrollPop(): void {
        this._touchNode.off(NodeEventType.TOUCH_END, this.onTouch, this); //防止隐藏过程中再次点击
        this.playHideTween();

        if (this._index == 1) {
            this._jieSuanSke.setAnimation(0, "Disappear", false);
            this._jieSuanSke.setCompleteListener(track => {
                this._jieSuanSke.setCompleteListener(null);
                this._popNode.active = false;
                this.hideCallback?.call(this);
            });
        } else {
            this._jieSuanSke.setAnimation(0, "Disappear", false);
            this._jieSuanSke.setCompleteListener(track => {
                this._jieSuanSke.setCompleteListener(null);
                this.jieSuanNode.getChildByName("tubiao").active = false;;
                this._popNode.active = false;
                this.hideCallback?.call(this);
            });
        }
    }

    private playHideTween(): void {
        let jieSuanPos = this.jieSuanNode.position;
        tween(this.jieSuanNode).to(0.17, { scale: new Vec3(1.1, 1.1, 1.1) }).to(0.1, { position: new Vec3(jieSuanPos.x, jieSuanPos.y + 10, jieSuanPos.z) })
            .to(0.17, { scale: new Vec3(0, 0, 0) }).start();

        let mianBanPos = this.mianBanNode.position;
        tween(this.mianBanNode).to(0.17, { scale: new Vec3(1.1, 1.1, 1.1) }).to(0.1, { position: new Vec3(mianBanPos.x, mianBanPos.y + 10, mianBanPos.z) })
            .to(0.1, { scale: new Vec3(0, 0, 0) }).start();

    }

    private playAppearTween(): void {
        this.jieSuanNode.position = new Vec3(18, -5, 0);
        this.jieSuanNode.scale = new Vec3(0, 0, 0);
        let jieSuanPos = this.jieSuanNode.position;
        tween(this.jieSuanNode).to(0.3, { scale: new Vec3(1.2, 1.2, 1.2) }).to(0.13, { scale: new Vec3(0.9, 0.9, 0.9) })
            .to(0.1, { scale: new Vec3(1.1, 1.1, 1.1) }).to(0.1, { scale: new Vec3(1, 1, 1) }).start();

        this.mianBanNode.position = new Vec3(0, -114, 0);
        this.mianBanNode.scale = new Vec3(0, 0, 0);
        let mianBanPos = this.mianBanNode.position;
        tween(this.mianBanNode).to(0.3, { scale: new Vec3(1.2, 1.2, 1.2) }).to(0.13, { scale: new Vec3(0.9, 0.9, 0.9) })
            .to(0.1, { scale: new Vec3(1.1, 1.1, 1.1) }).to(0.1, { scale: new Vec3(1, 1, 1) }).start();

    }

    private onTouch(evt) {
        if (this.canTouch) {
            this.hideScrollPop();
            Log.d("tips onTouch");
        }
    }
    /**
     * reward_start : jiesuan-tanchu
     * reward_loop  : jiesuan-xunhuan
     * reward_end   : jiesuan-jieshu
     * 
     * remind_start : chufa-tanchu
     * remind_end   : chufa-jieshu
     * 
     * allWin_start : deifentishi-tanchu
     * allWin_loop  : deifentishi-xunhuan
     * allWin_end   : deifentishi-jieshu
     */
}

