import { _decorator, Component, Node, sp, tween, Tween } from 'cc';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { Events } from '../../../../../scripts/framework/Events';
import { Global } from '../../../../../scripts/main/Global';
import { ScreenType } from '../../../../../scripts/framework/ui/UIView';
import { GameComUtils } from '../../../../gamesCommon/script/utils/GameComUtils';
const { ccclass, property } = _decorator;

@ccclass('GameIntroComp')
export class GameIntroComp extends Component {

    @property(Node)
    logo: Node;

    @property(sp.Skeleton)
    effAdpage: sp.Skeleton;

    @property(Node)
    heng: Node;

    @property(Node)
    shu: Node;

    private _logoPos = {
        'landscape': { x: 0, y: 208 },
        'portrait': { x: 0, y: 478 }
    }

    start() {
        this.addToStage();
        this.changeScreen();
    }

    update(deltaTime: number) {

    }

    private changeScreen() {
        let contentNode: Node = this.node;
        let pos = this._logoPos[Global.gameScreenType];
        this.logo.setPosition(pos.x, pos.y);
        let pressTip = null
        if (Global.gameScreenType == ScreenType.Portrait) {
            contentNode.angle = 90;
            this.heng.active = false;
            this.shu.active = true;
            GameComUtils.asyncSkeletonTrackTime(this.effAdpage, 'ani_ver');
            pressTip = this.shu.getChildByName("fh_hb_jiazaixiamian")
        } else {
            contentNode.angle = 0;
            this.heng.active = true;
            this.shu.active = false;
            GameComUtils.asyncSkeletonTrackTime(this.effAdpage, 'ani_hor');
            pressTip = this.heng.getChildByName("fh_hb_jiazaixiamian")
        }
        Tween.stopAllByTarget(pressTip);
        GameComUtils.fadeInOutTween(pressTip, 1, 255, 1, 0)
    }

    protected addToStage() {
        Eventer.getInstance().on(Events.ScreenSwitchEvent, this.changeScreen, this);
    }

    protected onDestroy(): void {
        Eventer.getInstance().offName(Events.ScreenSwitchEvent, this);
    }
}