import { _decorator, Component, Node, Vec3, Label, Sprite, find, SpriteAtlas, tween, UITransform } from 'cc';
import BanditControl from './BanditControl';
import { BoardCount, RES } from '../../Config';
import TileControl from './TileControl';
import { GameType } from '../../net/ServerProxy';
import { MapData } from '../../GameDataDefine';
import ReelControl from './ReelControl';
import { Utils } from '../../utils/Utils';
import { Config } from "../../Config";
import AudioManager from '../../../../../scripts/framework/manager/AudioManager';

const { ccclass, property } = _decorator;

@ccclass('SlotGame')
export class SlotGame extends Component {

    private static _instance: SlotGame;

    @property({ type: BanditControl, visible: true })
    public slotBand: BanditControl;

    @property({ type: Node, visible: true })
    private _roundGroup: Node;
    private _roundNum_L: Label;
    private _roundTex_L: Sprite;

    public static get instance(): SlotGame {
        return this._instance;
    }

    protected onLoad(): void {
        SlotGame._instance = this;

        this._roundGroup = find("/RoundGroup", this.node);
        if (this._roundGroup) { 
            this._roundNum_L = this._roundGroup.getChildByPath("Round_L/Label").getComponent(Label);
            this._roundTex_L = this._roundGroup.getChildByPath("Round_L/Sprite").getComponent(Sprite);
        }
    }

    private _initialRowCount: number = 3;
    private _initialColCount: number = 5;




    // 添加 normal 普通模式配置
    // "每个图标之间的垂直距离（像素）" })
    public iconDistance: number = 99;

    // "老虎机滚动的速度（像素/秒）" })
    public rollSpeed: number = 1500;

    // "老虎机停止时的反弹速度（像素/秒）" })
    public boundSpeed: number = 1000;

    // "每列开始滚动的时间间隔（秒）" })
    public spinStartInterval: number = 0.2;

    // "每列停止的时间间隔（秒）" })
    public spinStopInterval: number = 0.05;

    // "整个滚动过程的持续时间（秒）" })
    public totalSpinDuration: number = 1; // 调整这个值以匹配你期望的总旋转时间

    // "滚动停止时的缓动持续时间（秒）" })
    public stopEasingDuration: number = 0.15;

    // 添加 feature 模式配置
    // "Feature 模式下每个图标之间的垂直距离（像素）" })
    public featureIconDistance: number = 99;

    // "Feature 模式下老虎机滚动的速度（像素/秒）" })
    public featureRollSpeed: number = 1800;

    // "Feature 模式下老虎机停止时的反弹速度（像素/秒）" })
    public featureBoundSpeed: number = 1000;

    // "Feature 模式下每列开始滚动的时间间隔（秒）" })
    public featureSpinStartInterval: number = 0.2;

    // "Feature 模式下每列停止的时间间隔（秒）" })
    public featureSpinStopInterval: number = 0.05;

    // "Feature 模式下整个滚动过程的持续时间（秒）" })
    public featureTotalSpinDuration: number = 1.5;

    // "Feature 模式下滚动停止时的缓动持续时间（秒）" })
    public featureStopEasingDuration: number = 0.15;

    // "feature 模式下老虎机没有升级时，自动滚动下一次的时间间隔（秒）" })
    private _featureAutoRollTimeDelay: number = 5;

    public get featureAutoRollTimeDelay(): number {
        return this._featureAutoRollTimeDelay;
    }

    public set featureAutoRollTimeDelay(value: number) {
        this._featureAutoRollTimeDelay = Math.max(value, 1); // 确保至少有1秒的延迟
    }

    private lastSoundPlayTime: number = 0;
    private soundInterval: number = 0.1; // 最小音效播放间隔，单位秒

    public init(rowCount: number = 3, colCount: number = 5, isFeature: boolean = false): void {
        this._initialRowCount = rowCount;
        this._initialColCount = colCount;
        this.slotBand.init(
            rowCount, 
            colCount, 
            isFeature ? this.featureIconDistance : this.iconDistance, 
            isFeature ? this.featureRollSpeed : this.rollSpeed,
            isFeature ? this.featureBoundSpeed : this.boundSpeed,
            isFeature ? this.featureTotalSpinDuration : this.totalSpinDuration
        );
    }

    public startSpin(down: boolean, useBlur: boolean, type: GameType, mapData?: MapData): void {
        const isFeature = type === GameType.Feature;
        if (isFeature && mapData) {
            const totalSymbols = mapData.map.length;
            const newColCount = 5; // 假设列数固定为5
            const newRowCount = totalSymbols / newColCount;
            console.log("startSpin totalSymbols newRowCount newColCount: ", totalSymbols, newRowCount, newColCount);

            if (newRowCount !== this.slotBand.rowCount || newColCount !== this.slotBand.colCount) {
                this.init(newRowCount, newColCount, true);
            }
        } else if (type === GameType.Normal) {
            if (this.slotBand.rowCount !== this._initialRowCount || this.slotBand.colCount !== this._initialColCount) {
                this.init(this._initialRowCount, this._initialColCount, false);
            }
        }

        AudioManager.Instance().stopAllEffect();

        // 播放 Reel 旋转的背景音乐
        this.playSoundNew("qhb_bg_reelspin");

        this.slotBand.startSpin(
            down, 
            useBlur, 
            isFeature,
            isFeature ? this.featureSpinStartInterval : this.spinStartInterval
        );
    }

    public adjustSlotPosition(): void {
        const slotBandNode = this.slotBand.node;
        const uiTransform = slotBandNode.getComponent(UITransform);
        if (!uiTransform) {
            console.error('UITransform component not found on slotBand node.');
            return;
        }
        // 打印当前的宽高和位置
        console.log("Current slotBand dimensions:", {
            width: uiTransform.width,
            height: uiTransform.height,
            position: slotBandNode.position
        });
        // 计算新的高度和位置
        const iconHeight = 100; // 假设每个图标高度为105
        const newHeight = this.slotBand.rowCount * iconHeight;
        const yOffset = -130;
        console.log("Adjusting slotBand:", {
            rowCount: this.slotBand.rowCount,
            newHeight: newHeight,
            yOffset: yOffset
        });
        // 使用 tween 创建缓动效果
        tween(slotBandNode)
            .to(0.5, { 
                position: new Vec3(0, yOffset, 0)
            }, { easing: 'cubicOut' })
            .call(() => {
                // 在回调中调整高度
                uiTransform.height = newHeight;
                // 打印调整后的宽高和位置
                console.log("Adjusted slotBand dimensions:", {
                    width: uiTransform.width,
                    height: uiTransform.height,
                    position: slotBandNode.position
                });
            })
            .start();
    }

    public stopSpin(mapData: MapData, type: GameType): void {
        const board = this.convertMapDataToBoard(mapData);
        const result = this.slotBand.convertBoardToResult(board);
        const isFeature = type === GameType.Feature;
        this.slotBand.stopSpin(
            result, 
            isFeature ? this.featureSpinStopInterval : this.spinStopInterval, 
            isFeature ? this.featureStopEasingDuration : this.stopEasingDuration
        );

        // 播放普通线-中奖音效
        this.playSoundNew("qhb_bg_cr_small_stop");
    }

    public stopSpin_force(mapData: MapData, type: GameType): void {
        const board = this.convertMapDataToBoard(mapData);
        const result = this.slotBand.convertBoardToResult(board);
        const isFeature = type === GameType.Feature;
        this.slotBand.stopSpin_force(result);

        // 播放普通线-中奖音效
        this.playSoundNew("qhb_bg_cr_small_stop");
    }

    public setIcons(mapData: MapData): void {
        const board = this.convertMapDataToBoard(mapData);
        const scores = mapData.score || [];
        console.log("Setting icons with board data:", board);
        this.slotBand.setIcons(board, Array.isArray(scores) ? scores : [scores]);

        // 检查是否有 Scatter 出现
        let scatterCount = board.filter(icon => icon === 9).length; // 假设 9 是 Scatter 的 ID
        if (scatterCount > 0) {
            // 播放 Scatter 出现音效
            const scatterSound = `qhb_bg_ant_${Math.min(scatterCount, 3)}`;
            this.playSoundNew("qhb_bg_cr_small_stop");
        }
    }

    public getIcon(row: number, col: number): TileControl {
        return this.slotBand.getIcon(row, col);
    }

    public getAllIcon(): TileControl[] {
        console.log(`Retrieved getAllIcon icons`);
        const icons = this.slotBand.getAllIcon();
        return icons;
    }

    public getIconPos(index: number): Vec3 {
        return this.slotBand.getIconPos(index);
    }

    public getIconPos2(index: number): Vec3 {
        return this.slotBand.getIconPos2(index);
    }

    public isSpinStopped(): boolean {
        return !this.slotBand.spinning;
    }
    public isSpinStart(): boolean {
        return this.slotBand.spinning;
    }

    public showAllIcon(light: boolean): void {
        for (let row = 0; row < this.getRowCount(); row++) {
            for (let col = 0; col < this.getColCount(); col++) {
                let icon = this.getIcon(row, col);
                icon.stopIcon();
                // icon.dim(!light);
            }
        }
    }

    public initRound(count: number): void {
        this._roundGroup.active = true;
        this._roundNum_L.node.active = true;
        this._roundTex_L.node.position = new Vec3(-39, 0, 0);
        this._roundTex_L.spriteFrame = RES.getFrom<SpriteAtlas>("BackgroundAtlas").getSpriteFrame("s_free_spin");
        this.updateRound(count);
    }

    public updateRound(round: number): void {
        if (round == -1) {
            this._roundNum_L.node.active = false;
            this._roundTex_L.node.position = new Vec3(0, 0, 0);
            this._roundTex_L.spriteFrame = RES.getFrom<SpriteAtlas>("BackgroundAtlas").getSpriteFrame("final_spin");
        } else {
            this._roundNum_L.string = round.toString();
        }
    }

    public showSpecialRound(): void {
        this._roundGroup.active = true;
        this._roundNum_L.node.active = false;
        this._roundTex_L.node.position = new Vec3(0, 0, 0);
        this._roundTex_L.spriteFrame = RES.getFrom<SpriteAtlas>("BackgroundAtlas").getSpriteFrame("reborn_respin_3");
    }

    public clearRound(): void {
        this._roundGroup.active = false;
    }

    private convertMapDataToBoard(mapData: MapData): number[] {
        // Assuming mapData.board is already in the correct format
        return mapData.map;
    }

    public getReels(): ReelControl[] {
        return this.slotBand.getReels(); // 假设 _reels 是 SlotGame 中存储 ReelControl 实例的数组
    }

    public getRowCount(): number {
        return this.slotBand.rowCount; // 假设 _rowCount 是 SlotGame 中存储行数的属性
    }
    public getColCount(): number {
        return this.slotBand.colCount; // 假设 _rowCount 是 SlotGame 中存储行数的属性
    }

    private playSoundNew(soundKey: string): void {
        console.log("SlotGame playSoundNew===================================================", soundKey);
        const currentTime = Date.now() / 1000;
        if (currentTime - this.lastSoundPlayTime >= this.soundInterval) {
            Utils.playEffectNew(soundKey);
            this.lastSoundPlayTime = currentTime;
        }
    }
}
