    public static playEffectNew(soundKey: string) {
        console.log("playEffectNew soundKey", soundKey);
        const soundPath = Config.sounds_new[soundKey];
        let path = `resources/audio/${soundPath}`;
        LogUtil.log("playEffectNew soundPath", soundPath);
        if (soundPath) {
            AudioManager.Instance().playEffect(path, RES.bundleName, 1, false);  // 设置 loop 为 false
        } else {
            console.warn(`Sound key not found: ${soundKey}`);
        }
        // AudioManager.Instance().playEffect(path, RES.bundleName);
    }

    public static playMusicNew(musicKey: string): void {
        const musicPath = Config.sounds_new[musicKey];
        console.log("playMusicNew full path:", musicPath);
        let path = `resources/audio/${musicPath}`;
    
        // 检查音频系统是否初始化
        if (!AudioManager.Instance()) {
            console.error("AudioManager is not initialized!");
            return;
        }
    
        // 检查全局背景音乐设置
        if (!Global.backgroundMusic) {
            console.warn("Background music is disabled globally!");
            return;
        }
    
        // 尝试播放音乐
        if (musicPath) {
            AudioManager.Instance().playMusic(path, RES.bundleName);  // 音乐默认就是循环的
        } else {
            console.warn(`Music key not found: ${musicKey}`);
        }
    }

