    /**
     * 线性倒V型
     */
    public static hillIn(k: number) {
        k *= 2;
        if (k < 1) {
            return k;
        }
        return 2 - k;
    }

    /**
     * 线性V型
     */
    public static hillOut(k: number) {
        k *= 2;
        if (k < 1) {
            return 1 - k
        }
        return k - 1;
    }

