    /**
    * 二阶贝塞尔曲线运动
    * @param target 目标
    * @param duration 时间
    * @param c1 起始点
    * @param c2 控制点
    * @param to 终点
    * @param opts 自定义选项
    * @returns
    */
    
    public static bezierTo(target: any, duration: number, c1: Vec3, c2: Vec3, to: Vec3, opts: any, delayTime:number) {
        opts = opts || Object.create(null);
        /*
        * @desc 二阶贝塞尔
        * @param {number} t 当前百分比
        * @param {} p1 起点坐标
        * @param {} cp 控制点
        * @param {} p2 终点坐标
        * @returns {any}
        */
        let twoBezier = (t:number, p1: Vec3, cp: Vec3, p2: Vec3) => {
            let x = (1 - t) * (1 - t) * p1.x + 2 * t * (1 - t) * cp.x + t * t * p2.x;
            let y = (1 - t) * (1 - t) * p1.y + 2 * t * (1 - t) * cp.y + t * t * p2.y;
            return v3(x, y, 0);
        };
        
        return tween(target).delay(delayTime).call(()=>{
            target.setSiblingIndex(50);
        }).by(duration, {}, {onUpdate(arg, ratio) {
            target.position = twoBezier(ratio!, c1, c2, to);
        }, easing: "backOut"});
    }
