import { _decorator, Component, Node, Vec3, TweenEasing, Tween, UITransform, tween } from 'cc';
import { UIButton } from '../../../../../scripts/framework/ui/basic_ui/UIButton';
import { RollCommonModel } from '../../../../rollCommon/script/RollCommonModel';
import { UICF, UIID_GAME } from "../../../../../bundlers/320000101/scripts/UIDefined";
import GamesData from '../../../../gamesCommon/script/GamesData';
import { ShakeTool } from '../../../../rollCommon/script/media/ShakeTool';
import { GameCommonModel } from '../../../../gamesCommon/script/GameCommonModel';
import GameResPath from '../../../../gamesCommon/script/constDatas/GameResPath';
import { GameCommonManager } from '../../../../gamesCommon/script/GameCommonManager';
import { GameComUtils } from '../../../../gamesCommon/script/utils/GameComUtils';
import { StatConst } from '../../../../gamesCommon/script/stat/StatConst';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { GameEventType } from '../../../../gamesCommon/script/GameEventType';
import { RollCommonManager } from '../../../../rollCommon/script/RollCommonManager';
import { UIManager } from '../../../../../scripts/framework/ui/UIManager';
import { Global } from '../../../../../scripts/main/Global';
import { ScreenType } from '../../../../../scripts/framework/ui/UIView';

const { ccclass, property } = _decorator;

@ccclass('SpinRollMenu')
export class SpinRollMenu extends Component {

    @property(Node)
    public content: Node;

    @property({ displayName: "helpBtn", type: UIButton, tooltip: '帮助按钮' })
    private helpBtn: UIButton;
    @property({ displayName: "setBtn", type: UIButton, tooltip: '设置按钮' })
    private setBtn: UIButton;
    @property({ displayName: "screenSwitchBtn", type: UIButton, tooltip: '切换横竖屏按钮' })
    private screenSwitchBtn: UIButton;
    @property({ displayName: "recordBtn", type: UIButton, tooltip: '游戏记录按钮' })
    private recordBtn: UIButton;
    @property({ displayName: "backBtn", type: UIButton, tooltip: '返回大厅按钮' })
    private backBtn: UIButton;

    private readonly _showPoint: Vec3 = new Vec3(0, 0, 0);
    private readonly _hidePoint: Vec3 = new Vec3(0, -600, 0);
    private _model: RollCommonModel;

    /** 菜单开启 */
    private _isOpenMenu = false;

    protected __preload(): void {
        this._model = RollCommonModel.getInstance();
        // UICF[UIID_GAME.UIRollHelp1].bundle = GamesData.gameId + "";
    }

    start() {
        GamesData.shakeResumeFun = ShakeTool.instance.resume;
        this.showMenu(this._isOpenMenu, false);
        this.showMenuBtn(this._isOpenMenu, false);

        this.addToStage();
        this.initBtn();
    }

    onLoad() {
        this.content.active = false;
    }

    protected onDestroy(): void {
        this.removeFromStage();
    }

    public updataMenu() {
        if (this._isOpenMenu == false) {
            return;
        }

        this._isOpenMenu = false;
        this.showMenu(this._isOpenMenu, true);
        this.showMenuBtn(this._isOpenMenu, true);
    }

    private initBtn() {
        this.initBackBtn();
        this.initScreenBtn();
        this.initRecordBtn();
        this.initNode();
    }

    private initBackBtn() {
        let isShow = GameCommonModel.getInstance().isShowBack();
        if(this.backBtn&&this.backBtn.node) {
            this.backBtn.node.active = isShow;
        }
    }

    private initRecordBtn() {
        let isShow = GameCommonModel.getInstance().isShowRecord();
        if(this.recordBtn&&this.recordBtn.node) {
            this.recordBtn.node.active = isShow;
        }
    }

    private initScreenBtn() {
        let isShow = GameCommonModel.getInstance().isShowScreen();
        if(this.screenSwitchBtn&&this.screenSwitchBtn.node) {
            this.screenSwitchBtn.node.active = isShow;
        }
    }

    private initNode() {
        let h = this.content.getComponent(UITransform).height;
        let w = this.node.getComponent(UITransform).width;
        this.node.getComponent(UITransform).setContentSize(w, h);
    }

    private onBack(target: UIButton): void {
        GameResPath.playRollCommonSound("click_1");
        this.updataMenu();
        GameCommonManager.getInstance().backToHall();
        GameCommonManager.getInstance().releaseRec();
    }
    private onBackBegan(target: UIButton) {
        this.setBtnNormal(target.node);
    }
    private onBackCancel(target: UIButton) {
        this.setBtnPressed(target.node);
    }

    private onHelp(target: UIButton): void {
        GameResPath.playRollCommonSound("click_1");
        UIManager.getInstance().open(UIID_GAME.PayTableView);
    }
    private onHelpBegan(target: UIButton) {
        this.setBtnNormal(target.node);
    }
    private onHelpCancel(target: UIButton) {
        this.setBtnPressed(target.node);
    }

    private onRecord(target: UIButton): void {
        GameComUtils.c2sStat(StatConst.GAME_RECORD);
        GameResPath.playRollCommonSound("click_1");
        this.updataMenu();
        GameCommonManager.getInstance().showRecord();
        Eventer.getInstance().emit(GameEventType.RollRecordClick);
    }
    private onRecordBegan(target: UIButton) {
        this.setBtnNormal(target.node);
    }
    private onRecordCancel(target: UIButton) {
        this.setBtnPressed(target.node);
    }

    private onSetting(target: UIButton): void {
        GameResPath.playRollCommonSound("click_1");
        this.updataMenu();
        UIManager.getInstance().open(UIID_GAME.SetView);
    }
    private onSettingBegan(target: UIButton) {
        this.setBtnNormal(target.node);
    }
    private onSettingCancel(target: UIButton) {
        this.setBtnPressed(target.node);
    }

    private onScreenSwitch(target: UIButton): void {
        GameResPath.playRollCommonSound("click_1");
        this.updataMenu();
        GameComUtils.c2sStat(StatConst.SCREEN_TIMES);
        Global.gameScreenType = Global.gameScreenType == ScreenType.Portrait ? ScreenType.Landscape : ScreenType.Portrait;
        Eventer.getInstance().emit(GameEventType.ScreenSwitch);

        window.parent.postMessage(JSON.stringify({
            functionName: 'gameScreenSwitch',
            screenType: Global.gameScreenType //landscape portrait
        }), '*')
    }
    private onScreenBegan(target: UIButton) {
        this.setBtnNormal(target.node);
    }
    private onScreenCancel(target: UIButton) {
        this.setBtnPressed(target.node);
    }

    public onMenu() {
        console.log("SpinRollMenu onMenu");
        GameResPath.playRollCommonSound("click_1");
        this._isOpenMenu = !this._isOpenMenu;
        this.showMenu(this._isOpenMenu, true);
    }

    /**
    * 显示菜单
    * @param isShow 是否显示
    * @param hasTween 是否动画
    */
    protected showMenu(isShow: boolean, hasTween: boolean) {
        console.log("SpinRollMenu showMenu", isShow, hasTween);
    
        let uiTransform = this.content.getComponent(UITransform);
        let width = uiTransform.width;
        let height = uiTransform.height;
    
        // Set the anchor point to the bottom-right corner
        uiTransform.anchorX = 1;
        uiTransform.anchorY = 0;
    
        // Calculate the position to keep the bottom-right corner fixed
        let bottomRightPosition = new Vec3(this._showPoint.x, this._showPoint.y, 0);
    
        // Ensure content is active and visible
        this.content.active = true;
    
        if (hasTween) {
            Tween.stopAllByTarget(this.content);
            
            if (isShow) {
                // Set initial state for showing
                this.content.setPosition(bottomRightPosition);
                this.content.setScale(0, 0, 1);
    
                tween(this.content)
                    .to(0.3, { scale: new Vec3(1, 1, 1) }, { easing: 'backOut' })
                    .start();
            } else {
                // Set initial state for hiding
                this.content.setPosition(bottomRightPosition);
                this.content.setScale(1, 1, 1);
    
                tween(this.content)
                    .to(0.3, { scale: new Vec3(0, 0, 1) }, { easing: 'backIn' })
                    .call(() => { this.content.active = false; })
                    .start();
            }
        } else {
            // Immediate change without animation
            this.content.setPosition(bottomRightPosition);
            this.content.setScale(isShow ?  new Vec3(1, 1, 1) :  new Vec3(0, 0, 1));
            this.content.active = isShow;
        }
    }

   

    /**
     * 菜单按钮状态
     * @param isShow 是否显示
     * @param hasTween 是否动画
     */
    protected showMenuBtn(isShow: boolean, hasTween: boolean) {
        // let arrow = this.btn_menu.node.getChildByName("caidansanjiao");
        // let angle = 0;
        // if (isShow) {
        //     angle = 180;
        // }

        // if (hasTween) {
        //     Tween.stopAllByTarget(arrow);
        //     let tween = new Tween(arrow);
        //     tween = tween.to(0.2, { angle: angle });
        //     tween.start();
        // }
        // else {
        //     arrow.angle = angle;
        // }
    }

    protected setBtnNormal(node: Node) {
        node.setScale(1, 1);
    }
    protected setBtnPressed(node: Node) {
        node.setScale(0.9, 0.9);
    }

    private closeMenu(evt): void {
        this.updataMenu();
    }

    protected addToStage() {
        if (this.backBtn) {
            this.backBtn.touchEndedFun = this.onBack.bind(this);
            this.backBtn.touchBeganFun = this.onBackBegan.bind(this);
            this.backBtn.touchCancelFun = this.onBackCancel.bind(this);
        }
        if (this.setBtn) {
            this.setBtn.touchEndedFun = this.onSetting.bind(this);
            this.setBtn.touchBeganFun = this.onSettingBegan.bind(this);
            this.setBtn.touchCancelFun = this.onSettingCancel.bind(this);
        }
        if (this.helpBtn) {
            this.helpBtn.touchEndedFun = this.onHelp.bind(this);
            this.helpBtn.touchBeganFun = this.onHelpBegan.bind(this);
            this.helpBtn.touchCancelFun = this.onHelpCancel.bind(this);
        }
        if (this.recordBtn) {
            this.recordBtn.touchEndedFun = this.onRecord.bind(this);
            this.recordBtn.touchBeganFun = this.onRecordBegan.bind(this);
            this.recordBtn.touchCancelFun = this.onRecordCancel.bind(this);
        }
        if (this.screenSwitchBtn) {
            this.screenSwitchBtn.touchEndedFun = this.onScreenSwitch.bind(this);
            this.screenSwitchBtn.touchBeganFun = this.onScreenBegan.bind(this);
            this.screenSwitchBtn.touchCancelFun = this.onScreenCancel.bind(this);
        }

        Eventer.getInstance().on(GameEventType.RollStart, this.closeMenu, this);
        Eventer.getInstance().on(GameEventType.RollStop, this.closeMenu, this);
        Eventer.getInstance().on(GameEventType.RollAutoStart, this.closeMenu, this);
        Eventer.getInstance().on(GameEventType.RollAutoStop, this.closeMenu, this);
        Eventer.getInstance().on(GameEventType.RollChangeLine, this.closeMenu, this);
        Eventer.getInstance().on(GameEventType.RollChageBet, this.closeMenu, this);
        Eventer.getInstance().on(GameEventType.RollQuick, this.closeMenu, this);
        Eventer.getInstance().on(GameEventType.RollBackgroundClick, this.closeMenu, this);
        Eventer.getInstance().on(GameEventType.RollMenuViewClose, this.closeMenu, this);
    }

    protected removeFromStage() {
        Eventer.getInstance().offName(GameEventType.RollStart, this);
        Eventer.getInstance().offName(GameEventType.RollStop, this);
        Eventer.getInstance().offName(GameEventType.RollAutoStart, this);
        Eventer.getInstance().offName(GameEventType.RollAutoStop, this);
        Eventer.getInstance().offName(GameEventType.RollChangeLine, this);
        Eventer.getInstance().offName(GameEventType.RollChageBet, this);
        Eventer.getInstance().offName(GameEventType.RollQuick, this);
        Eventer.getInstance().offName(GameEventType.RollBackgroundClick, this);
        Eventer.getInstance().offName(GameEventType.RollMenuViewClose, this);

        Tween.stopAllByTarget(this.content);

        if (this.backBtn) {
            this.backBtn.touchEndedFun = null;
        }
        if (this.setBtn) {
            this.setBtn.touchEndedFun = null;
        }
        if (this.helpBtn) {
            this.helpBtn.touchEndedFun = null;
        }
        if (this.recordBtn) {
            this.recordBtn.touchEndedFun = null;
        }
        if (this.screenSwitchBtn) {
            this.screenSwitchBtn.touchEndedFun = null;
        }

    }
}

