import { _decorator, Node, sp, NodeEventType, AudioClip, AudioSource, Sprite, SpriteAtlas, tween, Vec3, } from 'cc';
import { Resource } from '../../../../../scripts/framework/hall/Resource';
import AudioManager from '../../../../../scripts/framework/manager/AudioManager';
import { ResManager } from '../../../../../scripts/framework/manager/ResManager';
import { ScreenType, UIView } from '../../../../../scripts/framework/ui/UIView';
import { Global } from '../../../../../scripts/main/Global';
import GamesData from '../../../../gamesCommon/script/GamesData';
import { BigWinViewData, BigWinType } from '../../../../rollCommon/script/RollCommonModel';
import { RollValue } from '../../../../rollCommon/script/views/RollValue';
import { Config, RES } from '../../Config';
import { GameEventType } from '../../../../gamesCommon/script/GameEventType';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { RollComUtils } from '../../../../rollCommon/script/utils/RollComUtils';
import { Utils } from '../../utils/Utils';
import { MainGameView } from '../MainGameView';
import { Mask } from 'cc';
import { UITransform } from 'cc';

const { ccclass, property } = _decorator;

@ccclass('WinController')
export class WinController extends UIView {

    @property(Node)
    private touchNode: Node;
    @property(RollValue)
    private lab_bigWin: RollValue;
    @property(sp.Skeleton)
    private ske_bigwin: sp.Skeleton;
    @property(Node)
    private rollNode: Node;
    private _rolling = false;
    private _data: BigWinViewData;
    private _audioSource: AudioSource = null!;
    private _mainGameView: MainGameView;

    init(...args): void {
        this._data = args[0];
        this._mainGameView = this._data.thisObj as MainGameView;
    }

    start() {
        // this._data = {
        //     "type": BigWinType.BIG_WIN,
        //     "autoHide": true,
        //     "value": 999999999,
        //     "delay": 0.01,
        //     "call": null,
        //     "thisObj": this
        // }

        RollComUtils.closeFuncUI()
        // this.onScreenSwitch()
        // Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
        this.lab_bigWin.init(true, 594);
        this.lab_bigWin.node.scale = new Vec3(1, 1, 1);

        this._showSkeleton();

        this.touchNode.on(NodeEventType.TOUCH_END, this.onTouch, this);


        let delay = this._data.delay||1000; //this._data.delay
        let autoCloseTime: number = Math.ceil(delay / 1000) + 5;
        console.log("autoCloseTime===============================",autoCloseTime);

        this.scheduleOnce(() => {
            this._rolling = false;
            this._hide();
        }, autoCloseTime);

        //quickHit
        Utils.playEffectNew("qhb_bigwin");
    }

    private onScreenSwitch() {
        this.rollNode.angle = Global.gameScreenType == ScreenType.Landscape ? 0 : 90;
        let scale = Global.gameScreenType == ScreenType.Landscape ? 1 : 0.75;
        this.rollNode.setScale(new Vec3(scale, scale, scale));
    }

    private _showSkeleton() {
        // this.ske_bigwin.node.active = false;
        let typeName: string = this._data.type;
        let atlas = RES.getRes(RES.resConfig.BigWinAtlas, SpriteAtlas);
        let num = 1
        switch (typeName) {
            case BigWinType.BIG_WIN://"big-win":
                this.ske_bigwin.setAnimation(0, "bigwin", true);
                break;
            case BigWinType.HUGE_WIN://"super-win":
                this.ske_bigwin.setAnimation(0, "hugewin", true);
                break;
            case BigWinType.SUPER_WIN://"super-win":
                this.ske_bigwin.setAnimation(0, "hugewin", true);
                break;
            default: break;
        }

        // this._rolling = true;
        this.ske_bigwin.node.active = true;
        this.lab_bigWin.setPrefix(Config.getPrefix())
        
        if(this._data&&this._data.value){
            this.lab_bigWin.addValueTo(this._data.value, true, this._data.delay);
        }
    }

    private _hideSke(): void {
        this._hide();
        if (AudioManager.Instance().musicEnabled) {
            GamesData.playMusic();
        }
    }

    private onTouch(evt) {
        console.log("onTouch===============================");
        if (this._rolling) {
            this.lab_bigWin.stopRoll();
            this._rolling = false;
        }
        else {
            tween(this.lab_bigWin.node).delay(0.5).to(0.6, { scale: new Vec3(0, 0, 0) }, { easing: "backIn" }).start();
            this.touchNode.off(NodeEventType.TOUCH_END, this.onTouch, this); //防止隐藏过程中再次点击
            this._hideSke();
        }
    }

    protected onDestroy(): void {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }

    private _hide() {
        console.log("WinController _hide===============================");

        this.touchNode.off(NodeEventType.TOUCH_END, this.onTouch, this); //防止隐藏过程中再次点击
        AudioManager.Instance().stopAllEffect();
        
        // Utils.playSound("end");
        this.ske_bigwin.clearTrack(0);
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
        this.close();
        if (this._data.call && this._data.thisObj) {
            this._data.call.call(this._data.thisObj);
        }
    }
}
