import { _decorator, Component, Node } from 'cc';
import { RollCommonModel } from '../../../rollCommon/script/RollCommonModel';
const { ccclass, property } = _decorator;

@ccclass('buyShowCtr')
export class buyShowCtr extends Component {
    @property(Node)
    private horBuy: Node
    @property(Node)
    private verBuy: Node
    private isShow = false
    start() {
        this.showBuy(this.isShow)
    }
    public showBuy(enable) {
        this.horBuy.active = enable
        this.verBuy.active = enable
    }
    update(deltaTime: number) {
        if (RollCommonModel.getInstance().isShowSpecBuy != this.isShow) {
            this.isShow = RollCommonModel.getInstance().isShowSpecBuy
            this.showBuy(this.isShow)
        }
    }
}

