import { _decorator, Component, Label, Node } from 'cc';
import { Utils } from '../utils/Utils';
import { GameEventType } from '../../../gamesCommon/script/GameEventType';
import { Eventer } from '../../../../scripts/framework/Eventer';
import { RollCommonModel } from '../../../rollCommon/script/RollCommonModel';
import { GameCommonModel } from '../../../gamesCommon/script/GameCommonModel';
import GamesData from '../../../gamesCommon/script/GamesData';
import { Config } from '../Config';
import { UIButton } from '../../../../scripts/framework/ui/basic_ui/UIButton';
import { UIManager } from '../../../../scripts/framework/ui/UIManager';
import { UIID_GAME } from '../UIDefined';
import { RollComUtils } from '../../../rollCommon/script/utils/RollComUtils';
import { GameType } from '../net/ServerProxy';
const { ccclass, property } = _decorator;

@ccclass('buyBtnNodes')
export class buyBtnNodes extends Component {
    @property(Node)
    private buyBtnNodes
    @property(UIButton)
    public btn_buyGame: UIButton;
    public isFreeShow;
    private _model
    private _type = GameType.Normal;
    public get type() {
        return this._type;
    }
    public set type(value) {
        this._type = value;
        this.isHide(this._type == GameType.Normal)
    }
    /**是否隐藏*/
    private isHide(bool) {
        if (bool) {
            this.node.setPosition(0, 0)
        } else {
            this.node.setPosition(0, -2000)
        }
    }

    start() {
        // //开发服测试用
        // if (this.isFreeShow == false) {
        //     this.isFreeShow = true
        //     this.freeShow()
        // }
        this.addToStage();
        this.updateBuy()
        if (this.btn_buyGame) {
            this.btn_buyGame.touchEndedFun = this.onBuyGame.bind(this);
        }
    }
    protected get model(): RollCommonModel {
        if (!this._model) {
            this._model = RollCommonModel.getInstance();
        }
        return this._model;
    }
    protected addToStage() {
        Eventer.getInstance().on(GameEventType.RollStart, this.rollFuc, this)
        Eventer.getInstance().on(GameEventType.RollChageBet, this.updateBuy, this);
    }
    public rollFuc() {
        this.btn_buyGame.enabled = false;
        RollComUtils.setBuyButtonOpacity(this.btn_buyGame.node, true);
    }
    public getBuyState() {
        return this.btn_buyGame.enabled
    }
    public setBuyState(bool) {
        this.btn_buyGame.enabled = bool;
        RollComUtils.setBuyButtonOpacity(this.btn_buyGame.node, !bool);
    }

    // public freeShow() {
    //     this.setSpecialBtnShow(this.isFreeShow)
    //     this.updateBuy()
    // }
    public updateBuy() {
        this.updateLabel()
        let curBet = GameCommonModel.getInstance().curBet;
        let line = this.model.curBetLine;
        let bet = curBet * line * this.model.betRate;
        let money = GameCommonModel.getInstance().money
        if (money < bet * Config.buyGaneBet) {
            this.btn_buyGame.enabled = false;
            RollComUtils.setBuyButtonOpacity(this.btn_buyGame.node, true);
        } else {
            this.btn_buyGame.enabled = true;
            RollComUtils.setBuyButtonOpacity(this.btn_buyGame.node, false);
        }
    }
    public updateLabel() {
        let curBet = GameCommonModel.getInstance().curBet;
        let line = this.model.curBetLine;
        let bet = curBet * line * this.model.betRate;
        let buyScore = GamesData.formatScore(bet * Config.buyGaneBet, false);
        this.buyBtnNodes.getChildByName("buyLabel").getComponent(Label).string = Config.getPrefix() + buyScore;

    }
    protected onBuyGame(target: UIButton): void {
        UIManager.getInstance().open(UIID_GAME.BuyGameView);
    }
    /**
     * 设置购买特殊玩法按钮是否启用
     * @param enable 
     */
    public setSpecialBtnShow(enable: boolean) {
        this.buyBtnNodes.active = enable;
    }
    update(deltaTime: number) {
        // if (RollCommonModel.getInstance().isShowSpecBuy != this.isFreeShow) {
        //     this.isFreeShow = RollCommonModel.getInstance().isShowSpecBuy
        //     this.freeShow()
        // }

    }
    protected onDestroy(): void {
        Eventer.getInstance().offName(GameEventType.RollStart, this)
        Eventer.getInstance().offName(GameEventType.RollChageBet, this);
    }

}

