import { _decorator, Component, Sprite, Vec3, Color, sp, SpriteAtlas, Node, UITransform, instantiate, Prefab, Layers, SpriteFrame, resources, AssetManager, log, tween, Tween } from "cc";
import { BundleManager } from "../../../../../scripts/framework/manager/BundleManager";
import LogUtil from "../../../../../scripts/common/utils/LogUtil";
import { MaxId, MinId, QuickHit_Syboml, QuickHit_Syboml_Feature, RES, Scatter_Syboml, Wild_Normal, Wild_Special } from "../../Config";
import { Utils } from "../../utils/Utils";
import { GameUtility } from "../other/GameUtility";

const {ccclass, property} = _decorator;


@ccclass
export default class TileControl extends Component {
    // @property({ type: [SpriteFrame], visible: true })
    // private textures = [];
    @property({ type: Sprite, visible: true })
    private _iconTex: Sprite;
    @property({ type: sp.Skeleton, visible: true })
    private _iconSke: sp.Skeleton;

    public _shiftDown: boolean;
    public id: number;      // 图标id

    // Glow over tile
    @property(Node)
    public glowNode = null;

    public get positionY() {
        return this.node.position.y;
    }

    public set positionY(value: number) {
        this.node.position = new Vec3(this.node.position.x, value);
    }

    private get isSkeVaild() {
        return this._iconSke && this._iconSke.node;
    }

    private get aniKey(): string {
        let ani: string = "";
        //LogUtil.debug("aniKey===========", this.id);
        switch (this.id) {
            case 1: ani = "win"; break;
            case 2: ani = "win"; break;
            case 3: ani = "win"; break;
            case 4: ani = "win"; break;
            case 5: ani = "win"; break;
            case 6: ani = "win"; break;
            case 7: ani = "win"; break;
            case 8: ani = "win"; break;
            case 9: ani = "intro"; break;
            case 10: ani = "intro"; break;
            case 11: ani = "overturn"; break;
            case 12: ani = "win"; break;
            default: ani = "win"; break;
        }
        return ani;
    }

    private _isSpinning: boolean = false;

    public get isSpinning(): boolean {
        return this._isSpinning;
    }

    public set isSpinning(value: boolean) {
        this._isSpinning = value;
    }

    protected onLoad(): void {
        this.id = 0;
        this._iconTex = this.getComponentInChildren(Sprite);
        if (!this._iconTex) {
            LogUtil.error("TileControl: 未能在子节点中找到 Sprite 组件");
        }
    }

    public init(down: boolean, id: number, score?: number, useBlur: boolean = false): void {
        this.id = id;
        this._shiftDown = down;
        this.setTile(this.id, useBlur, false);
        // this.dim(true);
        // this.turnOver();
        // this.setScore(score);
    }

    async resetInEditor(): Promise<void> {
        this.setRandom();
    }

    public activateGlow(option: boolean) {
        this.glowNode.active = option;
    }

    public dim(dim: boolean = true): void {
        let color = dim ? new Color(60, 60, 60, 255) : Color.WHITE;
        this._iconTex.color = color;
        this._iconSke.node.active = !dim;
        this._iconTex.node.active = dim;
    }

    public setRandom(): void {
        const randomIndex = GameUtility.randomEx(MinId, MaxId, Scatter_Syboml);
        // LogUtil.debug(`setRandom randomIndex: ${randomIndex}`);
        this.id = randomIndex;
        this.setTile(this.id, false, true);
    }

    public setTile(id: number, useBlur: boolean, showAni: boolean = false): void {
        this.id = id;
        // this._isSpinning = useBlur; // 当使用模糊图标时，认为正在旋转
        // console.log("setTile id:", id, "this._isSpinning:", this._isSpinning, "showAni:", showAni);
        const atlas = RES.getFrom<SpriteAtlas>("IconAtlas");
        if(!this._isSpinning){
            // console.log("setStaticIcon0000:", showAni);
            if( showAni){
                this.playIcon(false);
            }
            else{
                // if( id === QuickHit_Syboml || id === QuickHit_Syboml_Feature )
                //     this.playIcon(false);
                // else
                    this.setStaticIcon(id, useBlur, atlas);
            }
        } else {
            // console.log("setStaticIcon111:", showAni);
            this.setStaticIcon(id, useBlur, atlas);
        }
    }
    
    private setStaticIcon(id: number, useBlur: boolean, atlas: SpriteAtlas | null): void {
        // console.log("setStaticIcon id:", id, "useBlur:", useBlur);   
        
        // 检查 _iconTex 是否存在
        if (!this._iconTex) {
            LogUtil.error("TileControl: _iconTex 为空");
            return;
        }

        this._iconTex.node.active = true;
        const key = `icon${id}_${useBlur ? 1 : 0}`;
        
        // 检查图集是否存在并且能否获取到精灵帧
        const spriteFrame = atlas?.getSpriteFrame(key);
        if (!spriteFrame) {
            LogUtil.error(`TileControl: 无法获取精灵帧，键值为: ${key}`);
            return;
        }

        // 设置精灵帧
        this._iconTex.spriteFrame = spriteFrame;

        // 处理骨骼动画组件（如果存在）
        if (this._iconSke) {
            this._iconSke.node.active = false;
        }
    }

    public playIcon(loop: boolean): TileControl {
        LogUtil.debug(`[TileControl] icon.playIcon started at: [${new Date().toISOString()}]`);
        // console.log("playIcon loop:", loop);
        if (!this.isSkeVaild) {
            this.showSprite();
            return this;
        }
        return this.playIcon2(this.aniKey, loop);
    }

    public playQuickHitAnimation(): TileControl {
        LogUtil.debug(`[TileControl] playQuickHitAnimation started at: [${new Date().toISOString()}]`);
        if (!this.isSkeVaild) {
            this.showSprite();
            return this;
        }
        try {
            this.hideSprite();
            if (!this.id) {
                LogUtil.warn('TileControl: id is not set for scatter animation');
                return this;
            }
            const skeletonName = `IconSk${this.id}`;
            const asset = RES.getFrom(skeletonName);
            if (!asset || !(asset instanceof sp.SkeletonData)) {
                LogUtil.error(`TileControl: Failed to load valid skeleton data for ${skeletonName}`);
                return this;
            }
            this.setIconSke(asset);
            if (!this._iconSke) {
                LogUtil.error('TileControl: _iconSke is null for scatter animation');
                return this;
            }
            this._iconSke.node.active = true;
            // 播放intro动画，设置为不循环
            this._iconSke.setAnimation(0, 'end', false);
            // 监听intro动画完成事件，然后播放win动画
            this._iconSke.setCompleteListener(() => {
                // 移除完成事件监听器
                this._iconSke.setCompleteListener(null);
                // 播放win动画，设置为循环播放
                this._iconSke.setAnimation(0, 'overturn2', false);
            });

        } catch (error) {
            LogUtil.error('TileControl: Error playing scatter animation:', error);
        }

        return this;
    }

    /**
     * 播放Scatter特殊动画序列
     * 先播放intro动画，然后播放win动画
     * @returns TileControl实例，用于链式调用
     */
    public playScatterAnimation(): TileControl {
        if (!this.isSkeVaild) {
            this.showSprite();
            return this;
        }

        try {
            this.hideSprite();

            if (!this.id) {
                LogUtil.warn('TileControl: id is not set for scatter animation');
                return this;
            }

            const skeletonName = `IconSk${this.id}`;
            const asset = RES.getFrom(skeletonName);

            if (!asset || !(asset instanceof sp.SkeletonData)) {
                LogUtil.error(`TileControl: Failed to load valid skeleton data for ${skeletonName}`);
                return this;
            }

            this.setIconSke(asset);

            if (!this._iconSke) {
                LogUtil.error('TileControl: _iconSke is null for scatter animation');
                return this;
            }

            this._iconSke.node.active = true;

            // 播放intro动画，设置为不循环
            this._iconSke.setAnimation(0, 'intro', false);

            // 监听intro动画完成事件，然后播放win动画
            this._iconSke.setCompleteListener(() => {
                // 移除完成事件监听器
                this._iconSke.setCompleteListener(null);
                // 播放win动画，设置为循环播放
                this._iconSke.setAnimation(0, 'win', true);
            });

        } catch (error) {
            LogUtil.error('TileControl: Error playing scatter animation:', error);
        }

        return this;
    }

    private showSprite(): void {
        if (this._iconSke) {
            this._iconSke.node.active = false;
        }
        if(this._iconTex){
            this._iconTex.node.active = true;
        }
    }

    public playIcon2(key: string, loop: boolean): TileControl {
        // console.log("playIcon2 key:", key, "loop:", loop, "id:", this.id);
        try {
            this.hideSprite();
    
            if (!this.id) {
                LogUtil.warn('TileControl: id is not set');
                return this;
            }
    
            const skeletonName = this.id <= 11 ? `IconSk${this.id}` : 'IconSkn';
            const asset = RES.getFrom(skeletonName);
            // console.log("playIcon2 asset:", asset, "skeletonName:", skeletonName);
            if (!asset) {
                LogUtil.error(`TileControl: Failed to load asset for ${skeletonName}`);
                return this;
            }
    
            if (!(asset instanceof sp.SkeletonData)) {
                LogUtil.error(`TileControl: Asset for ${skeletonName} is not a SkeletonData`);
                return this;
            }
    
            this.setIconSke(asset);
    
            if (!this._iconSke) {
                LogUtil.error('TileControl: _iconSke is null after setIconSke');
                return this;
            }
    
            this._iconSke.node.active = true;
    
            if (!key) {
                LogUtil.warn('TileControl: Animation key is not provided');
                return this;
            }
    
            // console.log("Before setAnimation - _iconSke:", this._iconSke);
            // console.log("_iconSke.skeletonData:", this._iconSke.skeletonData);
            // if (!this._iconSke.skeletonData) {
            //     LogUtil.error('TileControl: skeletonData is null');
            //     return this;
            // }
            // const animationNames = this._iconSke.animation;
            // // const animationNames = this._iconSke.skeletonData.getAnimationNames();
            // console.log("Available animations:", animationNames);
            // if (!animationNames.includes(key)) {
            //     LogUtil.error(`TileControl: Animation '${key}' not found in skeletonData`);
            // }

            if(skeletonName == "IconSk11" && key == "overturn"){ 
                // First show the static icon
                this.setStaticIcon(this.id, false, RES.getFrom<SpriteAtlas>("IconAtlas"));
                
                // Add delay before playing animation
                this.scheduleOnce(() => {
                    this.hideSprite(); // Hide the static sprite
                    this._iconSke.node.active = true;
                    this._iconSke.setAnimation(0, key, false);
                }, 2); // 2 seconds delay
            }
            else{
                this._iconSke.setAnimation(0, key, loop);
            }
            // console.log("After setAnimation");
    
        } catch (error) {
            LogUtil.error('TileControl: Error in playIcon2', error);
        }
    
        return this;
    }

    private hideSprite(): void {
        this._iconTex.node.active = false;
    }

    public playByUrl(url: string, aniName: string, loop: boolean): TileControl {
        this.hideSprite();
        this._iconTex.node.active = true;
        this.setIconSke(RES.getFrom(url));
        this._iconSke.node.active = true;
        this._iconSke.setAnimation(0, aniName, loop);
        return this;
    }

    private setIconSke(skeData: sp.SkeletonData): void {
        //LogUtil.debug(`setIconSke: ${skeData.name}`);
        if (this.isSkeVaild) {
            this._iconSke.skeletonData = skeData;
            return;
        }

        if (this.isSkeVaild) {
            this._iconSke.node.removeFromParent();
            this._iconSke.node.destroy();
            this._iconSke = null;
        }

        let skeNode = instantiate(RES.getFrom<Prefab>("SkePref"));
        this.node.addChild(skeNode);
        this._iconSke = skeNode.getComponent(sp.Skeleton);
        this._iconSke.skeletonData = skeData;
    }

    public stopIcon(): void {
        this._isSpinning = false;
        this._iconTex.node.active = true;
        if (this.isSkeVaild) {
            this._iconSke.node.active = false;
            this._iconSke.clearTrack(0);
            this._iconSke.setToSetupPose();
            this._iconSke.setCompleteListener(null);
        }
    }

    public onIconComplete(callback: Function, thisArg: any): void {
        this._iconSke?.setCompleteListener(() => {
            this._iconSke.setCompleteListener(null);
            callback.call(thisArg);
        });
    }

    async replaceImage(newImagePath: string) {
        return new Promise<void>((resolve, reject) => {
            this.setTile(2, false);
        });
    }

    public turnOver(): void {
        //LogUtil.debug(`setOverTurn`);
        var currentRotation = this._iconTex.node.eulerAngles;
        tween(this._iconTex.node)
            .to(0.5, { eulerAngles: new Vec3(currentRotation.x, currentRotation.y + 180, currentRotation.z) })
            .call(async () => {
                await this.setRandom();
            })
            .to(0.1, { eulerAngles: new Vec3(currentRotation.x, currentRotation.y + 360, currentRotation.z) })
            .start();
    }

    
    /** 移除动画节点 */
    private releaseIconSke(): void {
        if (this.isSkeVaild) {
            // this._iconSke.node.destroy();
            this._iconSke.node.removeFromParent();
            this._iconSke.node.destroy();
            this._iconSke = null; // 确保引用被清除
        }
    }

    public clear(): void {
        // this.index = -1;
        this.releaseIconSke();
    }

    public remove(): void {
        this.destroy();
    }

    private isPlaying(key: string) {
        return this._iconSke?.animation == key;
    }

    private setIconPosY(node: Node, y: number): void {
        let pos = node.position;
        node.setPosition(pos.x, y, pos.z);
    }

    public setScore(score: number): void {}
    
    public showNormalIcon(): void {
        // Stop any ongoing animations
        this.stopIcon();

        // Ensure the sprite is visible and the skeleton is hidden
        this._iconTex.node.active = true;
        if (this._iconSke) {
            this._iconSke.node.active = false;
        }

        // Set the tile to its normal state (non-blurred)
        this.setTile(this.id, false, false);

        // Reset any color changes (in case it was dimmed)
        this._iconTex.color = Color.WHITE;

        // Deactivate glow effect if it exists
        if (this.glowNode) {
            this.activateGlow(false);
        }

        // Reset rotation (in case it was mid-turn)
        this._iconTex.node.eulerAngles = Vec3.ZERO;
    }
}