import { _decorator, Component, Node, sp } from 'cc';
const { ccclass, property } = _decorator;

@ccclass('ColorAnimation')
export class ColorAnimation extends Component {
    @property(sp.Skeleton)
    private skeleton: sp.Skeleton | null = null;
    private animationPrefix: string = '';

    onLoad() {
        // 获取动画前缀（使用 skeleton 节点的名称）
        this.animationPrefix = this.skeleton.node.name;
    }

    playRandomAnimation() {
        if (!this.skeleton) return;

        // 生成 1-3 的随机数
        const randomNumber = Math.floor(Math.random() * 3) + 1;

        // 构建动画名称
        const animationName = `${this.animationPrefix}${randomNumber}`;

        // 检查动画是否存在
        if (!this.skeleton.findAnimation(animationName)) {
            console.error(`ColorAnimation: 未找到动画 ${animationName}`);
            return;
        }

        // 播放随机选择的动画
        this.skeleton.setAnimation(0, animationName, true);
    }
}
