    protected update(deltaTime: number): void {
        let delta = Math.floor(deltaTime * 1000);
        if (delta > 200) {  //200ms以上的认为卡顿，则丢弃
            return;
        }
        Timer.update(delta);
        SequenceCtrl.update(delta / 1000);
        this._machine?.updateState();

        // 待修改
        if (this.block && this.result != null) {
            this.informStop();
            this.result = null;
        }
    }

