    private receiveBet(data: { baseMap: any, featureMap: any, reward: number }): void {
        this._hasReceive = true;
        
        // Update the map data based on the current game type
        if (this._type === GameType.Normal) {
            this._mapData = data.baseMap[0];
        } else if (this._type === GameType.Feature) {
            this._mapData = data.featureMap;
            console.log("receiveBet data:", data);
        }
        
        LogUtil.debug("当前牌面数据 _mapData ==", this._mapData);
        LogUtil.debug("当前总奖励 data.reward ==", data.reward);
    
        // Update the big win display
        if(data.reward > 0&&this.lab_bigWin){  
            this.lab_bigWin.setValue(0);
            this.lab_bigWin.setText("0");

            LogUtil.debug("receiveBet this.onFeature", this.onFeature);
            LogUtil.debug("receiveBet this._mapData", this._mapData.map);
            let isEnterFreeFeature = GameUtility.isEnterFeature(this._mapData.map);
            LogUtil.debug("receiveBet isEnterFreeFeature", isEnterFreeFeature);
            if (isEnterFreeFeature && !this.onFeature) {
                this.starAniContainer.active = true;
                this._isPrePairInFeature = true;
                
                if (this.starAniPrefab) {
                    this.starAniPrefab.reset();
                }
                this.showStarAnimation(() => { this.starAniContainer.active = false; });

                this._featureTotalWin = data.reward;
                console.log("receiveBet this.featureTotalWin:", this._featureTotalWin);
            }
            else{
                this.scheduleOnce(() => {
                    console.log(`[MainGameView] receiveBet scheduleOnce data.reward: ${data.reward}`);
                    this.lab_bigWin.addValue(data.reward);
                }, 3.5); 

                this._totalWin = data.reward;
                const winType = this.getBigWinType(this._totalWin);
                LogUtil.debug("Entering ===============================receiveBet:",winType);
                switch (winType) {
                        case BigWinType.MINOR:
                            break;
                        case BigWinType.BIG_WIN:
                            break;
                        case BigWinType.HUGE_WIN:
                            this.showFireKuangAnimation();
                        // 可以添加更多类型的动画
                }
            }
        }
    }

    private updateBalance(): void {
        LogUtil.log("updateBalance OnReceiveBalance当前余额 ==");
        if (this.rollComModel.isRolling || this.rollComModel.inFreeGame) {
            return;
        }
        
        // Log.e(Config.logTag, "set money", this.gameComModel.money);
        this._bottomUI.setMoney(this.gameComModel.money);

        switch (this._type) {
            case GameType.Normal:
                break;
            case GameType.Feature:
                if(!SlotGame.instance.isSpinStopped()){
                    this._mapData = ServerProxy.getInstance().getLastMapData(this._type); 
                    if(this._mapData.score > 0){    
                        this.scheduleOnce(() => {
                            console.log(`[MainGameView] receiveBet scheduleOnce data.reward: ${this._mapData.score}`);
                            this.lab_bigWin.addValue(this._mapData.score);
                        }, 3.5); 
                    }
                }
                LogUtil.log("updateBalance this.state = StRolling");
                this.state = StRolling;
                break;
        }
    }   

    private initQuickHitItems(data: any): void {
        let tempScores = [];
        
        // 计算第一个元素 (使用固定的 curBet = 4)
        let firstData = GameDataDefine.quickhitLvData[0];
        let line = RollCommonModel.getInstance().curBetLine;
        let firstBet = firstData.reward * GameCommonModel.getInstance().curBet*4/5 * line * RollCommonModel.getInstance().betRate;
        let firstScore = GamesData.formatScore(firstBet, false);
        tempScores.push(firstScore);
    
        // 计算其余元素
        for (let i = 0; i < 8; i++) {
            let curData = GameDataDefine.quickhitLvData[i];
            let curBet = GameCommonModel.getInstance().curBet;
            let bet = curData.reward * curBet * line * RollCommonModel.getInstance().betRate;
            let score = GamesData.formatScore(bet, true);
            tempScores.push(score);

            // console.log("tempScores[i + 1]:", tempScores[i + 1]);
            if (this.quickHitLabels[i]) {
                this.quickHitLabels[i].string = `${tempScores[i + 1]}`;
            }
        }
    
        // 更新 quickHitData
        this.quickHitData = tempScores;
    
        if (this.quickHitController) {
            this.quickHitController.init(this);
        }
        // console.log("Updated quickHitData:", this.quickHitData);
    }


