    //#region StReady
    private readyEnter(): void {
        LogUtil.debug("Entering ===============================readyEnter");
        if (Global.playback) return;

        this._mapData = null;
        LogUtil.debug("Entering ===============================readyEnter SlotGame.instance.isSpinStart():", SlotGame.instance.isSpinStart());
        if (SlotGame.instance.isSpinStart()) {
            this.onNormal && this.sendBet();   // 发送押注信息      
            this.onFeature && this.sendBetFeature();   // 发送feature押注信息
        }
    }

    private readyUpdate(): void {
        // LogUtil.debug("Entering ===============================readyUpdate:",this._type,this._hasReceive);
        // this._mapData = null;
        if (this._hasReceive ) {
            this._hasReceive = false;
            this._mapData = ServerProxy.getInstance().getMapData(this._type);   // 获取游戏数据   
            LogUtil.debug("Entering ===============================readyUpdate _hasReceive  this.mapData:", this.mapData);
            // this._mapData.map = [1, 2, 3, 4, 9, 6, 1, 9, 7, 9, 8, 10, 1, 2, 5];  //可以添加测试数据
        }
        if (this.mapData) {
            switch (this._type) {
                case GameType.Normal:
                    this._curWin = this.mapData.score;
                    this._totalWin = this.mapData.score;
                    this._curMoney += this.mapData.score;
                    break;
                case GameType.Feature:
                    this._curWin = this.mapData.score;
                    this._totalWin += this.mapData.score;    // 当前总赢分
                    this._curMoney += this.mapData.score;
                    --this._freeTotalRound;
                    SlotGame.instance.updateRound(this._freeTotalRound);           // 更新免费游戏轮数
                    break;
            }
            // LogUtil.log("readyUpdate this.state = StRolling:", this.starAniContainer.active);
            if(!this.starAniContainer.active){
                LogUtil.debug(`Setting state to StRolling`);
                this.state = StRolling;
            }
        }
    }
