    private _autoOut: number = 0;
    private rollingPressed(): void {
        LogUtil.debug("Entering ===============================rollingPressed");
        Config.isClickStop = true
        if (this.state == StIdle) {
            if (this.autoGame || !this.onNormal || Global.playback && !Global.playbackFinish) {
                Timer.clearTimeOut(this._autoOut);
                this._autoOut = Timer.setTimeOut(this, () => {
                    this.idleStartPressed();
                }, 120);
            }
            return
        }
        LogUtil.debug("rollingPressed SlotGame.instance.stopSpin");
        SlotGame.instance.stopSpin(this.mapData, this._type);   // 接收到滚轮数据停止滚动
    }

