    private continueSpinning(): void {
        LogUtil.debug("continueSpinning:::::::::::::::::");
        if (this._type === GameType.Feature) {
            if (this._mapData) {
                // 计算获得的 quickHit 数量
                const newQuickHits = this.calculateQuickHitCount(this._mapData.map);
                this.quickHitCount += newQuickHits;
                
                const nextLevel = this.quickHitController.calculateLevel(this.quickHitCount);
                console.log('nextLevel:', nextLevel);
                console.log('this.quickHitController.getSymbolsToNextLevel:', this.quickHitController.getSymbolsToNextLevel());
                // 检查是否需要升级
                if (this.quickHitCount >= this.quickHitController.getSymbolsToNextLevel()) {
                    // 更新 LineControl 中的计数
                    console.log('this.quickHitCount111111111111111:', this.quickHitCount);
                    // this._lineControl.setQuickHitCount(this.quickHitCount, this.quickHitController.getSymbolsToNextLevel());
                    LogUtil.debug(`[LineControl] this.slotGame.featureAutoRollTimeDelay11111: started at: [${new Date().toISOString()}], featureAutoRollTimeDelay: ${this.slotGame.featureAutoRollTimeDelay}`);
                    this.scheduleOnce(() => {
                        this.quickHitController.triggerQuickHit(this.quickHitCount);
                        //重置spin数量
                        this.quickHitController.setInitialSpinCount(3);
                        this.quickHitCount = 0;
                        this._lineControl.setQuickHitCount(this.quickHitCount, this.quickHitController.getSymbolsToNextLevel());
                    }, this.slotGame.featureAutoRollTimeDelay); 
                } else {
                    // Feature 玩法未结束，继续旋转
                    LogUtil.debug(`[LineControl] this.slotGame.featureAutoRollTimeDelay22222: [${new Date().toISOString()}], featureAutoRollTimeDelay: ${this.slotGame.featureAutoRollTimeDelay}`);
                    this.scheduleOnce(() => {
                        if (this._type == GameType.Feature) {
                            LogUtil.debug(`continueSpinning ================== [${new Date().toISOString()}]`);
                            this.startSpin();
                            this.quickHitController.updateCurrentSpinTime();
                            console.log('this.quickHitCount22222222222222:', this.quickHitCount);
                            // 更新 LineControl 中的计数
                            this._lineControl.setQuickHitCount(this.quickHitCount, this.quickHitController.getSymbolsToNextLevel());
                        }
                    }, this.slotGame.featureAutoRollTimeDelay); 
                }
            } else {
                // LogUtil.debug("continueSpinning1111111111111111111111:::::::::::::::::");
                this.quickHitController.node.active = false;
                this.boardNum.active = true;

                // 没有更多数据，结束 Feature 游戏
                this._type = GameType.Normal;
                this.hideQuickHitFeature();
                this.stopSpin();

                LogUtil.debug(`Setting state to StIdle`);
                this.state = StIdle;
            }
        } else {
            LogUtil.debug("continueSpinning222222222222222222222:::::::::::::::::");
            this.stopSpin();
            LogUtil.debug(`Setting state to StReward111111`);
            this.state = StReward;
        }
    }

