    //#region StReward
    private rewardEnter(): void {
        LogUtil.debug("Entering ===============================rewardEnter");
        LogUtil.debug('rewardEnter:', this.mapData);
    
        const showRewardAnimation = (winType: BigWinType | null) => {
            console.log('showRewardAnimation winType:', winType);
            if (winType === null) {
                // 普通奖励，直接进入空闲状态
                LogUtil.debug(`Setting state to StIdle`);
                this.state = StIdle;
                return;
            }
    
            switch (winType) {
                case BigWinType.MINOR:
                    this.showShuziAnimation();
                    break;
                case BigWinType.BIG_WIN:
                    this.showBigWinAnimation();
                    break;
                case BigWinType.HUGE_WIN:
                    this.showHugeWinAnimation();
                    break;
                case BigWinType.SUPER_WIN:
                    this.showHugeWinAnimation();
                    break;
                // 可以添加更多类型的动画
            }
    
            // 动画结束后进入空闲状态
            LogUtil.debug(`Setting state to StIdle`);
            this.state = StIdle;
        }
    
        const processWin = () => {
            // 如果是从 Feature 状态返回，直接跳过 QuickHit 动画检查
            if (this._isReturningFromFeature) {
                this._isReturningFromFeature = false; // 重置标志
                UIManager.getInstance().closeToUI(UIID_GAME.BigWinView);
                showRewardAnimation(BigWinType.SUPER_WIN);

                LogUtil.debug(`processWin setStartBtnState================== [${new Date().toISOString()}]`);
                this.setStartBtnState(1, true);
                return;
            }

            const winType = this.getBigWinType(this._totalWin);

            // 检查 this._mapData 是否为空
            if (this._mapData && this._mapData.map) {
                // 计算 QuickHit 符号的数量
                let quickHitCount = this.calculateQuickHitCount(this._mapData.map);
                console.log('QuickHit count:', quickHitCount);
                // quickHitCount = Math.floor(Math.random() * (12 - 5 + 1)) + 5;
                // console.log('Randomized QuickHit count:', quickHitCount);
                // 判断 QuickHit 等级
                let quickHitLevel = 0;
                for (let i = 0; i < this.symbolsToQuickHitLevel.length; i++) {
                    if (quickHitCount >= this.symbolsToQuickHitLevel[i]) {
                        quickHitLevel = i;
                    } else {
                        break;
                    }
                }
                console.log('QuickHit level:', quickHitLevel);
    
                // 如果达到 QuickHit 等级，播放相应的动画
                if (quickHitLevel > 0) {
                    if (this._type !== GameType.Feature) {
                        this.plaJackpotAnimation(quickHitLevel);
                        this.playQuickHitWinnerAnimation();
                        // 播放 quick hit中奖
                        console.log('Utils.playMusicNew("qhb_bg_qhprogressive")');
                        Utils.playEffectNew("qhb_bg_qhprogressive");
                        return; // 播放 QuickHit 动画后直接返回，不再显示其他奖励动画
                    }
                }
            } else {
                LogUtil.warn("this._mapData or this._mapData.map is null or undefined");
            }
    
            // 如果没有 QuickHit 或 _mapData 为空，显示普通奖励动画
            showRewardAnimation(winType);
    
            if (this._type === GameType.Feature && this._freeTotalRound <= 0) {
                this.exitFeatureGame();
            }
        }
    
        processWin();
    }

