        // 设置等级和显示动画
        this.curQuickLevelNode.setLevel(level, 3);
        this.curQuickLevelNode.showAnimation(level, true, false);
        this.curQuickLevelNode.hideAllElements();
        this.curQuickLevelNode.hideCurLevelLab();
