    private getBigWinType(win: number): BigWinType | null {
        LogUtil.debug("Entering ===============================getBigWinType");
        let bet = this.gameComModel.curBet * Config.maxLine;
        let rate = win / bet;
        Log.d(Config.logTag, `big win type:bet${bet},rate:${rate},curBet:${this.gameComModel.curBet},configRate:${Config.betRate},line:${Config.maxLine}`);
        if (rate >= 300) {
            return BigWinType.SUPER_WIN;     //火焰框加huge_win
        } else if (rate >= 50) {
            return BigWinType.HUGE_WIN;     //火焰框加huge_win
        } else if (rate >= 15) {
            return BigWinType.BIG_WIN;      //bigwin
        } else if (rate >= 3) {
            return BigWinType.MINOR;        //喷金币
        }
        return null;
    }

