    /////////////////////////////////////////Spin/////////////////////////////////////
    async requestResult(): Promise<void> {
        LogUtil.debug("Entering ===============================requestResult");
        this.result = null;
        this.result = await this.getAnswer();
        LogUtil.debug('result', this.result);
    }

    getAnswer(): Promise<Array<Array<number>>> {
        LogUtil.debug("Entering ===============================getAnswer");
        let slotResult: Array<Array<number>> = [];
        return new Promise<Array<Array<number>>>(resolve => {
          setTimeout(() => {
            let pattern = this.getRandomPattern();
            let equalLines = this.getRandomEqualLines(pattern, this.machineSize.x);
            slotResult = this.getResultWithEqualLines(equalLines, this.machineSize);
            resolve(slotResult);
          }, 1000 + 500 * Math.random());
        });
    }
    
    informStop(): void {
        LogUtil.debug("Entering ===============================informStop");
        let resultRelayed = this.result; 
        this.slotGame.stopSpin({ map: resultRelayed.flat() } as MapData,  this._type);
    }
    
    getRandomEqualLines(linesCount: number, lineSize: number): Array<number>{
        LogUtil.debug("Entering ===============================getRandomEqualLines");
        let equalLines = Array(lineSize).fill(0).map((v,i)=>i);
        equalLines = this.shuffleArray(equalLines);
        return equalLines.slice(0, linesCount);
    }
    
    getResultWithEqualLines(equalLines: Array<number>, machineSize:Vec2): Array<Array<number>> {
        LogUtil.debug("Entering ===============================getResultWithEqualLines");
        if(equalLines.length == 0){
          return [];
        }
        const slotResult = Array(machineSize.y).fill(Array(machineSize.x).fill(-1));
        let value = 0;
        equalLines.forEach(pivvot => {
          value = this.getRandomInt(0, this.tileCount - 1);
          for (let index = 0; index < machineSize.y; index++) {
            slotResult[index][pivvot] = value;
          }
        });
        return slotResult;
    }
    
    getRandomInt(min, max): number {
        LogUtil.debug("Entering ===============================getRandomInt");
        return Math.floor(Math.random() * (max - min + 1) + min);
    }
    
    shuffleArray(array: Array<number>): Array<number> {
        LogUtil.debug("Entering ===============================shuffleArray");
        for (let i = array.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [array[i], array[j]] = [array[j], array[i]];
        };
        return array;
    }
    
    getRandomPattern(): number{
        LogUtil.debug("Entering ===============================getRandomPattern");
        let occurrence = 0;
        let random = this.getRandomInt(0, 99);
        for (let index = 3; index >=0; index--) {
            occurrence += this.probability[index];
            if( random <= occurrence)
            return index;
        }
        return 0;
    }

    private isProcessingClick: boolean = false;
    click(): void {
        LogUtil.debug("Entering ===============================click");

        if (this.isProcessingClick) {
            LogUtil.debug('Ignoring click: already processing a click');
            return;
        }
    
        if (this._type === GameType.Feature || this._isPrePairInFeature) {
            LogUtil.debug('Ignoring click in Feature mode');
            return;
        }
        this.isProcessingClick = true;
        try {
            if (this.slotGame.isSpinStopped()) {
                this.idleStartPressed();
            } else{
                this.stopSpin_force();
                // this.block = true;
                // this.slotGame.slotBand.lock();
            }
        } catch (error) {
            LogUtil.error('Error in click method:', error);
        } finally {
            // 无论是否发生错误，都确保重置处理标志
            this.scheduleOnce(() => {
                this.isProcessingClick = false;
                LogUtil.debug('Click processing flag reset');
            }, 0.5); // 500毫秒的延迟，可以根据需要调整
        }
    }

