    private onFeatureModeEnded(): void {
        LogUtil.debug("featureTotalWin mode ended, returning to Normal mode");
        LogUtil.debug("featureTotalWin total win:", this._featureTotalWin);
        
        this._type = GameType.Normal;
        this._isReturningFromFeature = true;
    
        // 添加回调函数来处理动画完成后的逻辑
        LogUtil.debug(`[onFeatureModeEnded] showFeatureEndAnimation playSpecialAnimation at: [${new Date().toISOString()}]`);
        this.quickHitController.setTotalReward(this._featureTotalWin);
        this.quickHitController.showFeatureEndAnimation(() => {
            LogUtil.debug(`[onFeatureModeEnded] showFeatureEndAnimation playSpecialAnimation callbackat: [${new Date().toISOString()}]`);
            this.scheduleOnce(() => {
                LogUtil.debug(`[onFeatureModeEnded] hideQuickHitFeature playSpecialAnimation at: [${new Date().toISOString()}]`);
                // 结束 Quick Hit 背景音乐播放
                this.stopMusic();
                this.hideQuickHitFeature();
                // 重置SlotGame和BanditControl的位置
                this.resetSlotGamePosition();
                
                // 更新总奖励显示
                if (this._featureTotalWin > 0) {
                    this.lab_bigWin.setValue(0);
                    this.lab_bigWin.setText("0");
                    this.scheduleOnce(() => {
                        this.lab_bigWin.addValue(this._featureTotalWin);
                    }, 0);
                }

                let bigdata: BigWinViewData = {
                    "type": BigWinType.BIG_WIN,
                    "autoHide": true,
                    "value": this._featureTotalWin, // 使用累计的奖励金额
                    "delay": 0.01,
                    "call": () => { 
                        this.state = StIdle; 
                        this.setStartBtnState(1, true);
                        // 重置 feature 总奖励
                        this._featureTotalWin = 0;
                    },
                    "thisObj": this
                }
                UIManager.getInstance().open(UIID_GAME.BigWinView, bigdata);

                LogUtil.debug(`Setting state to StReward222222 [${new Date().toISOString()}]`);
                this.state = StReward;
            }, 3.8);
        });
    
    }

