    private showStarAnimation(callback: () => void): void {
        // console.log("showStarAnimation 开始执行");
        if (!this.starAniPrefab || !this.starAniContainer) {
            console.error("StarAniPrefab or starAniContainer is not set!");
            callback();
            return;
        }

        const starAniControl = this.starAniPrefab;
        if (!starAniControl) {
            console.error("StarAniControl component not found!");
            callback();
            return;
        }

        // console.log("StarAniControl 组件存在");
        if (starAniControl.node.parent !== this.starAniContainer) {
            // console.log("将 StarAniControl 节点添加到 starAniContainer");
            this.starAniContainer.addChild(starAniControl.node);
        }

        starAniControl.node.active = true;
        // console.log("StarAniControl 节点已激活");

        // console.log("开始播放星星动画");
        starAniControl.playAnimation(() => {
            // console.log("所有星星动画播放完成");
            starAniControl.node.active = false;
            // console.log("StarAniControl 节点已隐藏");
            callback();
        });
    }

