import { _decorator, Component, Node, Prefab, instantiate, tween, Vec3, v3, Layout, UITransform, Tween } from "cc";
import TileControl from "./TileControl";
import LogUtil from "../../../../../scripts/common/utils/LogUtil";
import { MinId, MaxId, Scatter_Syboml, Wild_Special, QuickHit_Syboml, QuickHit_Syboml_Feature } from "../../Config";
import { GameUtility } from "../other/GameUtility";
import { Utils } from "../../utils/Utils";
import { Config } from "../../Config";

const { ccclass, property } = _decorator;

enum ReelState {
    Stopped = 0,
    Spinning,
    Stopping,
};

@ccclass
export default class ReelControl extends Component {
    @property({ type: Node })
    public reelAnchor: Node = null;

    @property({ type: [Node], visible: false })
    private tiles: Node[] = [];
    @property({ type: Prefab })
    private _tilePrefab: Prefab = null;

    private _useBlur: boolean;
    private _special: boolean;
    private _shiftDown: boolean = false;

    @property({ type: [Number], visible: true })
    private _reelResult: number[] = [];
    private _reelScore: number[] = [];
    @property({ type: [Number], visible: true })
    private _iconsPositionY: number[] = [];
    private _iconDistance: number;

    private _rowCount: number = 5;
    private _originY: number = 0;
    private result: number[] = [];
    private _reelState: ReelState;

    public stopSpinning: boolean = false;
    public onReelStopped: Function;

    // 新增参数定义
    private spinSpeed: number; // 像素/秒
    private endSpeed: number; // 像素/秒
    private moveDistance: number = 110;

    private _distanceY: number;
    private stopEasingDuration: number;

    private totalSpinTime: number;

    private columnIndex: number = -1;  // 新增属性来存储列索引

    public get distanceY(): number {
        return this._distanceY;
    }

    protected onLoad(): void {
    }

    @property
    get tilePrefab(): Prefab {
        return this._tilePrefab;
    }

    set tilePrefab(newPrefab: Prefab) {
        this._tilePrefab = newPrefab;
        this.reelAnchor.removeAllChildren();
        this.tiles = [];

        if (newPrefab !== null) {
            this.createReel();
            // this.shuffle();
        }
    }

    public init(rowCount: number, distanceY: number, spinSpeed: number, endSpeed: number, totalSpinTime: number, columnIndex: number): void {
        this._reelState = ReelState.Stopped;
        this._rowCount = rowCount;
        this._distanceY = distanceY;
        this._iconDistance = distanceY;
        this.spinSpeed = spinSpeed; // 设 spinSpeed
        this.endSpeed = endSpeed; // 设置 endSpeed
        this.totalSpinTime = totalSpinTime;
        this.columnIndex = columnIndex;  // 设置列索引
        LogUtil.debug(`ReelControl init rowCount: ${rowCount}, distanceY: ${distanceY}, spinSpeed: ${spinSpeed}, endSpeed: ${endSpeed}, totalSpinTime: ${totalSpinTime}, columnIndex: ${columnIndex}`);

        this._originY = this.node.position.y;

        this.reelAnchor.removeAllChildren();
        this.tiles = [];

        this.createReel();
    }

    createReel(): void {
        let newTile: Node;
        for (let i = 0; i < this._rowCount; i++) {
            newTile = instantiate(this.tilePrefab);
            this.reelAnchor.addChild(newTile);
            this.tiles[i] = newTile;
            // 设置新的 Y 坐标
            newTile.position = new Vec3(0, 49.5 + i * 99, 0);
            newTile.getComponent(TileControl).init(true, GameUtility.randomEx(MinId, MaxId, Scatter_Syboml));
        }

        const layout = this.reelAnchor.getComponent(Layout);
        if (layout) {
            layout.updateLayout();
        }
    }

    shuffle(): void {
        for (let i = 0; i < this.tiles.length; i++) {
            this.tiles[i].getComponent(TileControl).setRandom();
        }
    }

    public readyStop(newResult: number[], stopEasingDuration: number): void {
        // console.log(`[ReelControl] readyStop called with stopEasingDuration: ${stopEasingDuration}`);
        const startTime = performance.now();
        this._reelResult = newResult ? newResult.slice().reverse() : [];
        this.stopSpinning = true;
        this.stopEasingDuration = stopEasingDuration;

        // 添加一个计时器来检查实际的停止时间
        const checkStopInterval = setInterval(() => {
            if (!this.stopSpinning) {
                clearInterval(checkStopInterval);
                const endTime = performance.now();
                // console.log(`[ReelControl] Actual stop duration: ${endTime - startTime}ms`);
            }
        }, 10);
    }

    private readonly EXTRA_OFFSET: number = 20; // 额外偏移量
    changeCallback(element: Node = null): void {
        const el = element;
        const scrollRange = this.calculateScrollRange();
        
        const positionCheck = this._shiftDown ? 
            el.position.y > scrollRange.start : 
            el.position.y < scrollRange.end;
    
        // console.log(`[ReelControl] changeCallback - Element position: ${el.position.y}, positionCheck: ${positionCheck}, scrollRange: [${scrollRange.end}, ${scrollRange.start}]`);
    
        if (positionCheck) {
            const newPosition = v3(0, this._shiftDown ? 
                scrollRange.end + this._iconDistance / 2 : // 将 tile 移动到底部
                scrollRange.start - this._iconDistance / 2, // 将 tile 移动到顶部
                0);
            el.position = newPosition;
            // console.log(`[ReelControl] Tile repositioned to: ${newPosition.y}`);
    
            let pop = null;
            if (this.result != null && this.result.length > 0) {
                pop = this.result.pop();
            }

            const tileC = el.getComponent(TileControl);
            if (pop != null && pop >= 0) {
                if (tileC) {
                    // console.log(`[ReelControl] Setting tile to: ${pop}`);
                    tileC.setTile(pop, false);
                }
            } else {
                if (tileC) {
                    // console.log(`[ReelControl] Setting random tile`);
                    tileC.setRandom();
                }
            }
        }
    }

    checkEndCallback(element: Node = null): void {
        const el = element;
        if (this.stopSpinning) {
            this.doStop(el);
        } else {
            this.doSpinning(el);
        }
    }

    private tilePositions: Map<Node, { minY: number, maxY: number, positions: number[] }> = new Map();

    doSpin(spinStartInterval: number, totalSpinTime: number): void {
        // console.log(`[ReelControl] doSpin started - spinStartInterval: ${spinStartInterval}, totalSpinTime: ${totalSpinTime}`);
        this.stopSpinning = false;
        this.totalSpinTime = Math.max(totalSpinTime, this.MIN_SPIN_TIME);
        // console.log(`[ReelControl] Adjusted totalSpinTime: ${this.totalSpinTime}`);
    
        // this.resetTilePositions();
    
        const reverseDistance = this.moveDistance * 0.15;
        const reverseDuration = 0.1;
    
        this.reelAnchor.children.forEach((element, index) => {
            // console.log(`[ReelControl] Setting up spin for tile ${index}`);
            this.tilePositions.set(element, { minY: element.position.y, maxY: element.position.y, positions: [element.position.y] });
    
            const tileControl = element.getComponent(TileControl);
            if (tileControl) {
                tileControl.isSpinning = true;
            }
    
            const delay = tween(element).delay(spinStartInterval);
            
            // 添加反向缓动
            const reverseMove = tween(element).by(reverseDuration, { 
                position: new Vec3(0, this._shiftDown ? -reverseDistance : reverseDistance, 0) 
            }, { easing: 'sineOut' });
            
            const startDuration = this.moveDistance / this.endSpeed;
            const start = tween(element).by(startDuration, { 
                position: new Vec3(0, this._shiftDown ? 
                    this.moveDistance + reverseDistance : 
                    -this.moveDistance - reverseDistance, 0) 
            }, { easing: 'sineIn' });
            const doChange = tween().call(() => this.changeCallback(element));
            const callSpinning = tween(element).call(() => {
                // console.log(`[ReelControl] Starting continuous spinning for tile ${index}, position: ${element.position.y}`);
                this.doSpinning(element, 
                    Math.ceil((this.totalSpinTime - startDuration - reverseDuration) / (this.moveDistance / this.spinSpeed)));
            });
    
            delay.then(reverseMove).then(start).then(doChange).then(callSpinning).start();
        });
    }
    
    doSpinning(element: Node = null, times = 1): void {
        times = Math.max(1, Math.ceil(times));
        // console.log(`[ReelControl] doSpinning started - times: ${times}`);
        const spinDuration = this.moveDistance / this.spinSpeed;
        const move = tween().by(spinDuration, { 
            position: new Vec3(0, this._shiftDown ? 
                this.moveDistance : 
                -this.moveDistance, 0) 
        }, { easing: 'linear' });
        const doChange = tween().call(() => this.changeCallback(element));
        const updatePosition = tween().call(() => {
            const data = this.tilePositions.get(element);
            if (data) {
                data.minY = Math.min(data.minY, element.position.y);
                data.maxY = Math.max(data.maxY, element.position.y);
                data.positions.push(element.position.y);
            }
        });
        const repeat = tween(element).repeat(times, move.then(doChange).then(updatePosition));
        const checkEnd = tween().call(() => {
            // console.log(`[ReelControl] Checking end of spinning`);
            this.checkEndCallback(element);
        });
    
        repeat.then(checkEnd).start();
    }
    
    doStop(element: Node = null): void {
        // console.log(`[ReelControl] doStop started`);
        const startTime = performance.now();
        const spinDuration = this.moveDistance / this.spinSpeed;
        const move = tween(element).by(spinDuration, { position: new Vec3(0, this._shiftDown ? this.moveDistance : -this.moveDistance, 0) });
        const doChange = tween().call(() => this.changeCallback(element));
        const end = tween().by(this.stopEasingDuration, { position: new Vec3(0, this._shiftDown ? this.moveDistance : -this.moveDistance, 0) }, { easing: 'bounceOut' });
        const endAdjustTile = tween().call(() => {
            this.tiles.forEach(tile => this.adjustTilePosition(tile));
        });
        const setTiles = tween().call(() => {
            const halfCount = Math.floor(this.tiles.length / 2);
            this.tiles.forEach((tile, index) => {
                const tileControl = tile.getComponent(TileControl);
                if (tileControl) {
                    if (this._reelResult[index] !== undefined) {
                        tileControl.setTile(this._reelResult[index], false);
                        tileControl.isSpinning = false;
                    }
                    if (this._reelScore[index] !== undefined) {
                        tileControl.setScore(this._reelScore[index]);
                    }
                }
                const newPosition = v3(0, index * this._iconDistance+this._iconDistance/2, 0);
                tile.position = newPosition;
            });
        });

        // 添加新的 tween 来播放声音效果
        const playSound = tween().call(() => {
            this.playTileSound();
        });
    
        move.then(doChange).then(move).then(doChange).then(end).then(doChange)
            .then(endAdjustTile).then(setTiles)
            .then(playSound)
            .then(tween().call(() => {
                const endTime = performance.now();
                // console.log(`[ReelControl] doStop completed in ${endTime - startTime}ms`);
                if (this.onReelStopped) {
                    this.onReelStopped();
                }
            }))
            .start();
    }
    
    // 调整 tile 位置以避免重叠
    adjustTilePosition(tile: Node): void {
        const tileC = tile.getComponent(TileControl);
        if (!tileC) return;
    
        const originalTilePosition = tile.position.clone();
        const scrollRange = this.calculateScrollRange();
        const maxAdjustments = 10; // 防止无限循环
        let adjustmentCount = 0;
    
        while (adjustmentCount < maxAdjustments) {
            let adjustmentNeeded = false;
            const tilePosition = tile.position;
            const adjacentTiles = this.getAdjacentTiles(tile);
    
            for (const adjacentTile of adjacentTiles) {
                const adjacentTileC = adjacentTile.getComponent(TileControl);
                if (!adjacentTileC) continue;
    
                const adjacentTilePosition = adjacentTile.position;
                if (tilePosition.equals(adjacentTilePosition)) {
                    // console.log(`[ReelControl] Overlap detected between tiles: ${tile.name} and ${adjacentTile.name}`);
                    // console.log(`[ReelControl] Overlap Position: x: ${tilePosition.x}, y: ${tilePosition.y}, z: ${tilePosition.z}`);
    
                    // 调整 tile 位置
                    const newY = tilePosition.y + (this._shiftDown ? -this._iconDistance : this._iconDistance);
                    
                    // 确保新位置在滚动范围内
                    if (newY >= scrollRange.end && newY <= scrollRange.start) {
                        tile.position = v3(tilePosition.x, newY, tilePosition.z);
                        // console.log(`[ReelControl] Adjusted ${tile.name} from y: ${tilePosition.y} to y: ${newY}`);
                        adjustmentNeeded = true;
                        break;
                    } else {
                        // console.log(`[ReelControl] Cannot adjust ${tile.name}. New position out of range.`);
                        return; // 如果无法调整，直接回
                    }
                }
            }
    
            if (!adjustmentNeeded) {
                // console.log(`[ReelControl] Tile ${tile.name} adjusted successfully after ${adjustmentCount} attempts.`);
                return; // 如果不需要进一步调整，退出循环
            }
    
            adjustmentCount++;
        }
    
        // console.warn(`[ReelControl] Max adjustments reached for tile ${tile.name}. Final position: y: ${tile.position.y}`);
    }

    private calculateScrollRange(): { start: number, end: number } {
        const tileHeight = this._iconDistance;
        const totalHeight = (this._rowCount ) * tileHeight; // 从第一个tile的中心到最后一个tile的中心的距离
        
        return {
            start: totalHeight + this.EXTRA_OFFSET, // 299 + extra offset
            end: -tileHeight / 2 // 0 - extra offset
        };
    }

    // 获取相邻的 tiles
    getAdjacentTiles(tile: Node): Node[] {
        const adjacentTiles: Node[] = [];
        const tileIndex = this.tiles.indexOf(tile);

        if (tileIndex > 0) {
            adjacentTiles.push(this.tiles[tileIndex - 1]);
        }
        if (tileIndex < this.tiles.length - 1) {
            adjacentTiles.push(this.tiles[tileIndex + 1]);
        }

        return adjacentTiles;
    }


    private prevRandom: number = 0;
    // 随机图标Id
    private getRandom(index?: number): number {
        let random: number;
        if (index == -1 || index == this._rowCount) {
            random = GameUtility.randomEx(MinId, MaxId, Scatter_Syboml);   // 上下的冗余图标不能出现scatter
        }
        else if (this.prevRandom == Scatter_Syboml) {
            random = 0;                                             // 如果上一个图标是scatter, 隐藏当前图标
        }
        else if (this._special) {
            random = GameUtility.randomEx(MinId, MaxId, Wild_Special);   // 特殊游戏中不会随机出Wild_Special图标
        }
        else {
            random = GameUtility.random(MinId, MaxId);
        }
        this.prevRandom = random;
        return random;
    }

    // 牌面图标Id
    private getResult(index: number): number {
        let result: number;
        if (this._reelResult[index - 1] == Scatter_Syboml && this._reelResult[index] == Scatter_Syboml) {
            result = 0
        } else {
            result = this._reelResult[index]
        }
        return result;
    }

    private getSnake(index?: number): number {
        if (index && this._reelScore) {
            return this._reelScore[index];
        }
        return undefined;
    }

    
    activateGlow(option: boolean): void {
        this.reelAnchor.children.forEach(element => {
            const tileControl = element.getComponent(TileControl);
            if (tileControl) {
                tileControl.activateGlow(option);
            }
        });
    }

    public setIcon(rowIndex: number, iconId: number, score?: number): void {
        if (this.tiles[rowIndex]) {
            const tileControl = this.tiles[rowIndex].getComponent(TileControl);
            if (tileControl) {
                tileControl.setTile(iconId, false);
                if (score !== undefined) {
                    tileControl.setScore(score);
                }
            }
        }
    }

    public getIcon(index: number): TileControl | null {
        // 计算反向索引
        const reverseIndex = this.tiles.length - 1 - index;
        if (reverseIndex >= 0 && reverseIndex < this.tiles.length) {
            const tile = this.tiles[reverseIndex];
            // console.warn(`getIcon index: ${index}, reverseIndex: ${reverseIndex}`);
            // console.warn(`getIcon tile position: ${tile.getPosition()}`);
            return tile ? tile.getComponent(TileControl) : null;
        }
        // console.warn(`getIcon Invalid index: ${index}`);
        return null;
    }
    
    /** 取图标世界坐标 (滚动停止后调用)*/
    public getIconPos(index: number): Vec3 | null {
        if (index >= 0 && index < this.tiles.length) {
            const tile = this.tiles[index];
            return tile ? tile.worldPosition : null;
        }
        // console.warn(`Invalid index: ${index}`);
        return null;
    }
    
    /** 获取图标本地坐标 */
    public getIconPos2(index: number): Vec3 | null {
        if (index >= 0 && index < this._iconsPositionY.length) {
            return new Vec3(this.node.position.x, this._iconsPositionY[index], 0);
        }
        // console.warn(`Invalid index: ${index}`);
        return null;
    }

    public getRowCount(): number {
        return this._rowCount;
    }   

    public adjustHeight(newRowCount: number, duration: number): void {
        // 计算新的高度
        const newHeight = newRowCount * this._iconDistance;

        const uiTransform = this.reelAnchor.getComponent(UITransform);
        if (!uiTransform) {
            // console.error('UITransform component not found on reelAnchor.');
            return;
        }

        // 使用 tween 来创建缓动效果
        tween(uiTransform)
            .to(duration, { height: newHeight }, {
                easing: 'quartOut',
                onUpdate: (target: UITransform, ratio: number) => {
                    // 在每次更新时调整 tiles 的位置
                    this.adjustTilesPosition(newRowCount, ratio);
                }
            })
            .call(() => {
                // 调整完成后，更新 _rowCount
                this._rowCount = newRowCount;
                // 如果需要，可以在这里添加其他逻辑
            })
            .start();
    }

    private adjustTilesPosition(newRowCount: number, ratio: number): void {
        const currentRowCount = this._rowCount + (newRowCount - this._rowCount) * ratio;
        const halfCount = currentRowCount / 2;

        this.tiles.forEach((tile, index) => {
            const newY = (index - halfCount) * this._iconDistance;
            tile.position = v3(tile.position.x, newY, tile.position.z);
        });
    }

    public adjustPositionDuringSpinning(newRowCount: number, duration: number, delayTime: number = 0): void {
        const uiTransform = this.reelAnchor.getComponent(UITransform);
        if (!uiTransform) {
            // console.error('UITransform component not found on reelAnchor.');
            return;
        }
    
        const currentHeight = uiTransform.height;
        const newHeight = newRowCount * this._iconDistance;
        const heightDiff = newHeight - currentHeight;
    
        // console.log(`Adjusting ReelControl position:`, {
        //     currentRowCount: this._rowCount,
        //     newRowCount: newRowCount,
        //     currentHeight: currentHeight,
        //     newHeight: newHeight,
        //     heightDiff: heightDiff,
        //     iconDistance: this._iconDistance
        // });
    
        // 调整 reelAnchor 的高度
        tween(uiTransform)
            .delay(delayTime)
            .to(duration, { height: newHeight }, { easing: 'quartOut' })
            .call(() => {
                // console.log(`ReelAnchor height adjusted:`, {
                //     newHeight: uiTransform.height
                // });
            })
            .start();
    
        // 调整所有 tiles 的位置
        this.tiles.forEach((tile, index) => {
            const currentY = tile.position.y;
            const targetY = currentY + (heightDiff / 2) * (index - (this.tiles.length - 1) / 2) / ((this.tiles.length - 1) / 2);
            
            // console.log(`Adjusting tile ${index}:`, {
            //     currentY: currentY,
            //     targetY: targetY
            // });
    
            tween(tile)
                .delay(delayTime)
                .to(duration, { position: new Vec3(tile.position.x, targetY, tile.position.z) }, { easing: 'quartOut' })
                .call(() => {
                    // console.log(`Tile ${index} position adjusted:`, {
                    //     newPosition: tile.position
                    // });
                })
                .start();
        });
    
        // 更新 _rowCount
        this._rowCount = newRowCount;
    
        // console.log(`ReelControl adjustment complete. New row count:`, this._rowCount);
    }

    public resetToDefaultPosition(): void {
        // 重置 reelAnchor 的高
        const uiTransform = this.reelAnchor.getComponent(UITransform);
        if (uiTransform) {
            const defaultHeight = this._rowCount * this._iconDistance;
            uiTransform.height = defaultHeight;
        }

        // 重置所有 tiles 的位置
        const halfCount = Math.floor(this._rowCount / 2);
        this.tiles.forEach((tile, index) => {
            tile.position = v3(0, (index - halfCount) * this._iconDistance, 0);
        });

        // console.log(`ReelControl reset to default position. Row count: ${this._rowCount}`);
    }

    private readonly MIN_SPIN_TIME: number = 0.5; // 最小旋转时间，单位秒

    private resetTilePositions(): void {
        const tileHeight = this._iconDistance;
        const totalHeight = this._rowCount * tileHeight;
        const centerY = this.node.position.y;
        
        // 计算初始位置，使最下面的tile刚好在可见区域下方
        const startY = centerY - totalHeight / 2 - tileHeight;
        
        this.tiles.forEach((tile, index) => {
            const newY = startY + index * tileHeight;
            tile.position = v3(tile.position.x, newY, tile.position.z);
            // console.log(`[ReelControl] Reset tile ${index} position to: ${newY}`);
        });
    }

    public stopSpin_force(newResult: number[]): void {
        // console.log(`[ReelControl] stopSpin_force started`);
        this.stopStartTime = Date.now();
        // console.log(`[ReelControl] Normal stop started at: ${this.stopStartTime}`);

        this.stopSpinning = true;
        this._reelResult = newResult ? newResult.slice().reverse() : [];

        // 立即停止所有正在进行的动画
        this.reelAnchor.children.forEach((element, index) => {
            Tween.stopAllByTarget(element);
            
            const tileControl = element.getComponent(TileControl);
            if (tileControl) {
                tileControl.isSpinning = false;
            }
        });

        // 添加短暂的过渡动画
        this.smoothStopAnimation(this.stopStartTime);
    }

    private smoothStopAnimation(startTime: number): void {
        const transitionDuration = 0.1; // 过渡动画持续时间，单位秒

        this.tiles.forEach((tile, index) => {
            const tileControl = tile.getComponent(TileControl);
            if (tileControl) {
                // 计算最终位置
                const finalPosition = v3(0, index * this._iconDistance + this._iconDistance/2, 0);
                
                // 创建过渡动画
                tween(tile)
                    .to(transitionDuration, { position: finalPosition }, { easing: 'expoOut' })
                    .call(() => {
                        // 设置最终结果
                        if (this._reelResult[index] !== undefined) {
                            // console.log(`[ReelControl] Setting tile ${index} to: ${this._reelResult[index]}`);
                            tileControl.setTile(this._reelResult[index], false);
                        }
                        if (this._reelScore[index] !== undefined) {
                            // console.log(`[ReelControl] Setting tile ${index} score to: ${this._reelScore[index]}`);
                            tileControl.setScore(this._reelScore[index]);
                        }
                    })
                    .start();
            }
        });

        // 在所有动画完成后触发停止回调
        this.scheduleOnce(() => {
            if (this.onReelStopped) {
                // console.log(`[ReelControl] Reel force stopped`);
                this.onReelStopped();
            }
        }, transitionDuration);

        // 在所有动画完成后触发停止回调并打印时间
        this.scheduleOnce(() => {
            const stopEndTime = Date.now();
            const stopDuration = stopEndTime - startTime;
            // console.log(`[ReelControl] Force stop completed at: ${stopEndTime}`);
            // console.log(`[ReelControl] Force stop duration: ${stopDuration}ms`);

            if (this.onReelStopped) {
                // console.log(`[ReelControl] Reel force stopped`);
                this.onReelStopped();
            }
        }, transitionDuration);
    }

    private stopStartTime: number;

    public stopSpin(newResult: number[], stopInterval: number, stopEasingDuration: number): void {
        this.stopStartTime = Date.now();
        // console.log(`[ReelControl] Normal stop started at: ${this.stopStartTime}`);
        
        // ... 原有的停止逻辑保持不变

        // 在停止动画完成后添加时间打印
        this.scheduleOnce(() => {
            const stopEndTime = Date.now();
            const stopDuration = stopEndTime - this.stopStartTime;
            // console.log(`[ReelControl] Normal stop completed at: ${stopEndTime}`);
            // console.log(`[ReelControl] Normal stop duration: ${stopDuration}ms`);
        }, stopInterval + stopEasingDuration);
    }

    // 修改 playTileSound 方法
    private playTileSound(): void {
        let hasScatter = false;
        let hasQuickHit = false;
        let scatterColumn = -1;

        // 遍历所有的 tile
        for (let i = 0; i < this.tiles.length; i++) {
            const tileControl = this.tiles[i].getComponent(TileControl);
            if (tileControl) {
                const tileId = tileControl.id;
                if (tileId === Scatter_Syboml) {
                    hasScatter = true;
                    scatterColumn = this.columnIndex;
                } else if (tileId === QuickHit_Syboml || tileId === QuickHit_Syboml_Feature) {
                    hasQuickHit = true;
                }
            }
        }

        // 根据找到的特殊符号决定播放哪个音效
        if (hasScatter) {
            let soundEffect = "";
            switch(scatterColumn) {
                case 1:
                    soundEffect = "qhb_bg_ant_1";
                    break;
                case 2:
                    soundEffect = "qhb_bg_ant_2";
                    break;
                case 3:
                    soundEffect = "qhb_bg_ant_3";
                    break;
                default:
                    // 如果在其他列找到 Scatter，可以在这里设置默认音效
                    break;
            }
            if (soundEffect) {
                Utils.playEffectNew(soundEffect);
            }
        } else if (hasQuickHit) {
            Utils.playEffectNew("qhb_fg_blitzland_1");
        }

        // 如果没有特殊符号，可以选择播放默认音效或不播放
        // else {
        //     Utils.playEffectNew("default_tile_sound");
        // }

        // console.log(`[ReelControl] Column ${this.columnIndex}, hasScatter: ${hasScatter}, hasQuickHit: ${hasQuickHit}`);
    }

}
