import { _decorator, CCInteger, EventTouch, Input, instantiate, Node, NodeEventType, Sprite, SpriteFrame, Toggle, ToggleContainer, Tween, Vec3 } from 'cc';
import { UIButton } from '../../../../../scripts/framework/ui/basic_ui/UIButton';
import { ScreenType, UIView } from '../../../../../scripts/framework/ui/UIView';
import GamesData from '../../../../gamesCommon/script/GamesData';
import { ResManager } from '../../../../../scripts/framework/manager/ResManager';
import { Global } from '../../../../../scripts/main/Global';
import { GameEventType } from '../../../../gamesCommon/script/GameEventType';
import { Config, RES } from '../../Config';
import { UIID_GAME } from '../../UIDefined';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { UIManager } from '../../../../../scripts/framework/ui/UIManager';
const { ccclass, property } = _decorator;

@ccclass('HelpController')
export class HelpController extends UIView {

    @property(UIButton)
    private btnClose: UIButton = null;
    @property({ type: UIButton, visible: true })
    private _backBtn: UIButton;
    @property({ type: UIButton, visible: true })
    private _nextBtn: UIButton;
    // @property({ type: UIButton, visible: true })
    // private _returnBtn: UIButton;
    @property(Node)
    private img_help0: Node;
    @property(Node)
    private img_help1: Node;
    @property(Node)
    private node_drag: Node;
    @property(ToggleContainer)
    private toggle: ToggleContainer;
    @property(Node)
    private toggleNode: Node;
    @property(Node)
    private mask: Node;
    @property({ displayName: "pageNum", type: CCInteger, tooltip: "帮助页数量，图片必须命名为：图片获取方式：help+页数（由0开始）+_语言（cn/en)，存放地址：resources/atlas/help/" })
    pageNum: number = 0;

    private _helpPageName: string = "help";
    private _curPage = -1;  //当前页码
    private _nextPage = -1;
    private _moveSpeed = 5000;  //帮助页面移动速度，5000px/s
    private _helpImageSpace = 1280;  //帮助页面间隔
    private _isMoving = false;
    private _isLeft = false;
    // start() {
    // }
    // update(deltaTime: number) {
    // }

    init(...args): void {
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitchClose, this);
        // 竖版不同的说明
        if (Global.gameScreenType == ScreenType.Portrait) {
            this._helpImageSpace = 720;
            Config.helpView = UIID_GAME.HelpView_s
        }
        else {
            this._helpImageSpace = 1280;
            Config.helpView = UIID_GAME.HelpView
        }

        this.toggleNode.name = "Toggle1";
        // this.toggleNode.on(NodeEventType.TOUCH_END, this.onToggle, this);
        if (this.pageNum <= 1) {
            this.toggle.node.active = false;
        }
        else {
            for (let i = 1; i < this.pageNum; i++) {
                let tglNode = instantiate(this.toggleNode);
                tglNode.name = `Toggle${i + 1}`;
                this.toggle.node.addChild(tglNode);
                //   tglNode.on(NodeEventType.TOUCH_END, this.onToggle, this);
            }
        }
        this._changeLanguage();
        this._setPageIndex(0);
        this._onChangePage(false, 0);

        this.addToStage();

    }

    protected onDestroy(): void {
    }

    /**
     * 设置所选页面
     * @param index 索引
     */
    private _setPageIndex(index: number) {
        let toggleArr: Toggle[] = this.toggle.toggleItems;
        let len: number = toggleArr.length;
        for (let i = 0; i < len; i++) {
            if (i == index) {
                toggleArr[i].isChecked = true;
            }
            else {
                toggleArr[i].isChecked = false;
            }
        }
    }

    /**切换页码 */
    private _onChangePage(hasTween: boolean, index: number) {
        if (this._isMoving) {
            return;
        }
        if (this._curPage == index) {
            return;
        }
        this._nextPage = index;

        let mLanguage: string = Global.language;
        let str = Global.gameScreenType == ScreenType.Landscape ? "" : "_s";
        let path = `preload_${mLanguage}/${this._helpPageName}${this._nextPage}_${mLanguage}${str}/spriteFrame`;
        // let path = `resources/atlas/help/${this._helpPageName}${this._nextPage}_${mLanguage}/spriteFrame`;
        ResManager.Instance().load(`${GamesData.gameId}`, path, SpriteFrame, () => { }, (evt: any) => {
            this.img_help1.getComponent(Sprite).spriteFrame = evt.data;
        });
        if (this._nextPage == this.pageNum - 1 || this._nextPage == 0) {

        } else {
            this._isLeft = this._curPage < index;
        }
        this._movePage(hasTween);
    }

    private _touchMove(data: EventTouch) {
        if (this._isMoving) {
            return;
        }

        let start = data.touch.getStartLocation();
        let cur = data.touch.getLocation();
        let distance = cur.subtract(start);
        let distanceSp = 0;
        if (Global.gameScreenType == ScreenType.Portrait) {
            distanceSp = distance.y;
        }
        else {
            distanceSp = distance.x;
        }
        // if (Math.abs(distance.x) > 3) {  //移动距离超过3个像素才认定为滑动
        if (Math.abs(distanceSp) > 3) {  //移动距离超过3个像素才认定为滑动
            this.img_help0.setPosition(new Vec3(distance.x));
            let nextPage = this._curPage;
            let nextPosition = new Vec3();
            // if (distance.x > 0) {  //向右滑动
            if (distanceSp > 0) {  //向右滑动
                nextPage = this._curPage - 1;
                if (nextPage < 0) {
                    nextPage = this.pageNum + nextPage;
                }
                nextPosition = new Vec3(-this._helpImageSpace + distance.x);
                this._isLeft = false;
            }
            else {  //向左滑动
                nextPage = this._curPage + 1;
                if (nextPage >= this.pageNum) {
                    nextPage = 0;
                }
                nextPosition = new Vec3(this._helpImageSpace + distance.x);
                this._isLeft = true;
            }
            if (this._nextPage != nextPage) {
                this._nextPage = nextPage;
                let mLanguage: string = Global.language;
                // let path = `resources/atlas/help/${this._helpPageName}${this._nextPage}_${mLanguage}/spriteFrame`;
                let str = Global.gameScreenType == ScreenType.Landscape ? "" : "_s";
                let path = `preload_${mLanguage}/${this._helpPageName}${this._nextPage}_${mLanguage}${str}/spriteFrame`;
                ResManager.Instance().load(`${GamesData.gameId}`, path, SpriteFrame, () => { }, (evt: any) => { this.img_help1.getComponent(Sprite).spriteFrame = evt.data; });

            }
            this.img_help1.setPosition(nextPosition);
        }
    }

    private _touchEnd(data: EventTouch) {
        if (this._curPage != this._nextPage) {
            this._movePage(true);
        }
    }

    /**
     * 自动滑动页面
     * @param hasTween 是否有动画
     * @param isLeft 是否向左移动
     */
    private _movePage(hasTween = true) {
        this._isMoving = true;
        let help0_endPos = new Vec3(this._helpImageSpace, 0, 0);
        if (this._isLeft) {
            help0_endPos = new Vec3(-this._helpImageSpace, 0, 0);
        }
        let help1_endPos = new Vec3(0, 0, 0);

        if (hasTween) {
            Tween.stopAllByTarget(this.img_help0);
            Tween.stopAllByTarget(this.img_help1);

            let startPos = this.img_help0.getPosition();
            let time = Math.abs(help0_endPos.x - startPos.x) / this._moveSpeed;
            let t1 = new Tween(this.img_help0);
            t1 = t1.to(time, { position: help0_endPos });
            t1 = t1.call(this._moveEnd.bind(this));
            t1.start();

            let help1_startPos = new Vec3(startPos.x - this._helpImageSpace);
            if (this._isLeft) {
                help1_startPos = new Vec3(startPos.x + this._helpImageSpace);
            }
            this.img_help1.setPosition(help1_startPos);
            let t2 = new Tween(this.img_help1);
            t2 = t2.to(time, { position: help1_endPos });
            t2.start();
        }
        else {
            this.img_help0.setPosition(help0_endPos);
            this.img_help1.setPosition(help1_endPos);
            this._moveEnd();
        }
    }

    private _moveEnd() {
        this._isMoving = false;
        //交换两个变量
        let temp = this.img_help0;
        this.img_help0 = this.img_help1;
        this.img_help1 = temp;

        this._curPage = this._nextPage;
        this._setPageIndex(this._curPage);
    }

    private onToggle(event: EventTouch): void {
        let targetTgl: Toggle = event.currentTarget.getComponent(Toggle);
        let index = this.toggle.toggleItems.indexOf(targetTgl);
        if (index == this._curPage) {
            return;
        }
        this._onChangePage(true, index);
    }

    private onBack(target: UIButton): void {
        Config.helpView = 0
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
        this.removeFromStage();
        this.close();
    }
    private onScreenSwitchClose(target: UIButton): void {
        if (Config.helpView > 0) {
            if (Config.helpView == UIID_GAME.HelpView) {
                UIManager.getInstance().open(UIID_GAME.HelpView_s)
                Config.helpView = UIID_GAME.HelpView_s
            } else {
                UIManager.getInstance().open(UIID_GAME.HelpView)
                Config.helpView = UIID_GAME.HelpView
            }
        }
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
        this.removeFromStage();
        this.close();
    }

    protected addToStage() {
        if (this._backBtn) {
            this._backBtn.touchEndedFun = this.onBackClicked.bind(this);
        }
        if (this._nextBtn) {
            this._nextBtn.touchEndedFun = this.onNextClicked.bind(this);
        }
        this.node_drag.on(Input.EventType.TOUCH_MOVE, this._touchMove, this);
        this.node_drag.on(Input.EventType.TOUCH_END, this._touchEnd, this);

        this.mask.on(Input.EventType.TOUCH_END, this.onBack, this);
        this.btnClose.touchEndedFun = this.onBack.bind(this);
    }
    private onBackClicked(): void {
        let nextPage = this._curPage - 1;
        if (nextPage < 0) {
            nextPage = this.pageNum + nextPage;
            this._isLeft = false;
        }
        this._onChangePage(true, nextPage);
    }

    private onNextClicked(): void {
        let nextPage = this._curPage + 1;
        if (nextPage >= this.pageNum) {
            nextPage = 0;
            this._isLeft = true;
        }
        this._onChangePage(true, nextPage);
    }

    protected removeFromStage() {
        this.node_drag.off(Input.EventType.TOUCH_MOVE, this._touchMove, this);
        this.node_drag.off(Input.EventType.TOUCH_END, this._touchEnd, this);
        // this.toggle.node.off(GameEventType.TOGGLE, this.onToggle, this);

        this.btnClose.touchEndedFun = null;
    }

    private _changeLanguage(): void {
        let lang: string = Global.language;
        this._backBtn.node.getComponent(Sprite).spriteFrame = RES.getRes("preload_" + lang + "/back_" + lang + "/spriteFrame");
        this._nextBtn.node.getComponent(Sprite).spriteFrame = RES.getRes("preload_" + lang + "/next_" + lang + "/spriteFrame");
        // if (Global.gameScreenType == ScreenType.Portrait) {
        //     this.btnClose.node.getComponent(Sprite).spriteFrame = RES.getRes("resources/atlas/help/btn_class/spriteFrame");
        // } else {
        //     this.btnClose.node.getComponent(Sprite).spriteFrame = RES.getRes("resources/atlas/help/" + lang + "/return_" + lang + "/spriteFrame");
        // }

    }
}

