import { _decorator, Component, Node, Label, tween, Vec3, Tween } from 'cc';
import { Utils } from '../../utils/Utils';
import { GameEventType } from '../../../../gamesCommon/script/GameEventType';
import { SpinBottomUI } from './SpinBottomUI';
import { SpinRollMenu } from './SpinRollMenu';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { RollCommonModel } from '../../../../rollCommon/script/RollCommonModel';
import { ScreenType } from '../../../../../scripts/framework/ui/UIView';
import { Global } from '../../../../../scripts/main/Global';
import { RollAutoPlay } from '../../../../rollCommon/script/views/RollAutoPlay';

const { ccclass, property } = _decorator;

/** 此类只供参考，具体由具体游戏实现自己写一份 */
@ccclass('SpinBottomView')
export class SpinBottomView extends Component {
    @property(SpinRollMenu)
    public menu: SpinRollMenu;
    @property(SpinBottomUI)
    public bottom: SpinBottomUI;
    @property(Label)
    public tips0: Label;
    @property(Label)
    public tips1: Label;
    @property(Node)
    public tips2Node: Node;
    @property(Label)
    public tips2: Label;
    public isFreeShow;

    @property(Node)
    public win_tips1Node: Node;
    @property(Node)
    public win_tips2Node: Node;
    @property(Node)
    public win_goodLuck: Node;
    @property(Node)
    public win_winTitle: Node;

    private tipTweens: Map<Node, Tween<Node>> = new Map();
    private idleStateSchedule: Function | null = null;
    private secondTipSchedule: Function | null = null;

    private tipMoveSpeed: number = 100;
    private winNodeWidth: number = 700;

    @property(Node)
    public autoPlay: Node;

    @property({
        type: Number,
        displayName: "横竖屏",
        tooltip: "1为横屏 2为竖屏",
    })
    public screenType: Number;

    protected onLoad(): void {
        this.addToStage();
        this.bottom.init();
        // this.autoPlay.node.active = false;
    }

    start() {
        if (this.tips0) {
            this.tips0.node.active = false;
        }
        if (this.tips1) {
            this.tips1.node.active = false;
        }
        if (this.tips2Node) {
            this.tips2Node.active = false;
        }
    }

    protected onDestroy(): void {
        this.removeFromStage();
    }

    public showTips0(isShow: boolean, text?: string) {
        if (this.tips0) {
            this.tips0.node.active = isShow;
            if (isShow) {
                this.tips0.string = text;
            }
        }
    }

    public showTips1(isShow: boolean, text?: string) {
        if (this.tips1) {
            this.tips1.node.active = isShow;
            if (isShow) {
                this.tips1.string = text;
            }
        }
    }

    public showTips2(isShow: boolean, text?: string) {
        if (this.tips2Node) {
            this.tips2Node.active = isShow;
            if (isShow && this.tips2) {
                this.tips2.string = text;
            }
        }
    }

    private onMenuClick() {
        console.log("SpinBottomView onMenuClick");
        this.menu.onMenu();

        // let type = this.screenType == 1 ? ScreenType.Landscape : ScreenType.Portrait;
        // if (Global.gameScreenType == type)
        //     this.menu.onMenu();
    }

    private onAutoClick() {
        this.autoPlay.active = !this.autoPlay.active;
        RollCommonModel.getInstance().isOpenAutoMenu = this.autoPlay.active;
        console.log("RollCommonModel.getInstance().isOpenAutoMenu", RollCommonModel.getInstance().isOpenAutoMenu);
    }

    private onAutoClose() {
        // if (this.autoPlay.node.active)
        //     this.bottom.setAutoCloseNotDisplay();
        // this.autoPlay.node.active = false;
        // RollCommonModel.getInstance().isOpenAutoMenu = false;
    }

    private onBgClose() {
        this.onAutoClose();
    }

    /** 自动spin界面是否打开 */
    isOpenAuto() {
        // return this.autoPlay.node.active;
    }


    protected addToStage() {
        Eventer.getInstance().on(GameEventType.RollMenuClick, this.onMenuClick, this);
        Eventer.getInstance().on(GameEventType.RollAutoPlayClick, this.onAutoClick, this);
        Eventer.getInstance().on(GameEventType.RollCloseAutoPlayMenu, this.onAutoClose, this);
        Eventer.getInstance().on(GameEventType.RollBackgroundClick, this.onBgClose, this);
    }

    protected removeFromStage() {
        Eventer.getInstance().offName(GameEventType.RollMenuClick, this);
        Eventer.getInstance().offName(GameEventType.RollAutoPlayClick, this);
        Eventer.getInstance().offName(GameEventType.RollCloseAutoPlayMenu, this);
        Eventer.getInstance().offName(GameEventType.RollBackgroundClick, this);
    }

    public updateWinState(state: 'idle' | 'spin') {
        console.log(`[SpinBottomView] updateWinState state: ${state}`);
        if (state === 'idle') {
            this.showIdleState();
        } else {
            this.showSpinState();
        }
    }

    private calculateDuration(distance: number): number {
        return distance / this.tipMoveSpeed;
    }

    private showIdleState() {
        this.cancelAllAnimationsAndSchedules();

        this.idleStateSchedule = () => {
            this.win_goodLuck.active = false;
            this.win_winTitle.active = false;

            this.animateTip(this.win_tips1Node);
            
            const duration = this.calculateDuration(this.winNodeWidth);

            this.secondTipSchedule = () => {
                this.animateTip(this.win_tips2Node);
                this.secondTipSchedule = null;
            };
            this.scheduleOnce(this.secondTipSchedule, duration);

            this.idleStateSchedule = null;
        };
        this.scheduleOnce(this.idleStateSchedule, 5);
    }

    public hideSpinState() {
        this.cancelAllAnimationsAndSchedules();

        this.win_tips1Node.active = false;
        this.win_tips2Node.active = false;

        this.win_goodLuck.active = false;
        this.win_winTitle.active = true;
    }

    private showSpinState() {
        this.cancelAllAnimationsAndSchedules();

        this.win_tips1Node.active = false;
        this.win_tips2Node.active = false;

        this.win_goodLuck.active = true;
        this.win_winTitle.active = false;

        this.scheduleOnce(() => {
            this.win_winTitle.active = true;
            this.win_goodLuck.active = false;
        }, 2);
    }

    private cancelAllAnimationsAndSchedules() {
        if (this.idleStateSchedule !== null) {
            this.unschedule(this.idleStateSchedule);
            this.idleStateSchedule = null;
        }
        if (this.secondTipSchedule !== null) {
            this.unschedule(this.secondTipSchedule);
            this.secondTipSchedule = null;
        }

        this.tipTweens.forEach((tween, node) => {
            tween.stop();
            node.active = false;
            node.setPosition(new Vec3(this.winNodeWidth, 0, 0)); // Reset position
        });
        this.tipTweens.clear();
    }

    private animateTip(tipNode: Node) {
        tipNode.active = true;
        tipNode.setPosition(new Vec3(this.winNodeWidth, 5, 0));

        const endX = -this.winNodeWidth;
        const duration = this.calculateDuration(this.winNodeWidth * 2);

        const newTween = tween(tipNode)
            .to(duration, { position: new Vec3(endX, 5, 0) })
            .call(() => {
                tipNode.setPosition(new Vec3(this.winNodeWidth, 5, 0));
                this.animateTip(tipNode);
            })
            .start();

        this.tipTweens.set(tipNode, newTween);
    }
    
}
