import { _decorator, Label, Node, NodeEventType, Sprite } from 'cc';
import { ScreenType, UIView } from '../../../../../scripts/framework/ui/UIView';
import { UIButton } from '../../../../../scripts/framework/ui/basic_ui/UIButton';
import { GameEventType } from '../../../../gamesCommon/script/GameEventType';
import i18n from '../../../../../scripts/framework/language/i18n';
import { Global } from '../../../../../scripts/main/Global';
import { GameComUtils } from '../../../../gamesCommon/script/utils/GameComUtils';
import { StatConst } from '../../../../gamesCommon/script/stat/StatConst';
import AudioManager from '../../../../../scripts/framework/manager/AudioManager';
import { Eventer } from '../../../../../scripts/framework/Eventer';



const { ccclass, property } = _decorator;

@ccclass('GameSettingPanel')
export class GameSettingPanel extends UIView {

    @property({ type: Node, visible: true })
    private _touchNode: Node;
    @property({ type: Node, visible: true })
    private _musicBtnGroup: Node;
    @property({ type: Node, visible: true })
    private _soundBtnGroup: Node;
    @property(Label)
    LabelBgMusic: Label
    @property(Label)
    LabelSoundEffect: Label

    @property({ type: Node, visible: true })
    private spiteBgL: Node;
    @property({ type: Node, visible: true })
    private spiteBgR: Node;

    private _musicBtn: UIButton;
    private _soundBtn: UIButton;
    private _returnBtn: UIButton;

    start() {
        // Rotate spiteBgR 180 degrees around the z-axis
        this.spiteBgR.setRotationFromEuler(0, 180, 0);
    }

    onLoad() {

    }

    public onOpen(): void {
        this._musicBtn = this._musicBtnGroup.getChildByName("checkBtn").getComponent(UIButton);
        this._soundBtn = this._soundBtnGroup.getChildByName("checkBtn").getComponent(UIButton);
        this._returnBtn = this.node.getChildByName("return").getComponent(UIButton);

        this._musicBtn.touchEndedFun = this.onClicked.bind(this, GameEventType.BackgroundMusic);
        this._soundBtn.touchEndedFun = this.onClicked.bind(this, GameEventType.SoundEffect);
        this._returnBtn.touchEndedFun = this.onClicked.bind(this, GameEventType.Return);

        this.LabelBgMusic.string = i18n.tr(3001002)
        this.LabelSoundEffect.string = i18n.tr(3001003)

        this._touchNode.on(NodeEventType.TOUCH_END, this.onTouch, this);

        this.screenSwitch();
        this.setCheckState();
        this.addToStage();
    }

    private screenSwitch(): void {
        if (Global.gameScreenType == ScreenType.Landscape) {
            this.node.angle = 0;
        } else {
            this.node.angle = 90;
        }
    }
    private onClicked(type: string): void {
        switch (type) {
            case "BackgroundMusic":
                GameComUtils.c2sStat(StatConst.BGM_TIMES);
                Global.backgroundMusic = !Global.backgroundMusic;
                if (Global.backgroundMusic) {
                    this.playMusic();
                }
                else {
                    this.stopMusic();
                }
                break;
            case "SoundEffect":
                GameComUtils.c2sStat(StatConst.SOUND_TIMES);
                Global.soundEffect = !Global.soundEffect;
                if (Global.soundEffect) {
                    this.playSound();
                }
                else {
                    this.stopSound();
                }
                break;
            case "Return":
                this.close();
                break;
        }
        this.setCheckState();
    }

    private setCheckState(): void {
        this._musicBtn.getComponent(Sprite).enabled = Global.backgroundMusic;
        this._soundBtn.getComponent(Sprite).enabled = Global.soundEffect;
    }

    /**
   * playMusic 用于开关背景音乐和音效的
   */
    private playMusic() {
        Global.backgroundMusic = true;
        AudioManager.Instance().setMusicEnabled(true);
        // AudioManager.Instance().musicEnabled = true;
        AudioManager.Instance().musicOn();
        // if (!GamesData.musicInfo) { return; }
        // AudioManager.Instance().playMusic(GamesData.musicInfo.url, GamesData.musicInfo.bundleName);
    }
    /** 
     * stopMusic 用于开关背景音乐和音效的
    */
    private stopMusic() {
        Global.backgroundMusic = false;
        AudioManager.Instance().setMusicEnabled(false);
        AudioManager.Instance().musicOff();
    }

    /**
   * playMusic 用于开关背景音乐和音效的
   */
    private playSound() {
        AudioManager.Instance().setSoundEnabled(true);
        // AudioManager.Instance().musicOn();
        AudioManager.Instance().pauseAllSound = false;
    }
    /** 
     * stopMusic 用于开关背景音乐和音效的
    */
    private stopSound() {
        AudioManager.Instance().setSoundEnabled(false);
        // AudioManager.Instance().audioSource.stop();
        // AudioManager.Instance().musicOff();
        AudioManager.Instance().pauseAllSound = true;
    }

    private onTouch(evt) {
        // this._touchNode.off(NodeEventType.TOUCH_END, this.onTouch, this); //防止隐藏过程中再次点击
        this.close();
    }

    private addToStage() {
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.screenSwitch, this);
    }

    protected onDestroy(): void {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }
}