import { Node, SliderJoint2D, sp, _decorator } from "cc";

const { ccclass, property } = _decorator;

export class SpineUtility {

    /** 添加skeleton组件 */
    public initSpine(node: Node): void {
        node?.addComponent(sp.Skeleton);
    }

    /** 删除skeleton组件 */
    public clearSpine(node: Node): void {
        node?.getComponent(sp.Skeleton).destroy();
    }

    public setSpineData(node: Node, data: sp.SkeletonData): void {
        if (node) {
            node.getComponent(sp.Skeleton).skeletonData = data;
        }
    }

    public playSpine(node: Node, key: string, loop: boolean): void {
        if (node) {
            let ske = node.getComponent(sp.Skeleton);
            if (!ske) {
                ske = node.addComponent(sp.Skeleton);
            }
            ske.setAnimation(0, key, loop);
        }
    }

    public stopSpine(node: Node): void {
        if (node) {
            let ske = node.getComponent(sp.Skeleton);
            if (!ske) {
                return;
            }
            ske.clearTrack(0);
            ske.setCompleteListener(null);
        }
    }

    public setCompletetd(node: Node, callback: Function, thisArg: any): void {
        node?.getComponent(sp.Skeleton).setCompleteListener(callback.call(thisArg));
    }
}
export default new SpineUtility;