import LogUtil from "../../../../scripts/common/utils/LogUtil";
import { Singleton } from "../../../../scripts/framework/Singleton";
import { GameEventType } from "../../../gamesCommon/script/GameEventType";
import GameSocketManager, { C2S_ProtocolParams, S2C_ProtocolParams } from "../../../gamesCommon/script/gameSocket/GameSocketManager";
import { FeatureMap, MapData } from "../GameDataDefine";
import { Utils } from "../utils/Utils";
import { Protocol, SlotBetVo_c2s, SlotBetVo_s2c, LastMapVo_s2c, FreeSpinVo_c2s } from "./Protocol";


export enum GameType {
    None = 0,
    Normal,
    Feature,
    Special
}

export class ServerProxy extends Singleton<ServerProxy>() {
    private _baseMap: MapData[] = [];
    private _featureMap: FeatureMap[] = [];
    private _bet: number = 0;
    private _win: number = 0;
    /** 游戏中断-游戏类型 */
    private _type: number = 0;
    private _recovery: LastMapVo_s2c;
    private _currentFeatureIndex: number = 0;
    private _lastProcessedMessageId: string | number = null;
    private _lastProcessedMessageTime: number = 0;
    private readonly MESSAGE_THRESHOLD_MS: number = 50; // 50毫秒的时间阈值

    public get connected() {
        return this.socket != null && this.socket.isConnect;
    }

    public get socket() {
        return GameSocketManager.getInstance();
    }

    public getRecovery() {
        return this._recovery;
    }

    public registerMsgMap() {
        this.socket.registerMsgListener<S2C_ProtocolParams<SlotBetVo_s2c>>(Protocol.SLOTBET, this._s2cSlotBet, this);
        this.socket.registerMsgListener<S2C_ProtocolParams<SlotBetVo_s2c>>(Protocol.SLOT_BUY, this._s2cSlotBet, this);
        this.socket.registerMsgListener<S2C_ProtocolParams<LastMapVo_s2c>>(Protocol.LAST_MAP, this._s2cLastMap, this);
    }

    public destroy() {
        this._baseMap = null;
        this._featureMap = null;
        this.socket.unregisterMsgListener(Protocol.SLOTBET, this);
        this.socket.unregisterMsgListener(Protocol.SLOT_BUY, this);
    }

    /**
     * 发送数据包
     * @param code 协议编码
     * @param msg json格式数据包，服务端解析有顺序，注意参数顺序
     * @returns
     */
    public sendPack(code: string, msg: any) {
        this.socket.sendMessage<C2S_ProtocolParams>(code, msg);
    }


    /*____________游戏协议____________ */
    /**
     * 发送押注消息
     * @param msg 单线押注数量
     */
    public c2sSlotBet(msg: SlotBetVo_c2s) {
        let msgObj: C2S_ProtocolParams<SlotBetVo_c2s> = {
            type: Protocol.SLOTBET,
            message: msg
        }

        this.sendPack(Protocol.SLOTBET, msgObj);
    }

    /**
   * 购买免费
   * @param msg 单线押注数量
   */
    public c2sSlotBuy(msg: SlotBetVo_c2s) {
        let msgObj: C2S_ProtocolParams<SlotBetVo_c2s> = {
            type: Protocol.SLOT_BUY,
            message: msg
        }

        this.sendPack(Protocol.SLOT_BUY, msgObj);
    }
    public getBandFTimes() {
        // Log.w("ggg", this._baseMap)
        return this._baseMap.length + this._featureMap.length;
    }
    /**
        * 断线重连
        */
    private _s2cLastMap(data: S2C_ProtocolParams<LastMapVo_s2c>) {
        LogUtil.log("_s2cLastMap Received last map data:", data);

        let message = data.message;
        this._baseMap = message.base || [];
        this._featureMap = message.feature || [];
        this._bet = message.bet || 0;
        this._win = message.win || 0;

        this._recovery = message;

        LogUtil.log("Parsed last map data - Base maps:", this._baseMap.length, "Feature maps:", this._featureMap.length, "Bet:", this._bet, "Win:", this._win);

        Utils.event.emit(GameEventType.RollLastMap, {
            baseMap: this._baseMap,
            featureMap: this._featureMap,
            bet: this._bet,
            win: this._win
        });
    }


    //免费旋转次数（免费游戏转一次发一次）
    public c2sFreeSpin(msg: FreeSpinVo_c2s): void {
        LogUtil.debug("c2sFreeSpin xxx发送")
        let msgObj: C2S_ProtocolParams<FreeSpinVo_c2s> = {
            type: Protocol.FREESPIN,
            message: msg
        }
        this.sendPack(Protocol.FREESPIN, msgObj);
    }
    /**
     * 收到押注信息
     */
    private _s2cSlotBet(data: S2C_ProtocolParams<SlotBetVo_s2c>) {
        const currentTime = Date.now();
        const messageId = data.type;
        console.log("===_s2cSlotBet messageId===", messageId, currentTime);

        // 检查消息ID和时间戳
        if (this._lastProcessedMessageId === messageId && 
            (currentTime - this._lastProcessedMessageTime) < this.MESSAGE_THRESHOLD_MS) {
            LogUtil.warn("Duplicate message received and ignored:", messageId);
            return;
        }

        // 更新最后处理的消息ID和时间戳
        this._lastProcessedMessageId = messageId;
        this._lastProcessedMessageTime = currentTime;

        LogUtil.log("_s2cSlotBet Received slot bet data:", data);

        let message = data.message;
        this._baseMap = message.base || [];
        this._featureMap = message.feature || [];
        this._currentFeatureIndex = 0; // Reset the index when receiving new data
        
        // 可以在这里添加额外的数据处理逻辑
        // 例如，计算总奖励等
        let totalReward = message.reward || 0;

        LogUtil.log("Parsed slot bet data - Base maps:", this._baseMap.length, "Feature maps:", this._featureMap.length, "Total reward:", totalReward);

        Utils.event.emit(GameEventType.OnReceiveBet, {
            baseMap: this._baseMap,
            featureMap: this._featureMap,
            reward: totalReward
        });
    }

    /**取当前牌面值 */
    public getMapData(type: GameType): MapData {
        let map: MapData;
        LogUtil.debug("getMapData type:", type);
        switch (type) {
            case GameType.Normal:
                if (!this._baseMap || this._baseMap.length == 0) {
                    return null;
                }
                map = this._baseMap.shift();
                break;
            case GameType.Feature:
                if (!this._featureMap || this._featureMap.length == 0 || this._currentFeatureIndex >= this._featureMap.length) {
                    // Feature模式结束
                    Utils.event.emit(GameEventType.QuickHitFeatureEnd, this._win);
                    return null;
                }
                map = this._featureMap[this._currentFeatureIndex];
                // Replace all occurrences of 10 with 11 in the map
                if (map && map.map) {
                    map.map = map.map.map(element => element === 10 ? 11 : element);
                }
                this._currentFeatureIndex++;
                LogUtil.debug("getMapData this._currentFeatureIndex:", this._currentFeatureIndex);
                LogUtil.debug("getMapData this._featureMap[this._currentFeatureIndex]:", map);
                break;
            default: break;
        }
        return map;
    }


    /**取前一个牌面值 */
    public getLastMapData(type: GameType): MapData {
        let map: MapData;
        LogUtil.debug("getLastMapData type:", type);
        switch (type) {
            case GameType.Normal:
                break;
            case GameType.Feature:
                if (!this._featureMap || this._featureMap.length == 0 || this._currentFeatureIndex > this._featureMap.length) {
                    return null;
                }
                map = this._featureMap[this._currentFeatureIndex-1];
                // Replace all occurrences of 10 with 11 in the map
                if (map && map.map) {
                    map.map = map.map.map(element => element === 10 ? 11 : element);
                }
                LogUtil.debug("getLastMapData map:", map);
                break;
            default: break;
        }
        return map;
    }

    public getMapLenth(type: GameType): number {
        let len = 0;
        switch (type) {
            case GameType.Normal:
                if (!this._baseMap || this._baseMap.length == 0) {
                    return null;
                }
                len = this._baseMap.length;
                break;
            case GameType.Feature:
                if (!this._featureMap || this._featureMap.length == 0) {
                    return null;
                }
                len = this._featureMap.length - this._currentFeatureIndex;
                break;
            default: break;
        }
        return len;
    }

    java2cPlayback() {
        Log.d('java2cPlayback Start Replay');
        // Global.playbackFinish = false;
        // let vo = GameUtils.copyTab(Global.playbackVo);
        // this._baseMap = vo.gameRes.base;
        // this._featureMap = vo.gameRes.free;
        Utils.event.emit(GameEventType.OnReceiveBet);
    }

    
    /** 获取游戏中断-游戏类型 */
    public get type(): number {
        return this._type;
    }

    public get baseMaps(): MapData[] {
        return this._baseMap;
    }

    public get featureMaps(): FeatureMap[] {
        return this._featureMap;
    }

    public get bet(): number {
        return this._bet;
    }

    public get win(): number {
        return this._win;
    }
}
