            Log.d(Config.logTag, `openGameView game 320000101!!!!!!`);
            UIManager.getInstance().setUIConf(UICF);
            UIManager.getInstance().open(UIID_GAME.MainView);
            BundleManager.getInstance().getBundle(this.bundle).loadDir(`preload_${Global.language}`);
