export class StateMachine {
    private _locked: boolean = false;
    private _curState: number = Infinity;
    private _stateDic: { [key: number]: StateAction } = {};

    public get locked() {
        return this._locked;
    }

    public set locked(value: boolean) {
        this._locked = value;
    }

    public get state(): number {
        return this._curState;
    }

    public get stateAction(): StateAction {
        return this._stateDic[this._curState];
    }

    public get thisArg(): any {
        return this._stateDic[this._curState].listener;
    }
    
    /** 立刻切换状态 */
    public set state(key: number) {
        if (this.contains(key)) {
            if (this._locked || this._curState == key) return;
            this.stateAction?.onExit?.call(this.thisArg);
            this._curState = key;
            this.stateAction?.onEnter?.call(this.thisArg);
        }
    }

    public constructor(){
        this._stateDic = {};
    }

    public setCallbacks(thisArg: any, key: number, enter?: Function, update?: Function, exit?: Function): void {
        this._stateDic[key] = new StateAction(thisArg, enter, update, exit);
    }

    public updateState(): void {
        this.stateAction?.onUpdate?.call(this.thisArg);
    }

    private contains(state: number): boolean {
        return state in this._stateDic;
    }

    public reset(): void {
        this._locked = true;
        this._curState = Infinity;
        this._stateDic = null;
        Log.d("machine reset")
    }
}

class StateAction {
    listener: any;
    onEnter: Function;
    onUpdate: Function;
    onExit: Function;

    constructor(listener: any, enter: Function, update: Function, exit: Function) {
        this.listener = listener;
        this.onUpdate = update;
        this.onEnter = enter;
        this.onExit = exit;
    }
}
